insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '816e0590-7d39-5246-a37b-45e5a2027bab', (select id from public.topics where programme = 'IB DP' and code = 'A1.1' limit 1), 'Water: Polarity, Hydrogen Bonding, Cohesion and Adhesion', 'A1.1 Water · Lesson 1 · SL and HL', '/a11-lesson1/', 'DP1-A1.1-L1', 52, 11 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-A1.1-L1', 'Water: Polarity, Hydrogen Bonding, Cohesion and Adhesion', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "1", "max": 2, "pts": [["ocean", "sea", "water"], ["solution", "dissolv", "ultraviolet", " uv ", "radiation", "stable temperature", "temperature changes slowly", "temperature change slowly", "stable", "concentrat", "brought together"]], "tips": ["Say where the first cells originated.", "Give one reason: think reactions in solution, UV protection or stable temperature."]}, {"kind": "text", "id": "q1_1", "q": "2", "max": 4, "pts": [["solvent", "dissolv"], ["liquid over", "liquid at", "range of temperature", "temperatures at which", "stays liquid", "is liquid"], ["specific heat", "energy to heat", "heat capacity", "temperature stable", "stable temperature", "resists", "slowly"], ["reactant", "photosynthesis", "hydrolysis"], ["ice floats", "ice is less dense", "less dense", "insulat", "floats"], ["cohesion", "xylem", "transparent", "light"]], "tips": ["Choose four DIFFERENT properties, each with property → consequence: solvent, liquid range, heat capacity, reactant, ice floats, cohesion, transparency."]}], "2": [{"kind": "rows", "id": "q2_0", "q": "3", "tip": "Check the notes: which particles are in the nucleus, and what charge does each carry?", "rows": [{"label": "Proton", "sel": ["in the nucleus", "+1"], "pts": []}, {"label": "Neutron", "sel": ["in the nucleus", "0"], "pts": []}, {"label": "Electron", "sel": ["in shells around the nucleus", "−1"], "pts": []}]}, {"kind": "text", "id": "q2_1", "q": "4(a)", "max": 2, "pts": [["transfer", "gives", "gains", "loses", "donat", "lost", "gained"], ["opposite charge", "attract", "cation", "anion", "positive ion", "negative ion"]], "tips": ["Say what happens to the electron.", "Say what forms and what holds the ions together."]}, {"kind": "text", "id": "q2_2", "q": "4(b)", "max": 2, "pts": [["shar"], ["both nuclei", "pair", "each contribute", "one electron each", "attracted to both", "full outer shell", "two covalent", "two bonds", "needs two"]], "tips": ["Say what the atoms do with their electrons.", "Say what holds the atoms together, or why oxygen forms two bonds."]}, {"kind": "text", "id": "q2_3", "q": "5(a)", "max": 1, "pts": [["o h", "oxygen and hydrogen", "oxygen and each hydrogen", "oxygen and the hydrogen", "between the oxygen", "hydrogen and oxygen"]], "tips": ["Name the two atoms each bond joins."]}, {"kind": "text", "id": "q2_4", "q": "5(b)", "max": 3, "pts": [["electronegativ", "attracts the shared electrons more", "attracts electrons more", "more strongly", "stronger pull", "pulls the electrons", "attracts the electrons"], ["closer to the oxygen", "nearer the oxygen", "near the oxygen", "nearer to oxygen", "closer to oxygen", "oxygen+partial negative", "oxygen+slightly negative"], ["hydrogen+partial positive", "hydrogen+slightly positive", "bent", "do not cancel", "don t cancel"]], "tips": ["Say which atom attracts the shared electrons more strongly.", "Say where the electrons spend more time, and the charge that gives oxygen.", "Say the charge on each hydrogen, and why the molecule is polar (bent shape)."]}, {"kind": "choice", "id": "q2_5", "q": "5(c)", "max": 2, "n": 3, "ans": ["Bent (V-shaped)", "δ− (partial negative)", "δ+ (partial positive)"], "tip": "A water molecule is bent, with δ− on the oxygen and δ+ on each hydrogen. Correct your drawing."}, {"kind": "text", "id": "q2_6", "q": "6(a)", "max": 2, "pts": [["partial positive", "slightly positive", "positive hydrogen"], ["partial negative", "slightly negative", "negative oxygen", "neighbouring", "another water", "other molecule", "another molecule"]], "tips": ["Name the charge on the hydrogen involved.", "Say what it is attracted to, on which molecule."]}, {"kind": "text", "id": "q2_7", "q": "6(b)", "max": 2, "pts": [["liquid", "specific heat", "heat capacity", "energy to heat", "latent heat", "evaporat"], ["cohesion", "surface tension", "xylem", "column", "ice", "tension"]], "tips": ["One consequence about heat or water being liquid.", "One consequence about cohesion, surface tension, xylem or ice."]}], "3": [{"kind": "text", "id": "q3_0", "q": "7", "max": 1, "pts": [["same substance", "same type", "water molecules to each other", "between water molecules", "water to water", "like molecules", "each other"]], "tips": ["Cohesion is attraction between molecules of the SAME substance."]}, {"kind": "text", "id": "q3_1", "q": "8", "max": 4, "pts": [["root", "soil"], ["transpiration", "evaporat", "stomata"], ["tension", "pull", "suction"], ["cohesion", "continuous", "column", "hydrogen bond"], ["adhesion", "xylem wall", "walls"]], "tips": ["Write it as a sequence: root → xylem → transpiration → tension → cohesion and adhesion."]}, {"kind": "text", "id": "q3_2", "q": "9(a)", "max": 2, "pts": [["no water above", "nothing above", "at the surface", "surface molecules", "top layer"], ["sideways", "downward", "inward", "pulled together", "all directions", "hydrogen bond", "cohesion"]], "tips": ["Say what is different about a molecule at the surface.", "Say which way surface molecules are pulled, and by what."]}, {"kind": "text", "id": "q3_3", "q": "9(b)", "max": 1, "pts": [["pond skater", "insect", "invertebrate", "walk on", "stand on", "move on", "live on", "surface"]], "tips": ["Think of animals that live on the surface of a pond."]}], "4": [{"kind": "text", "id": "q4_0", "q": "10", "max": 3, "pts": [["different substance", "other substance", "another substance", "different molecule", "other surface", "another surface", "different surface", "different material"], ["uneven", "unequal", "partial", "slightly positive", "slightly negative"], ["gained or lost", "lost or gained", "gained", "lost", "full charge", "charged atom", "full electrical charge"]], "tips": ["Adhesion: water attracted to what?", "Polar: how is the charge spread?", "Ion: what has happened to its electrons?"]}, {"kind": "text", "id": "q4_1", "q": "11", "max": 2, "pts": [["cation+positive", "cation+lost"], ["anion+negative", "anion+gained"]], "tips": ["State the charge of a cation and how it formed.", "State the charge of an anion and how it formed."]}, {"kind": "text", "id": "q4_2", "q": "12", "max": 2, "pts": [["water is polar", "polar", "partial"], ["partial negative oxygen", "oxygen+positive", "hydrogen+negative", "opposite charge", "opposite"]], "tips": ["Start from water being polar.", "Say which part of water is attracted to which charge."]}, {"kind": "text", "id": "q4_3", "q": "13(a)", "max": 2, "pts": [["adhesion"], ["cohesion"]], "tips": ["Name the force that pulls water along the wall.", "Name the force that drags the rest of the column up. Capillary action needs both."]}, {"kind": "text", "id": "q4_4", "q": "13(b)", "max": 2, "pts": [["xylem", "cell wall", "narrow"], ["adhe", "cellulose", "lignin", "cohesion", "pull"]], "tips": ["Name where it happens in the plant.", "Say what water sticks to and how the column follows."]}, {"kind": "text", "id": "q4_5", "q": "13(c)", "max": 2, "pts": [["narrow", "spaces", "adhe", "particles"], ["upward", "upwards", "below", "roots", "root hair", "surface", "evaporat", "deeper"]], "tips": ["Cause: what are the spaces between soil particles like, and what does water stick to?", "Effect: where does the water move to?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "14", "max": 4, "pts": [["shared electrons", "electronegativ", "more strongly", "unequal"], ["partial positive+partial negative", "slightly positive+slightly negative"], ["hydrogen bond"], ["cohesion"], ["adhesion"]], "tips": ["Polarity → hydrogen bond → cohesion (water to water) → adhesion (water to other polar surfaces)."]}, {"kind": "text", "id": "q5_1", "q": "15", "max": 4, "pts": [["evaporat", "stomata"], ["transpiration+tension", "transpiration+pull"], ["cohesion"], ["adhesion"], ["continuous", "column", "does not break", "without breaking"]], "tips": ["Transpiration creates tension; cohesion holds the column; adhesion attaches it to the xylem walls."]}]}, "models": {"1": [["1", "The first cells originated in oceans or other bodies of water. Reason: reactions can happen in solution / water absorbs harmful UV radiation / large bodies of water have stable temperatures / dissolved substances are brought together."], ["2", "Any four, each linked to a consequence: good solvent → reactions and transport happen in solution; liquid over a wide temperature range → organisms can live across those temperatures; high specific heat capacity → stable cell and habitat temperatures; high cohesion → water columns in xylem, surface tension; reactant → used in photosynthesis and hydrolysis; transparent → aquatic producers can photosynthesise; ice less dense than water → ice floats and insulates the water below."]], "2": [["3", "Proton: in the nucleus, +1. Neutron: in the nucleus, 0. Electron: in shells around the nucleus, −1. One mark per fully correct row."], ["4(a)", "Sodium transfers its one outer electron to chlorine, so both have full outer shells; sodium becomes a positive ion (Na⁺, cation) and chlorine a negative ion (Cl⁻, anion); the attraction between the opposite charges is the ionic bond."], ["4(b)", "Oxygen and hydrogen each contribute one electron to a shared pair; the shared pair is attracted to both nuclei, holding the atoms together (oxygen forms two such bonds because it needs two more electrons)."], ["5(a)", "In the two O–H bonds, between the oxygen atom and each hydrogen atom."], ["5(b)", "Oxygen is more electronegative and attracts the shared electrons more strongly, so they spend more time nearer the oxygen; oxygen becomes partially negative (δ−) and each hydrogen partially positive (δ+); because the molecule is bent, the charges do not cancel, so water is polar."], ["5(c)", "Bent (V-shaped) molecule: one oxygen, two hydrogens, two O–H covalent bonds; δ− on the oxygen and δ+ on each hydrogen."], ["6(a)", "The δ+ hydrogen of one water molecule is attracted to the δ− oxygen of a neighbouring water molecule; this electrostatic attraction between molecules is a hydrogen bond."], ["6(b)", "Any two: water is liquid at temperatures suitable for life; high specific heat capacity; high latent heat of vaporisation; strong cohesion holds water columns in xylem; high surface tension; ice is less dense and floats."]], "3": [["7", "The attraction between molecules of the same substance; in water, caused by hydrogen bonding between water molecules."], ["8", "Water is absorbed from the soil by root hair cells and passes into the xylem; it evaporates from mesophyll cells and leaves through the stomata (transpiration); this creates tension at the top of the column; cohesion holds the molecules together so the continuous column is pulled up without breaking; adhesion to the xylem walls helps."], ["9(a)", "A molecule inside the liquid is attracted equally in all directions; a molecule at the surface has no water above it, so it is pulled sideways and downwards; surface molecules are drawn together into a layer that resists being broken."], ["9(b)", "Small organisms such as pond skaters can stand and move on the water surface without sinking."]], "4": [["10", "Adhesion: attraction between water and a different substance. Polar: a molecule with an uneven distribution of charge (slightly positive and slightly negative regions). Ion: an atom or group of atoms that has gained or lost electrons and carries a full charge."], ["11", "A cation has lost electrons and is positively charged (e.g. Na⁺); an anion has gained electrons and is negatively charged (e.g. Cl⁻); both are ions and both attract water."], ["12", "Water is polar (δ− oxygen, δ+ hydrogens); the δ− oxygen is attracted to positive charges and the δ+ hydrogens to negative charges, so water is attracted to polar or charged molecules and surfaces."], ["13(a)", "Adhesion attracts water to the wall of a narrow tube and draws it along; cohesion pulls the rest of the water column up behind it; the narrower the tube, the higher the water rises."], ["13(b)", "Xylem vessels are very narrow; water adheres to the cellulose and lignin walls and is drawn upward while cohesion pulls the column behind it; the same process moves water through the cell walls of leaf mesophyll cells to the evaporating surfaces."], ["13(c)", "Cause: spaces between soil particles are narrow and water adheres to their charged/polar surfaces, drawing it through. Effect: water moves upwards from deeper soil towards the roots (or to the surface in dry weather, where it evaporates)."]], "5": [["14", "Oxygen attracts the shared electrons more strongly, so water is polar (δ− oxygen, δ+ hydrogens); the δ+ hydrogen of one molecule is attracted to the δ− oxygen of another, forming a hydrogen bond; hydrogen bonding between water molecules causes cohesion; the partial charges also attract water to other polar or charged surfaces: adhesion."], ["15", "Water evaporates from mesophyll cells and leaves through stomata (transpiration); this creates tension (a pull) at the top of the xylem; cohesion (hydrogen bonds) holds the molecules together so the column is pulled up without breaking; adhesion to the xylem walls helps support the column against gravity."]]}, "labels": {"q1_0": "1", "q1_1": "2", "q2_1": "4(a)", "q2_2": "4(b)", "q2_3": "5(a)", "q2_4": "5(b)", "q2_6": "6(a)", "q2_7": "6(b)", "q3_0": "7", "q3_1": "8", "q3_2": "9(a)", "q3_3": "9(b)", "q4_0": "10", "q4_1": "11", "q4_2": "12", "q4_3": "13(a)", "q4_4": "13(b)", "q4_5": "13(c)", "q5_0": "14", "q5_1": "15", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'd534d2d6-4864-5bae-8655-d86cf491927e', (select id from public.topics where programme = 'IB DP' and code = 'A1.1' limit 1), 'Water: Solvent Properties, and Water Compared with Air', 'A1.1 Water · Lesson 2 · SL and HL', '/a11-lesson2/', 'DP1-A1.1-L2', 45, 12 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-A1.1-L2', 'Water: Solvent Properties, and Water Compared with Air', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "1", "max": 3, "pts": [["electronegativ", "more strongly", "attracts the shared electrons", "unequal", "attracts electrons"], ["partial negative", "partial positive", "slightly negative", "slightly positive", "bent"], ["hydrogen bond+another", "hydrogen bond+neighbour", "hydrogen bond+other", "attracted to the oxygen", "attracted to the partial negative"]], "tips": ["Why are the electrons shared unequally?", "Which partial charges result?", "What attracts what to form a hydrogen bond between molecules?"]}, {"kind": "text", "id": "q1_1", "q": "2", "max": 4, "pts": [["cohesion+water molecules", "cohesion+same", "cohesion+each other"], ["adhesion+other", "adhesion+different", "adhesion+wall", "adhesion+surface"], ["column", "continuous", "transpiration", "pulled up", "surface tension"], ["capillary", "wall", "gravity", "stick"]], "tips": ["Define cohesion.", "Define adhesion.", "Consequence of cohesion (continuous column pulled up).", "Consequence of adhesion (sticks to xylem walls, capillary action)."]}], "2": [{"kind": "rows", "id": "q2_0", "q": "3", "tip": "Each row needs the right choice AND a reason about polarity or charge.", "rows": [{"label": "Glucose", "sel": ["hydrophilic"], "pts": [["polar", " oh ", "hydroxyl", "hydrogen bond"]]}, {"label": "Sodium chloride (ions)", "sel": ["hydrophilic"], "pts": [["charge", "ion", "hydration shell"]]}, {"label": "Amino acids", "sel": ["hydrophilic"], "pts": [["charge", "polar", "nh2", "cooh", "amine", "carboxyl"]]}, {"label": "Lipids / fats", "sel": ["hydrophobic"], "pts": [["non polar", "nonpolar", "not polar", "hydrocarbon", "cannot form hydrogen", "no hydrogen bond", "uncharged"]]}, {"label": "Oxygen gas (O₂)", "sel": ["hydrophobic"], "pts": [["non polar", "nonpolar", "not polar", "uncharged", "no charge"]]}]}, {"kind": "text", "id": "q2_1", "q": "4", "max": 3, "pts": [["enzyme", "reaction"], ["collide", "move", "aqueous", "solution", "dissolv"], ["plasma", "xylem", "phloem", "sap", "blood"]], "tips": ["Link dissolving to enzymes catalysing reactions.", "Say why being dissolved matters (molecules move and collide).", "Name a transport medium."]}, {"kind": "text", "id": "q2_2", "q": "5", "max": 3, "pts": [["polar", "charged"], ["non polar", "nonpolar", "lipid", "fat", "hydrophobic", "not dissolve", "don t dissolve", "do not dissolve"], ["membrane", "bilayer", "boundary", "inside"]], "tips": ["Which substances does water dissolve?", "Which do not dissolve?", "Why does that matter: think membranes."]}], "3": [{"kind": "rows", "id": "q3_0", "q": "6", "tip": "Each consequence must say what the property means for an animal in water.", "rows": [{"label": "Buoyancy", "sel": [], "pts": [["support", "skeleton", "large", "float", "weight"]]}, {"label": "Viscosity", "sel": [], "pts": [["streamlin", "resist", "drag", "propul", "harder to move", "harder to swim", "slow"]]}, {"label": "Thermal conductivity", "sel": [], "pts": [["heat loss", "lose heat", "loses heat", "insulat", "blubber", "heat is lost", "cold"]]}, {"label": "Specific heat capacity", "sel": [], "pts": [["stable", "slowly", "constant", "does not change", "doesn t change", "little change", "changes little"]]}]}, {"kind": "text", "id": "q3_1", "q": "7", "max": 3, "pts": [["conductivity", "conducts", "25"], ["insulat", "poor conductor"], ["heat loss", "lose heat", "loses heat", "losing heat", "body temperature", "warm", "energy"]], "tips": ["Quote the thermal conductivity data (about 25× air).", "Say what blubber does (insulates, poor conductor).", "Say the effect on heat loss or body temperature."]}, {"kind": "text", "id": "q3_2", "q": "8(a)", "max": 2, "pts": [["air+poor conductor", "air conducts", "low conductivity", "insulat"], ["heat loss", "lose heat", "loses heat", "losing heat", "warm"]], "tips": ["Compare how well air and water conduct heat.", "Say the effect on heat loss."]}, {"kind": "text", "id": "q3_3", "q": "8(b)", "max": 2, "pts": [["buoyan", "float"], ["dense", "bone", "squeez", "exhal", "webbed", "feet", "heavy"]], "tips": ["What does trapped air do to the bird in water?", "Suggest one adaptation that helps it stay under."]}, {"kind": "text", "id": "q3_4", "q": "9", "max": 3, "pts": [["buoyan", "support"], ["flipper", "weight", "not suited", "not efficient"], ["lift", "wing", "streamlin", "drag", "viscos", "dense", "light"]], "tips": ["What supports the seal in water but not on land?", "Why are flippers poor on land?", "Compare what swimming (drag) and flying (lift) need."]}], "4": [{"kind": "text", "id": "q4_0", "q": "13", "max": 4, "pts": [["polar", "hydrogen bond"], ["solvent", "dissolv"], ["cohesion", "adhesion", "xylem", "transpiration"], ["specific heat", "temperature", "stable", "medium", "reaction", "enzyme", "buoyan", "insulat"]], "tips": ["Name at least two properties and link each one to a consequence for living things."]}], "5": [{"kind": "text", "id": "q5_0", "q": "10", "max": 3, "pts": [["cohesion", "hydrogen bond"], ["adhesion", "wall"], ["column", "transpiration", "pulled", "tension", "liquid", "capillary"]], "tips": ["Cohesion → continuous column; adhesion → xylem walls; pulled up by transpiration."]}, {"kind": "text", "id": "q5_1", "q": "11", "max": 3, "pts": [["buoyan+water+more", "buoyan+higher", "buoyan+greater", "buoyan+less", "buoyan+lower"], ["conductiv", "specific heat", "heat capacity"], ["insulat", "support", "skeleton", "blubber", "heat loss", "stable"]], "tips": ["Compare buoyancy using comparative words (greater, less).", "Compare thermal conductivity or specific heat capacity, with numbers if you can.", "Give one consequence for an aquatic animal."]}, {"kind": "text", "id": "q5_2", "q": "12", "max": 3, "pts": [["polar", "partial"], ["oxygen+na", "oxygen+positive", "hydrogen+cl", "hydrogen+negative", "opposite"], ["hydration shell", "surround", "pull apart", "pulls the ions apart", "separate", "lattice"]], "tips": ["Start with water being polar.", "Say which part of water faces Na⁺ and which faces Cl⁻.", "Say what then happens to the ions (hydration shells)."]}]}, "models": {"1": [["1", "Oxygen is more electronegative and attracts the shared electrons more strongly, so oxygen is δ− and each hydrogen δ+; the molecule is bent so the charges do not cancel; the δ+ hydrogen of one molecule is attracted to the δ− oxygen of a neighbouring molecule: a hydrogen bond."], ["2", "Cohesion: attraction between water molecules (hydrogen bonding), keeping a continuous column in the xylem that transpiration can pull up. Adhesion: attraction between water and other polar/charged surfaces such as cellulose xylem walls, giving capillary action and helping the column resist gravity."]], "2": [["3", "Glucose: hydrophilic, polar, its many –OH groups hydrogen bond with water. Sodium chloride: hydrophilic, charged ions attract the oppositely charged pole of water (hydration shell). Amino acids: hydrophilic, charged and polar groups (–NH₂, –COOH). Lipids: hydrophobic, non-polar hydrocarbon chains cannot hydrogen bond with water. Oxygen gas: hydrophobic, non-polar, so only a little dissolves."], ["4", "Enzymes catalyse reactions in aqueous solution; enzymes and substrates must be dissolved to move and collide; dissolved substances can be carried in blood plasma, xylem sap or phloem sap (insoluble substances settle out or need carriers)."], ["5", "Water dissolves mainly polar and charged substances; non-polar substances such as lipids do not dissolve; this insolubility lets phospholipids form a bilayer, the membrane that separates the inside of the cell from its surroundings."]], "3": [["6", "Buoyancy: water supports the body, so less skeletal support is needed and animals can grow large. Viscosity: water resists movement, so a streamlined shape and powerful propulsion are needed. Thermal conductivity: heat is lost about 25× faster than in air, so insulation (blubber, trapped air) is essential. Specific heat capacity: water temperature changes slowly, so aquatic habitats are thermally stable."], ["7", "Water conducts heat about 25 times faster than air, so the seal loses heat quickly; blubber is a poor conductor and insulates; this reduces heat loss, helping keep a constant core temperature and saving energy."], ["8(a)", "Trapped air is a very poor conductor of heat compared with water, so it acts as an insulating layer, greatly reducing heat loss to the water."], ["8(b)", "Trapped air makes the bird more buoyant, so it floats back up and must work harder to stay under. Adaptations: dense/less air-filled bones, squeezing air from feathers, exhaling before diving, large webbed feet for propulsion."], ["9", "In water buoyancy supports the seal''s weight, so its flippers only propel it; on land there is little support and flippers are poor weight-bearing limbs; water is denser and more viscous, so swimming needs a streamlined body to reduce drag, while flight needs wings for lift and a light body."]], "4": [["13", "Water is the medium for most reactions in organisms. Because it is polar, it dissolves ions and polar molecules, so enzymes work and substances are transported in blood plasma and xylem sap. Hydrogen bonding gives cohesion and adhesion, keeping a continuous column in the xylem that transpiration pulls up. It also gives a high specific heat capacity, keeping habitats and organisms at stable temperatures."]], "5": [["10", "Cohesion: hydrogen bonds hold water molecules together, forming a continuous column that does not break under tension; adhesion to the cellulose walls of xylem helps hold the column and gives capillary action; water is liquid and can be pulled up by transpiration."], ["11", "Water gives much greater buoyancy than air; water''s thermal conductivity is about 25× higher and its specific heat capacity about 4× higher than air''s; so aquatic animals need less skeletal support but need insulation to reduce heat loss."], ["12", "Water is polar (δ− oxygen, δ+ hydrogens); the δ− oxygen is attracted to Na⁺ and the δ+ hydrogens to Cl⁻; this pulls the ions out of the crystal lattice and water surrounds them in hydration shells, keeping them dissolved."]]}, "labels": {"q1_0": "1", "q1_1": "2", "q2_0_r0_t": "3 Glucose", "q2_0_r1_t": "3 Sodium chloride (ions)", "q2_0_r2_t": "3 Amino acids", "q2_0_r3_t": "3 Lipids / fats", "q2_0_r4_t": "3 Oxygen gas (O₂)", "q2_1": "4", "q2_2": "5", "q3_0_r0_t": "6 Buoyancy", "q3_0_r1_t": "6 Viscosity", "q3_0_r2_t": "6 Thermal conductivity", "q3_0_r3_t": "6 Specific heat capacity", "q3_1": "7", "q3_2": "8(a)", "q3_3": "8(b)", "q3_4": "9", "q4_0": "13", "q5_0": "10", "q5_1": "11", "q5_2": "12", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '35f28543-73fb-5407-a5a5-a48cb496945a', (select id from public.topics where programme = 'IB DP' and code = 'A1.1' limit 1), 'AHL: Water Beyond Earth', 'A1.1 Water · Lesson 3 · HL only', '/a11-lesson3/', 'DP1-A1.1-L3', 27, 13 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-A1.1-L3', 'AHL: Water Beyond Earth', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "1", "max": 1, "pts": [["life+water", "need water", "needs water", "depend", "require", "support life", "life could", "life might", "life may"]], "tips": ["Link liquid water to what all known life needs."]}], "2": [{"kind": "text", "id": "q2_0", "q": "2(a)", "max": 1, "pts": [["asteroid"]], "tips": ["Name what delivered the water (the syllabus says asteroids, not comets)."]}, {"kind": "text", "id": "q2_1", "q": "2(b)", "max": 2, "pts": [["gravit"], ["temperature+condens", "cool+condens", "cool enough", "temperature+liquid", "cold enough", "condens"]], "tips": ["Condition 1: gravity strong enough to hold water molecules.", "Condition 2: cool enough for vapour to condense into liquid."]}, {"kind": "text", "id": "q2_2", "q": "3", "max": 2, "pts": [["weak+gravit", "not strong enough", "too weak", "cannot hold", "can t hold", "unable to hold"], ["escape", "lost to space", "into space", "leave", "float away", "drift"]], "tips": ["What can weak gravity not do?", "What happens to the water molecules?"]}, {"kind": "text", "id": "q2_3", "q": "4", "max": 2, "pts": [["hot", "heat", "vapour", "vapor", "evaporat", "boil"], ["ultraviolet", " uv ", "stellar wind", "solar wind", "stripped", "broken apart", "split", "hydrogen escape", "escape", "lost"]], "tips": ["What state is water in when it is very hot?", "How is that vapour then lost permanently?"]}], "3": [{"kind": "rows", "id": "q3_0", "q": "5", "tip": "Each row needs the right Y/N AND reasoning about whether water can be LIQUID.", "rows": [{"label": "Juno (−150 °C)", "sel": ["N"], "pts": [["frozen", "freeze", "ice", "below 0", "solid"], ["liquid"]]}, {"label": "Kepler-B (15 °C)", "sel": ["Y"], "pts": [["liquid"]]}, {"label": "Vestia (450 °C)", "sel": ["N"], "pts": [["boil", "vapour", "vapor", "evaporat", "gas", "above 100"], ["liquid"]]}]}], "4": [{"kind": "text", "id": "q4_0", "q": "6", "max": 2, "pts": [["liquid"], ["too hot+too cold", "too close+too far", "boil+frozen", "boil+freeze", "region around a star", "around a star", "distance from"]], "tips": ["Link the zone to liquid water.", "Say where it lies: between too close (too hot) and too far (too cold)."]}, {"kind": "text", "id": "q4_1", "q": "7(a)", "max": 3, "pts": [["all known life", "all life", "every known", "life depends", "life needs", "life requires", "needed for life"], ["medium", "metabol", "solvent", "reaction", "transport"], ["detect", "distance", "easier", "remote", "from far"]], "tips": ["All known life depends on liquid water.", "Give the role water plays (medium for metabolism, solvent).", "Say why water is a practical thing to search for (detectable from far away)."]}, {"kind": "text", "id": "q4_2", "q": "7(b)", "max": 2, "pts": [["atmosphere", "gravit", "element", "radiation", "magnetic", "time", "unstable", "nutrient", "carbon", "energy"], ["atmosphere+gravit", "atmosphere+element", "atmosphere+radiation", "atmosphere+magnetic", "atmosphere+time", "gravit+element", "gravit+radiation", "gravit+magnetic", "gravit+time", "element+radiation", "element+magnetic", "element+time", "radiation+time", "magnetic+time", "unstable+atmosphere", "unstable+radiation", "unstable+element", "unstable+gravit"]], "tips": ["Give two DIFFERENT conditions: atmosphere, gravity, chemical elements, radiation protection, magnetic field, time, a stable star."]}], "5": [{"kind": "text", "id": "q5_0", "q": "8", "max": 3, "pts": [["asteroid"], ["gravit"], ["condens", "cool", "temperature"]], "tips": ["Origin (asteroids) + both retention conditions (gravity and temperature)."]}, {"kind": "text", "id": "q5_1", "q": "9", "max": 3, "pts": [["all known life", "life requires", "life depends", "life needs", "needed for life", "support life"], ["habitable zone", "goldilocks", "temperature range"], ["detect", "distance", "indicator", "not proof", "easier"]], "tips": ["Life needs liquid water.", "Link to the habitable zone.", "Water is an indicator: detectable, but not proof of life."]}, {"kind": "text", "id": "q5_2", "q": "10", "max": 3, "pts": [["asteroid"], ["gravit", "condens", "retain", "temperature"], ["life+water", "habitable", "metabol", "search"]], "tips": ["Origin, retention, and why the search focuses on water."]}]}, "models": {"1": [["1", "All known life depends on liquid water, so a planet with liquid water could potentially support life."]], "2": [["2(a)", "Water was delivered by asteroids containing water and ice that collided with the young Earth over a long period."], ["2(b)", "Gravity: Earth''s gravitational field was strong enough to hold water molecules and stop them escaping into space. Temperature: Earth was cool enough for water vapour to condense into liquid water."], ["3", "Its gravitational field is too weak to hold onto water molecules; water molecules (especially vapour) move fast enough to escape into space, so the water is lost over time (e.g. the Moon, Mercury)."], ["4", "It is too hot, so water stays as vapour rather than liquid; vapour high in the atmosphere is split by ultraviolet radiation and the hydrogen escapes into space (or is stripped away by the stellar wind), so the water is lost permanently."]], "3": [["5", "Juno: N, far below 0 °C so any water is permanently frozen, too cold for liquid water. Kepler-B: Y, between 0 and 100 °C so water can exist as a liquid on the surface. Vestia: N, far above 100 °C so water boils away as vapour, too hot for liquid water."]], "4": [["6", "The region around a star where a planet''s surface temperature allows liquid water to exist: between the region too close to the star (water boils) and too far (water stays frozen)."], ["7(a)", "All known life depends on liquid water; it is the medium for metabolic reactions and the solvent for transport; water can be detected remotely from great distances more easily than life itself, so finding it suggests life may be possible."], ["7(b)", "Any two: no or unsuitable atmosphere; gravity too weak to retain water or atmosphere; necessary chemical elements absent; intense radiation from the star; no magnetic field for protection; not enough time for life to develop; an unstable star."]], "5": [["8", "Water arrived on asteroids containing water and ice that collided with the young Earth over a long period; Earth''s gravity was strong enough to stop water molecules escaping into space; Earth was cool enough for water vapour to condense into liquid water."], ["9", "All known life requires liquid water, so its presence suggests a planet could support life; liquid water exists only in a temperature range, so scientists search the habitable zone; water is easier to detect from far away than life itself, so it is an indicator of possible life, not proof."], ["10", "Earth''s water probably arrived on asteroids carrying water and ice that collided with the young Earth. It was retained because Earth''s gravity held the molecules and the temperature let vapour condense into liquid. All known life depends on liquid water for metabolism, so scientists search for liquid water, and therefore the habitable zone, when looking for life."]]}, "labels": {"q1_0": "1", "q2_0": "2(a)", "q2_1": "2(b)", "q2_2": "3", "q2_3": "4", "q3_0_r0_t": "5 Juno (−150 °C)", "q3_0_r1_t": "5 Kepler-B (15 °C)", "q3_0_r2_t": "5 Vestia (450 °C)", "q4_0": "6", "q4_1": "7(a)", "q4_2": "7(b)", "q5_0": "8", "q5_1": "9", "q5_2": "10", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '2c1b154f-ff58-5777-bc40-fd1497d71ec2', (select id from public.topics where programme = 'IB DP' and code = 'A2.1' limit 1), 'AHL: The Origin of Cells', 'A2.1 Origins of cells · Lesson 1 · HL only', '/a21-lesson1/', 'DP1-A2.1-L1', 42, 81 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-A2.1-L1', 'AHL: The Origin of Cells', '{"marks": {"2": [{"kind": "rows", "id": "q2_0", "q": "2", "tip": "Each row needs BOTH what it was like and why it mattered. Use the word bank.", "rows": [{"label": "Temperature", "sel": [], "pts": [["hot", "cool", "molten"], ["liquid water", "ocean", "vent", "solvent"]]}, {"label": "UV radiation", "sel": [], "pts": [["ozone", "intense", "strong"], ["energy", "broke", "break", "destroy", "damage"]]}, {"label": "Volcanic activity", "sel": [], "pts": [["frequent", "violent", "more"], ["gas", "energy", "mineral", "atmosphere", "heat"]]}, {"label": "Asteroid bombardment", "sel": [], "pts": [["heavy", "frequent", "impact"], ["water", "organic", "energy", "vaporis", "vaporiz", "amino acid"]]}]}, {"kind": "text", "id": "q2_1", "q": "3", "max": 1, "pts": [["carbon compound", "organic", "amino acid", "sugar"]], "tips": ["What kinds of molecule formed from them?"]}], "3": [{"kind": "choice", "id": "q3_0", "q": "4", "max": 3, "n": 6, "ans": ["flask of gas mixture (the \"atmosphere\")", "tungsten electrodes producing sparks", "condenser making \"rain\"", "U-shaped trap where products collect", "flask of water (the \"ocean\")", "heat source boiling the water"], "tip": "Follow the cycle: water is boiled, vapour rises into the gas flask with sparks, then cools in the condenser and collects in the trap."}, {"kind": "text", "id": "q3_1", "q": "5", "max": 4, "pts": [["water+heat", "water+boil", "ocean", "vapour", "vapor"], ["methane", "ammonia", "hydrogen", "gas mixture", "no oxygen"], ["spark", "electrod", "lightning"], ["condens", "cool", "rain"], ["week", "sample", "analys", "chromatograph", "trap"]], "tips": ["Describe the sequence: heated water, gas mixture, sparks, condenser, trap, sampling, and what each part represents."]}, {"kind": "text", "id": "q3_2", "q": "6", "max": 2, "pts": [["amino acid", "glycine", "alanine", "organic"], ["could form", "can form", "spontaneous", "inorganic", "possible", "building blocks"]], "tips": ["Results: what was produced?", "Conclusion: what does it show is possible (not what did happen)?"]}, {"kind": "text", "id": "q3_3", "q": "7", "max": 4, "pts": [["safe", "small scale", "cheap", "inexpensive", "cost"], ["days", "quick", "fast", "modif", "different gases", "sample", "possible"], ["closed", "scale", "volume", "week", "timescale", "million"], ["glass", "protect", " uv ", "diluted", "concentrat", "continuous", "not life", "polymer", "did happen", "racemic"]], "tips": ["Benefits: think safety and cost, speed, modifying the gases, showing a step is possible.", "Limitations: scale, timescale, protection from UV, concentration in the trap, continuous sparking, no life produced."]}], "4": [{"kind": "text", "id": "q4_0", "q": "8", "max": 3, "pts": [["amphipathic", "hydrophilic+hydrophobic"], ["tails+shield", "tails+away", "tails+inside", "heads+water", "heads face", "excluded"], ["stable", "no energy", "spontaneous", "no enzyme", "edge", "sphere"]], "tips": ["What kind of molecule is it?", "How do heads and tails arrange in water?", "Why does it happen by itself (stability, no energy, no edge)?"]}, {"kind": "text", "id": "q4_1", "q": "9", "max": 3, "pts": [["internal environment", "inside", "separate", "enclos"], ["concentrat", "together", "products", "replicat", "selected"], ["grow", "divide", "protocell", "compartment"]], "tips": ["What does a vesicle create?", "What can then happen inside?", "What can vesicles do, and what is the result called?"]}, {"kind": "choice", "id": "q4_2", "q": "10", "max": 2, "n": 5, "ans": ["Simple organic molecules form from inorganic molecules", "Monomers join into polymers", "Self-replicating molecules (RNA, a ribozyme) appear", "Self-replicating molecules enclosed in vesicles: protocells", "DNA takes over information, proteins take over catalysis: true cells"], "tip": "Small molecules first, then polymers, then copying, then compartments, then the modern division of labour."}, {"kind": "text", "id": "q4_3", "q": "11", "max": 4, "pts": [["billion", "long ago", "no direct record", "no record"], ["rock+destroy", "rock+altered", "tectonic", "erosion", "metamorph"], ["microfossil", "contested", "mineral"], ["scale", "timescale", "reproduce", "atmosphere", "chance", "repeat"], ["possible", "actually", "did happen", "what happened"]], "tips": ["Give several limitations AND the closing point: an experiment shows a step is possible, not that it happened."]}], "5": [{"kind": "text", "id": "q5_0", "q": "12", "max": 3, "pts": [["no single", "no agreed", "list", "characteristics", "exception"], ["mule", "red blood cell", "seed", "tardigrade", "fire", "crystal"], ["gradual", "continuum", "boundary", "virus"]], "tips": ["No agreed definition: lists with exceptions.", "Give examples both ways (mule, seed; fire, crystals).", "Life arose gradually: no sharp boundary."]}, {"kind": "text", "id": "q5_1", "q": "13(a)", "max": 2, "pts": [["all the functions", "functions of life", "metabol", "enzyme"], ["membrane", "homeostasis", "replicat", "divide", "self sustaining", "genetic", "reproduce"]], "tips": ["Think functions of life, metabolism, membrane and homeostasis, self-replication."]}, {"kind": "text", "id": "q5_2", "q": "13(b)", "max": 2, "pts": [["no metabol", "none of the functions", "no enzyme", "cannot carry out", "no functions"], ["host", "cannot reproduce", "can t reproduce", "independently", "crystal", "inert", "no cytoplasm", "no cell", "not grow", "no homeostasis"]], "tips": ["What can a virus do on its own?", "How does it reproduce?"]}, {"kind": "text", "id": "q5_3", "q": "13(c)", "max": 1, "pts": [["genetic material", "genes", "evolve", "natural selection", "same molecules", "giant", "reproduce", "adapt", "parasite"]], "tips": ["Use the box above."]}, {"kind": "text", "id": "q5_4", "q": "15", "max": 2, "pts": [["control", "repeat", "safe", "cheap", "quick", "days", "modif", "possible"], ["gas mixture", "closed", "scale", "week", "timescale", "glass", "diluted", "concentrat", "continuous", "not life", "did happen", "atmosphere"]], "tips": ["One benefit.", "One limitation, correctly assigned."]}, {"kind": "text", "id": "q5_5", "q": "Exit (a)", "max": 1, "pts": [["stable", "amphipathic", "tails+water"]], "tips": ["The arrangement is more stable."]}, {"kind": "text", "id": "q5_6", "q": "Exit (b)", "max": 1, "pts": [["all the functions", "functions of life", "own machinery", "itself", "smallest", "depend"]], "tips": ["What can a cell do that anything smaller cannot?"]}]}, "models": {"1": [["1", "(a) yes: Miller–Urey and meteorites. (b) yes: the formose reaction. (c) yes: amphipathic molecules self-assemble. (d) plausible and supported by RNA lab work, but not demonstrated end to end. (e) no: never achieved; the unsolved part of the problem."]], "2": [["2", "Temperature: extremely hot at first, cooling until liquid water oceans could exist; liquid water is the solvent, and hot vents supplied heat, minerals and gases. UV: no ozone layer, so intense UV reached the surface; an energy source for reactions but also broke molecules apart. Volcanic activity: far more frequent and violent; released the atmosphere''s gases and supplied heat and mineral surfaces. Asteroids: heavy, frequent impacts; delivered energy, water and organic compounds (amino acids found in meteorites), but large impacts could vaporise oceans."], ["3", "They may have caused a variety of carbon compounds (amino acids, sugars, fatty acids, bases) to form spontaneously from simple inorganic molecules, without any living organism."]], "3": [["4", "1 flask of gas mixture (CH₄, NH₃, H₂, water vapour); 2 tungsten electrodes producing sparks (lightning); 3 condenser making \"rain\"; 4 U-shaped trap where products collect; 5 flask of water (the \"ocean\"); 6 heat source boiling the water."], ["5", "A sealed glass apparatus; water heated so vapour circulated (the ocean and evaporation); vapour passed into a flask of methane, ammonia and hydrogen with no oxygen (the early atmosphere); continuous sparks between tungsten electrodes (lightning); gases cooled in a condenser and fell as \"rain\" into a U-shaped trap and back to the water flask; ran for about a week; samples analysed by paper chromatography."], ["6", "Results: the solution turned pink then brown; several amino acids (glycine, alanine) and other organic compounds formed (re-analysis later found over twenty amino acids). Conclusion: biologically relevant carbon compounds can form spontaneously from inorganic molecules under early-Earth-like conditions with an energy source, so life''s building blocks could have arisen before life. It does not show that this is how life happened."], ["7", "Benefits: safe, small-scale and cheap; runs in days rather than millions of years; can be modified to compare hypotheses; products accumulate for analysis; shows a step is chemically possible. Limitations: a closed few-litre system cannot represent an open ocean; one week cannot represent hundreds of millions of years; products sheltered in glass from UV; products concentrated rather than diluted; continuous rather than occasional sparking; amino acids are not life (no polymers, no self-replication, racemic); shows what could happen, not what did."]], "4": [["8", "Fatty acids and phospholipids are amphipathic (hydrophilic head, hydrophobic tails); in water the tails are excluded, so the molecules arrange with tails shielded and heads facing the water; this is the more stable arrangement, so it forms spontaneously with no energy, enzymes or genetic information; a bilayer closes into a sphere to remove its exposed edge."], ["9", "The vesicle encloses water, creating an internal environment separate from the surroundings; molecules can be concentrated and a self-replicating molecule kept with its products, so the compartment can be selected as a unit; vesicles can grow and divide; this compartmentalisation produces a protocell."], ["10", "1 simple organic molecules from inorganic ones; 2 monomers join into polymers; 3 self-replicating molecules (RNA) appear; 4 they are enclosed in vesicles (protocells); 5 DNA takes over information storage and proteins catalysis: the first true cells."], ["11", "The events were about four billion years ago with no direct record of the intermediate stages; rocks of that age are destroyed or altered by tectonics, metamorphism and erosion; the earliest microfossils are contested (biological or mineral?); experiments cannot reproduce an ocean or hundreds of millions of years; the early atmosphere is uncertain; chance events cannot be re-run. Above all, an experiment shows a step is possible, not that it actually occurred."]], "5": [["12", "There is no single agreed definition; definitions are lists of characteristics with exceptions (a mule cannot reproduce, a red blood cell cannot divide, a dormant seed or tardigrade barely metabolises); non-living things share some characteristics (fire grows and uses fuel; crystals grow); life arose gradually from chemistry, so there is no sharp boundary, which is why borderline cases such as viruses are hard to place."], ["13(a)", "A cell carries out all the functions of life with its own machinery; has its own metabolism (enzymes); is bounded by a membrane and maintains an internal environment (homeostasis); stores its own genetic information and replicates; is self-sustaining."], ["13(b)", "A virus carries out none of the functions of life on its own and has no metabolism; it has no cytoplasm or cell structure (inert outside a host, can be crystallised); it can only be replicated using a host cell''s ribosomes, enzymes and nucleotides; it does not grow, respond or show homeostasis."], ["13(c)", "They contain genetic material and evolve by natural selection; they reproduce (inside a host) like obligate parasites; giant viruses carry genes for parts of the translation machinery."], ["15", "Any one benefit and one limitation from question 7, correctly assigned."], ["Exit (a)", "Because they are amphipathic, and the arrangement with tails shielded from water and heads facing it is the more stable one, so it forms spontaneously."], ["Exit (b)", "It is the smallest structure that carries out all the functions of life and maintains itself with its own machinery; anything smaller (an organelle, a virus) depends on a cell."]]}, "labels": {"q2_0_r0_t": "2 Temperature", "q2_0_r1_t": "2 UV radiation", "q2_0_r2_t": "2 Volcanic activity", "q2_0_r3_t": "2 Asteroid bombardment", "q2_1": "3", "q3_1": "5", "q3_2": "6", "q3_3": "7", "q4_0": "8", "q4_1": "9", "q4_3": "11", "q5_0": "12", "q5_1": "13(a)", "q5_2": "13(b)", "q5_3": "13(c)", "q5_4": "15", "q5_5": "Exit (a)", "q5_6": "Exit (b)", "s6revisit": "Predictions revisited", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '64b45844-264a-542c-9d41-4504a8668a0b', (select id from public.topics where programme = 'IB DP' and code = 'A2.1' limit 1), 'AHL: RNA, LUCA and the Evidence for the First Cells', 'A2.1 Origins of cells · Lesson 2 · HL only', '/a21-lesson2/', 'DP1-A2.1-L2', 50, 82 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-A2.1-L2', 'AHL: RNA, LUCA and the Evidence for the First Cells', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "2", "max": 3, "n": 3, "ans": ["DNA", "enzymes (proteins)", "messenger RNA"], "tip": "Modern cells: DNA stores, enzymes catalyse, mRNA carries the copy."}, {"kind": "text", "id": "q2_1", "q": "3", "max": 4, "pts": [["store", "base sequence", "information"], ["single strand", "fold", "3d", "three dimensional"], ["catalys", "ribozyme"], ["base pairing", "copied", "replicat"], ["prebiotic", "simple molecules", "dna nucleotides", "modif", "virus", "ribosome"]], "tips": ["Four different properties: storing information, folding, catalysis, copying, forming under prebiotic conditions."]}, {"kind": "rows", "id": "q2_2", "q": "4", "tip": "An answer with only differences cannot reach full marks: the last row needs a similarity.", "rows": [{"label": "Number of strands", "sel": ["single-stranded", "double-stranded"], "pts": []}, {"label": "The sugar in the backbone", "sel": ["ribose (–OH on carbon 2)", "deoxyribose"], "pts": []}, {"label": "Resistance to hydrolysis", "sel": ["lower", "higher"], "pts": []}, {"label": "Can damage be repaired?", "sel": ["not repaired", "repaired using the other strand"], "pts": []}, {"label": "Rate mutations accumulate", "sel": ["higher", "lower"], "pts": []}, {"label": "One way they are similar (type it)", "sel": [], "pts": [["nucleotide", "base sequence", "base pairing", "store information", "mutate", "polymer"]]}]}, {"kind": "text", "id": "q2_3", "q": "5", "max": 3, "pts": [["rrna", "ribosomal rna"], ["peptide bond", "peptidyl"], ["not a protein", "not protein", "not made of protein", "relic", "rna world", "ribozyme"]], "tips": ["What is the ribosome made of?", "Which reaction does the RNA catalyse?", "Why is that significant?"]}], "3": [{"kind": "text", "id": "q3_0", "q": "6", "max": 1, "pts": [["most recent+ancestor", "last+ancestor", "common ancestor+all"]], "tips": ["Not \"the first cell\"."]}, {"kind": "text", "id": "q3_1", "q": "7", "max": 4, "pts": [["dna", "ribosome", "genetic code", "atp synthase", "complex"], ["simpler", "protocell", "rna"], ["descent", "most recent", "defined by"], ["other lineages", "no descendants", "extinct", "died out", "left no", "other cells"], ["branch", "node", "earliest", "conclusion", "million years"]], "tips": ["Use the prompts: complexity, simpler first cells, defined by descent, other lineages, and a balanced conclusion."]}, {"kind": "rows", "id": "q3_2", "q": "8(a)", "tip": "In BOTH bacteria and archaea → inherited from LUCA. In only one group → evolved after the split.", "rows": [{"label": "ATP synthase genes", "sel": ["present in LUCA"], "pts": []}, {"label": "Chlorophyll genes", "sel": ["absent from LUCA"], "pts": []}, {"label": "Wood–Ljungdahl pathway genes", "sel": ["present in LUCA"], "pts": []}]}, {"kind": "text", "id": "q3_3", "q": "8(b)", "max": 2, "pts": [["both+inherit", "both+common ancestor", "common ancestor", "inherited"], ["horizontal", "transfer", "lost"]], "tips": ["Why does being in both groups suggest LUCA had it?", "What could move a gene into both groups later?"]}, {"kind": "choice", "id": "q3_4", "q": "9", "max": 4, "n": 7, "ans": ["prokaryotic", "DNA in a single circular chromosome", "ribosomes and the universal genetic code", "plasma membrane with ATP synthase", "chemoautotrophic: H₂ for energy, CO₂ for carbon", "anaerobic", "thermophilic (hot water)"], "tip": "Use the word bank."}], "4": [{"kind": "rows", "id": "q4_0", "q": "10(a)", "tip": "Subtract each date from 4.54.", "rows": [{"label": "LUCA (≈ 4.2 Ga)", "sel": [], "pts": [["0.34", "340"]]}, {"label": "Stromatolites (3.48 Ga)", "sel": [], "pts": [["1.06", "1060"]]}]}, {"kind": "text", "id": "q4_1", "q": "10(b)", "max": 1, "pts": [["quick", "rapid", "fast", "soon", "early", "first few hundred"]], "tips": ["Compare the dates with the age of the Earth."]}, {"kind": "text", "id": "q4_2", "q": "11", "max": 3, "pts": [["layer", "laminat"], ["cyanobacteria", "prokaryote", "bacteria", "mat"], ["3.48", "pilbara", "shark bay", "australia", "trap", "sediment", "still form"]], "tips": ["What are they?", "What builds them?", "How old, where, and how they form."]}, {"kind": "rows", "id": "q4_3", "q": "12", "tip": "Each row needs how it works AND a limitation.", "rows": [{"label": "Carbon isotope ratios (¹²C : ¹³C)", "sel": [], "pts": [["12c", "lighter", "light signature", "enriched", "light "], ["non living", "non biological", "indirect", "contested", "heated", "disputed", "chemistry"]]}, {"label": "The molecular clock", "sel": [], "pts": [["difference", "sequence", "mutation"], ["constant", "calibrat", "scarce", "vary", "horizontal", "rate"]]}]}], "5": [{"kind": "choice", "id": "q5_0", "q": "13", "max": 3, "n": 6, "ans": ["plume of vent fluid mixing with sea water", "warm alkaline fluid leaving the chimney", "chimney of soft carbonate minerals", "porous micro-compartments in the chimney wall", "cool, slightly acidic sea water rich in CO₂", "olivine-rich rock producing H₂ and CH₄"], "tip": "Work from the top (plume) down to the rock below."}, {"kind": "text", "id": "q5_1", "q": "14", "max": 4, "pts": [["40", "90", "warm"], ["alkaline", " ph "], ["hydrogen", "methane", "serpentin"], ["porous", "compartment", "carbonate"], ["no oxygen", "dark", "no light", "pressure", "stable", "gradient"]], "tips": ["Temperature, pH, chemistry of the fluid, structure of the chimney, light/oxygen/pressure."]}, {"kind": "rows", "id": "q5_2", "q": "15", "tip": "State the inference: metals from vent minerals; a borrowed proton gradient; dark and oxygen-free.", "rows": [{"label": "Iron–sulfur cluster proteins; enzymes needing nickel, molybdenum and tungsten", "sel": [], "pts": [["abundant", "mineral", "vent", "chimney", "rare in"]]}, {"label": "ATP synthase, but an incomplete set of proton pumps", "sel": [], "pts": [["gradient"], ["vent", "surround", "wall", "environment", "borrow", "already"]]}, {"label": "No genes for repairing UV damage, none for using oxygen", "sel": [], "pts": [["dark", "deep", "no light", "no uv"], ["no oxygen", "anaerobic", "without oxygen"]]}]}, {"kind": "text", "id": "q5_3", "q": "Exit (a)", "max": 1, "pts": [["catalys", "ribozyme", "enzyme", "fold"]], "tips": ["What can RNA do besides storing information?"]}, {"kind": "text", "id": "q5_4", "q": "Exit (b)", "max": 1, "pts": [["most recent", "descent", "already had", "complex", "simpler", "other lineages"]], "tips": ["How is LUCA defined?"]}]}, "models": {"1": [["1", "DNA: stores ✓, catalyses ✗, copied ✓. Protein: stores ✗, catalyses ✓, copied ✗. RNA: all three ✓, the only one that ticks every box, which is why it is the presumed first genetic material."]], "2": [["2", "DNA; enzymes, which are proteins; messenger RNA."], ["3", "Any four: stores information in its base sequence; single-stranded so it folds into 3D shapes with an active site; some RNAs are catalysts (ribozymes), so one molecule does both jobs; it can be copied by complementary base pairing; RNA nucleotides form more readily under prebiotic conditions and every cell still makes DNA nucleotides by modifying RNA ones; RNA is still central (mRNA, tRNA, rRNA, RNA viruses)."], ["4", "RNA single-stranded (bases exposed) / DNA double (bases protected). Ribose with a 2′ –OH / deoxyribose. RNA hydrolysed more easily / DNA more resistant. RNA not repaired / DNA repaired using the other strand as template. RNA mutates faster / DNA slower. Similar: both are nucleotide polymers storing information as a base sequence, copied by base pairing, and both mutate."], ["5", "The ribosome is built from rRNA and proteins; the site that catalyses peptide bond formation (peptidyl transferase centre) is made of rRNA, not protein, so the ribosome is a ribozyme; every protein is made by an RNA catalyst, taken as a relic of the RNA world."]], "3": [["6", "The last universal common ancestor: the most recent organism from which all organisms now living are descended."], ["7", "LUCA already had DNA, ribosomes, the universal code, a membrane and ATP synthase, too complex to arise in one step, so simpler cells came before; the first cells were probably RNA protocells; LUCA is defined by descent, not priority; other lineages existed alongside and before it but left no descendants; it is a branching point, the earliest cell we can still make evidence-based statements about, not the root of life."], ["8(a)", "ATP synthase: present (in both groups, so LUCA made ATP by chemiosmosis). Chlorophyll: absent (only some bacteria, so it evolved after the split; LUCA was not photosynthetic). Wood–Ljungdahl: present (in both, so LUCA fixed CO₂ using H₂)."], ["8(b)", "A gene in both bacteria and archaea was most simply inherited from their common ancestor, so LUCA had it; a gene in only one domain evolved after they separated. Limitation: horizontal gene transfer can move a gene into both groups after LUCA (and genes can be lost), so LUCA gene lists are estimates."], ["9", "Prokaryotic; DNA in a single circular chromosome; ribosomes, tRNA and the universal code; a plasma membrane with ATP synthase (chemiosmosis); chemoautotrophic (H₂ electron donor, CO₂ via the Wood–Ljungdahl pathway, iron–sulfur enzymes); anaerobic; thermophilic, near hydrothermal vents."]], "4": [["10(a)", "LUCA: 4.54 − 4.2 = 0.34 Ga (about 340 million years). Stromatolites: 4.54 − 3.48 = 1.06 Ga."], ["10(b)", "Life appeared remarkably quickly on a geological timescale: the first cells (older than LUCA) within the first few hundred million years, once liquid water existed."], ["11", "Layered rock mounds built by mats of prokaryotes, mainly cyanobacteria; the mat traps and binds sediment, then grows up through it, adding a layer; the oldest widely accepted are about 3.48 billion years old from the Pilbara, Western Australia, and living ones still form at Shark Bay, so they can be compared directly."], ["12", "Carbon isotopes: carbon-fixing enzymes take up ¹²C slightly faster, so biological carbon is enriched in ¹²C; graphite with this light signature in dated rock (Isua 3.7 Ga; Jack Hills zircon 4.1 Ga) suggests life; limitation: non-biological reactions can give a similar signature and old rocks are altered, so the evidence is indirect and contested. Molecular clock: sequence differences accumulate at a roughly steady rate; count them, calibrate with fossils, extrapolate back (LUCA ≈ 4.2 Ga); limitation: the rate is not constant, old calibration points are scarce, horizontal gene transfer distorts it, so estimates vary by hundreds of millions of years."]], "5": [["13", "1 plume of vent fluid mixing with sea water; 2 warm alkaline fluid leaving the chimney; 3 chimney of soft carbonate minerals; 4 porous micro-compartments in the wall; 5 cool, slightly acidic sea water rich in CO₂; 6 olivine-rich rock where serpentinisation produces H₂ and CH₄."], ["14", "Warm (40–90 °C, unlike black smokers above 300 °C); alkaline (pH 9–11) against cooler, slightly acidic sea water, so a proton gradient exists across thin walls; fluid rich in H₂ and CH₄ from serpentinisation; porous carbonate chimneys with micro-compartments; dark, no oxygen, high pressure; stable for tens of thousands of years."], ["15", "Metals abundant in vent chimney minerals but scarce in open sea water, so LUCA lived where they were available. It could use a proton gradient but not fully make one, so it used one already present: the pH difference across a porous vent wall. It lived in the dark, deep water, with no free oxygen. Evidence, not proof, of a vent habitat."], ["Exit (a)", "RNA can act as a catalyst as well as store information, so one molecule could hold the instructions and carry out the reactions, removing the chicken-and-egg problem."], ["Exit (b)", "LUCA is defined as the most recent common ancestor, not the first cell: it already had DNA, ribosomes and the genetic code, so simpler cells came before it."]]}, "labels": {"q2_1": "3", "q2_2_r5_t": "4 One way they are similar (type it)", "q2_3": "5", "q3_0": "6", "q3_1": "7", "q3_3": "8(b)", "q4_0_r0_t": "10(a) LUCA (≈ 4.2 Ga)", "q4_0_r1_t": "10(a) Stromatolites (3.48 Ga)", "q4_1": "10(b)", "q4_2": "11", "q4_3_r0_t": "12 Carbon isotope ratios (¹²C : ¹³C)", "q4_3_r1_t": "12 The molecular clock", "q5_1": "14", "q5_2_r0_t": "15 Iron–sulfur cluster proteins; enzymes needing nickel, molybdenum and tungsten", "q5_2_r1_t": "15 ATP synthase, but an incomplete set of proton pumps", "q5_2_r2_t": "15 No genes for repairing UV damage, none for using oxygen", "q5_3": "Exit (a)", "q5_4": "Exit (b)", "s6revisit": "Predictions revisited", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '51ba8b37-eaf4-5ca4-940f-806216f69009', (select id from public.topics where programme = 'IB DP' and code = 'A1.2' limit 1), 'A1.2 Nucleic acids · Lesson 1: Nucleotide structure and the composition of nucleic acids', 'A1.2 Nucleic acids · Lesson 1 · A1.2.1–A1.2.5 (SL)', '/a12-lesson1/', 'DP1-A12-L1', 20, 121 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-A12-L1', 'A1.2 Nucleic acids · Lesson 1: Nucleotide structure and the composition of nucleic acids', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["DNA", "RNA", "RNA", "Both"], "tip": "Which one leaves the nucleus as a messenger?"}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 5, "n": 5, "ans": ["Sugar", "Base", "Phosphate", "Base", "Sugar"], "tip": "Sugars end in -ose."}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 2, "pts": [["rna", "ribose in rna"], ["oxygen", "oh", "hydroxyl", "carbon 2", "c2", "2''"]], "tips": ["Where is each found, and what is different in the structure?"]}, {"kind": "choice", "id": "q3_2", "q": "Q5", "max": 1, "n": 1, "ans": ["Uracil"], "tip": "One base replaces thymine."}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 1, "n": 1, "ans": ["9"], "tip": "Count the bonds, not the nucleotides."}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 3, "pts": [["condensation"], ["phosphodiester", "covalent"], ["phosphate", "sugar", "carbon 3", "3''", "water"]], "tips": ["Type of reaction, type of bond, which atoms."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 3, "pts": [["phosphate"], ["deoxyribose", "sugar", "pentose"], ["base", "adenine", "thymine", "guanine", "cytosine"]], "tips": ["Three parts, joined in the right places."]}, {"kind": "choice", "id": "q5_1", "q": "Q9", "max": 1, "n": 1, "ans": ["Phosphodiester bond"], "tip": "Hydrogen bonds join the two strands."}]}, "models": {"1": [["Q1", "DNA (RNA in some viruses). It must store a huge amount of information stably, be copied accurately when cells divide, and be used to make proteins."]], "2": [["Q2", "All organisms: DNA. Some viruses: RNA. Messenger to ribosomes: mRNA. Both are polymers of nucleotides."]], "3": [["Q3", "Sugars: deoxyribose, ribose. Bases: adenine, uracil. Phosphate: PO₄³⁻."], ["Q4", "Ribose is the sugar in RNA and deoxyribose the sugar in DNA [1]; deoxyribose has one fewer oxygen atom: H instead of OH on carbon 2 [1]."], ["Q5", "RNA contains uracil in place of thymine."]], "4": [["Q6", "10 nucleotides are joined by 9 phosphodiester bonds; each condensation releases one water molecule, so 9."], ["Q7", "By condensation reactions, releasing water [1]; forming covalent phosphodiester bonds [1]; between the phosphate of one nucleotide and the sugar (carbon 3) of the next, giving an alternating sugar-phosphate backbone [1]."]], "5": [["Q8", "Phosphate [1]; deoxyribose (pentose sugar), with the phosphate on carbon 5 [1]; a nitrogenous base (A, T, C or G) joined to carbon 1 [1]."], ["Q9", "Phosphodiester bonds form the backbone; hydrogen bonds hold the two strands together."]], "6": [["Exit ticket", "Phosphate, pentose sugar, nitrogenous base. Phosphodiester bond, made by condensation."]]}, "labels": {"q1_0": "Q1", "q3_1": "Q4", "q4_1": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '187c760e-86a8-5085-ab87-cc2fe30da619', (select id from public.topics where programme = 'IB DP' and code = 'A1.2' limit 1), 'A1.2 Nucleic acids · Lesson 2: The DNA double helix, RNA and complementary base pairing', 'A1.2 Nucleic acids · Lesson 2 · A1.2.6–A1.2.8 (SL)', '/a12-lesson2/', 'DP1-A12-L2', 18, 122 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-A12-L2', 'A1.2 Nucleic acids · Lesson 2: The DNA double helix, RNA and complementary base pairing', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 1, "n": 1, "ans": ["TACG"], "tip": "A pairs with T, C with G."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 3, "pts": [["two strand", "double", "polynucleotide"], ["antiparallel", "opposite"], ["hydrogen", "a-t", "a with t", "complementary", "c-g"]], "tips": ["Strands, direction, pairing."]}, {"kind": "choice", "id": "q2_1", "q": "Q3", "max": 1, "n": 1, "ans": ["52"], "tip": "A–T has 2, C–G has 3."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 5, "n": 5, "ans": ["RNA", "DNA", "RNA", "Both", "Both"], "tip": "Check the table."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 3, "pts": [["deoxyribose", "ribose"], ["thymine", "uracil"], ["double", "single", "strand"]], "tips": ["Sugar, base, strands."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 1, "n": 1, "ans": ["AUGCCU"], "tip": "Pair each base, using U instead of T."}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 2, "pts": [["template", "each strand"], ["identical", "accurate", "same sequence", "copy"]], "tips": ["What does each strand do, and what is the result?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 2, "pts": [["a with t", "a-t", "a pairs", "adenine"], ["sequence", "determine", "one strand", "predict"]], "tips": ["Pairing rule, then what it means for the sequences."]}]}, "models": {"1": [["Q1", "A–T, T–A, G–C, C–G gives TACG."]], "2": [["Q2", "Two polynucleotide strands wound into a helix with sugar-phosphate backbones outside [1]; the strands are antiparallel [1]; bases pair by hydrogen bonds, A with T and C with G (complementary pairing) [1]."], ["Q3", "8 × 2 + 12 × 3 = 16 + 36 = 52."]], "3": [["Q4", "Ribose and uracil: RNA. Double-stranded: DNA. Phosphodiester bonds and adenine: both."], ["Q5", "DNA has deoxyribose, RNA ribose [1]; DNA has thymine, RNA uracil [1]; DNA is double-stranded, RNA single-stranded [1]."]], "4": [["Q6", "T→A, A→U, C→G, G→C, G→C, A→U gives AUGCCU."], ["Q7", "Each original strand acts as a template, and only the complementary nucleotide can pair with each base [1], so the new strands have exactly the right sequence and two identical DNA molecules are produced [1]."]], "5": [["Q8", "Each base pairs only with its partner: A with T and C with G [1]; so the sequence of one strand determines the sequence of the other [1]."]], "6": [["Exit ticket", "Complementary DNA: AATCGG. mRNA from template TTAGCC: AAUCGG."]]}, "labels": {"q2_0": "Q2", "q3_1": "Q5", "q4_1": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'b096fead-2260-51d6-b68b-a69cedaa1257', (select id from public.topics where programme = 'IB DP' and code = 'A1.2' limit 1), 'A1.2 Nucleic acids · Lesson 3: DNA sequence diversity and the genetic code', 'A1.2 Nucleic acids · Lesson 3 · A1.2.9–A1.2.10 (SL)', '/a12-lesson3/', 'DP1-A12-L3', 12, 123 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-A12-L3', 'A1.2 Nucleic acids · Lesson 3: DNA sequence diversity and the genetic code', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 1, "n": 1, "ans": ["4096"], "tip": "4 multiplied by itself 6 times."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["sequence", "order", "any order", "no restriction"], ["4", "long", "length", "number of possible", "combination"]], "tips": ["Order of bases, and length."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 1, "n": 1, "ans": ["Tryptophan"], "tip": "First base U, second G, third G."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["more than one", "several codons", "degenerate", "redundan"], ["stop"]], "tips": ["More codons than amino acids, plus a special job."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q6", "max": 2, "pts": [["same", "universal", "shared", "all organisms"], ["ancestor", "inherit", "evolved once"]], "tips": ["What is shared, and the best explanation."]}, {"kind": "choice", "id": "q4_1", "q": "Q7", "max": 1, "n": 1, "ans": ["The genetic code is nearly universal"], "tip": "Same codons, same amino acids."}], "5": [{"kind": "choice", "id": "q5_0", "q": "Q8", "max": 1, "n": 1, "ans": ["100"], "tip": "Three bases per codon."}, {"kind": "text", "id": "q5_1", "q": "Q9", "max": 2, "pts": [["same codon", "same amino acid", "all organisms", "almost all"], ["exception", "mitochondria", "variation", "few"]], "tips": ["What is the same, and what are the exceptions?"]}]}, "models": {"1": [["Q1", "(a) 4 (b) 16 (c) 64. Each extra base multiplies the number by 4: 4ⁿ."]], "2": [["Q2", "4⁶ = 4096."], ["Q3", "The information is in the sequence of bases, and any base can follow any other [1]; DNA molecules are very long, so the number of possible sequences (4ⁿ) is enormous [1]."]], "3": [["Q4", "UGG codes for tryptophan (Trp), the only codon for it."], ["Q5", "Most amino acids are coded for by more than one codon (the code is degenerate) [1]; and three codons are stop codons that code for no amino acid [1]."]], "4": [["Q6", "Almost all organisms use the same genetic code, with the same codons for the same amino acids [1]; this is best explained by all organisms inheriting it from a common ancestor [1]."], ["Q7", "Because the genetic code is shared, bacterial ribosomes translate the human gene into the same amino acid sequence."]], "5": [["Q8", "300 ÷ 3 = 100 amino acids (fewer if a stop codon is included)."], ["Q9", "In almost all organisms the same codons code for the same amino acids [1]; there are a few minor exceptions, for example in mitochondria and some microorganisms [1]."]], "6": [["Exit ticket", "1 048 576. Even a short sequence has a huge number of possible orders, so DNA can store a vast amount of information."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_1": "Q5", "q4_0": "Q6", "q5_1": "Q9", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '7cbe55f7-5558-597b-bfba-9f3c96e54a82', (select id from public.topics where programme = 'IB DP' and code = 'A1.2' limit 1), 'A1.2 Nucleic acids · Lesson 4 (HL): Directionality, base chemistry and DNA packaging', 'A1.2 Nucleic acids · Lesson 4 · A1.2.11–A1.2.13 (HL)', '/a12-lesson4/', 'DP1-A12-L4', 20, 124 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-A12-L4', 'A1.2 Nucleic acids · Lesson 4 (HL): Directionality, base chemistry and DNA packaging', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 1, "n": 1, "ans": ["5′-GAATC-3′"], "tip": "Write the complement (3′-CTAAG-5′), then reverse it."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["polymerase"], ["3''", "3′", "oh", "hydroxyl", "carbon 3"]], "tips": ["Which enzyme, and which end can it add to?"]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 5, "n": 5, "ans": ["Purine", "Pyrimidine", "Purine", "Pyrimidine", "Pyrimidine"], "tip": "Purines: \"Pure As Gold\"."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["purine", "two ring", "double ring"], ["pyrimidine", "one ring", "single ring", "same width", "constant"]], "tips": ["Ring sizes in each pair."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 4, "n": 4, "ans": ["eight histone proteins forming a core", "DNA between two nucleosomes", "holds the DNA where it enters and leaves", "DNA wrapped around a histone core"], "tip": "Core, joiner, clip, whole bead."}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 3, "pts": [["eight", "octamer", "8"], ["wrap", "wound", "coil", "147", "twice"], ["h1", "linker"]], "tips": ["Core, DNA, extras."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 3, "pts": [["wrap", "wound", "histone"], ["supercoil", "condense", "compact", "fit"], ["access", "transcri", "gene expression", "control"]], "tips": ["Wrapping, compaction, control."]}]}, "models": {"1": [["Q1", "They run in opposite directions. Each strand has a 5′ end (phosphate on carbon 5) and a 3′ end (OH on carbon 3); the 5′ end of one strand lies opposite the 3′ end of the other."]], "2": [["Q2", "Complement 3′-CTAAG-5′; read 5′→3′ it is GAATC."], ["Q3", "DNA polymerase can only add nucleotides to the free 3′ OH (hydroxyl) group of the growing strand [1]; so the new strand extends from its 5′ end towards its 3′ end [1]."]], "3": [["Q4", "Purines: adenine, guanine. Pyrimidines: cytosine, thymine, uracil."], ["Q5", "Each base pair contains one purine (two rings) and one pyrimidine (one ring) [1], so every pair is the same size and the helix has the same width all along [1]."]], "4": [["Q6", "Octamer: core of eight histones. Linker DNA: between beads. H1: holds DNA at entry and exit. Nucleosome: DNA wrapped round the core."], ["Q7", "A core of eight histone proteins (an octamer) [1]; with about 147 base pairs of DNA wrapped around it about twice [1]; held by histone H1 and joined to the next nucleosome by linker DNA [1]."]], "5": [["Q8", "DNA wraps around histones to form nucleosomes [1]; nucleosomes coil further (supercoiling) to condense the long DNA so it fits in the nucleus and into chromosomes for division [1]; packing also controls access to genes, regulating transcription [1]."]], "6": [["Exit ticket", "Top strand 5′→3′, bottom 3′→5′. For example, A (purine) pairs with T (pyrimidine)."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_1": "Q5", "q4_1": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '80dcb293-052f-554a-965b-3c18b77271c7', (select id from public.topics where programme = 'IB DP' and code = 'A1.2' limit 1), 'A1.2 Nucleic acids · Lesson 5 (HL): Experimental evidence for DNA as the genetic material', 'A1.2 Nucleic acids · Lesson 5 · A1.2.14–A1.2.15 (HL)', '/a12-lesson5/', 'DP1-A12-L5', 18, 125 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-A12-L5', 'A1.2 Nucleic acids · Lesson 5 (HL): Experimental evidence for DNA as the genetic material', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 2, "n": 2, "ans": ["labels DNA only", "labels protein only"], "tip": "Which element is in nucleotides? Which is in some amino acids?"}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["blend", "shake", "remove", "coat", "detach"], ["centrifug", "pellet", "separate", "heav"]], "tips": ["One job each."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 2, "pts": [["p-32", "32p", "dna", "phosphorus"], ["s-35", "35s", "protein", "sulfur", "supernatant"]], "tips": ["Where did each label go?"]}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["enter", "inside", "inject"], ["new phage", "instruct", "direct", "progeny", "replicat"]], "tips": ["What got in, and what did it then do?"]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 1, "n": 1, "ans": ["28 %"], "tip": "C = G, then share the rest equally between A and T."}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 2, "pts": [["single", "one strand"], ["not paired", "no pair", "complementary", "a ≠ t", "not equal"]], "tips": ["Look at its description in the table."]}, {"kind": "text", "id": "q4_2", "q": "Q8", "max": 2, "pts": [["equal", "same", "1:1", "a + g", "a+g"], ["pair", "purine with", "complementary"]], "tips": ["Amounts, and the reason."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q9", "max": 5, "pts": [["t2", "phage", "virus"], ["32", "phosphorus"], ["35", "sulfur", "sulphur"], ["blend", "centrifug", "pellet"], ["dna", "genetic material", "entered"]], "tips": ["Organism, two labels, method, results, conclusion."]}]}, "models": {"1": [["Q1", "Label the DNA and the protein differently (for example with different radioactive isotopes), let a virus infect a cell, and see which one enters the cell and is passed to the next generation."]], "2": [["Q2", "P is in the phosphate of DNA but not in proteins; S is in cysteine and methionine in proteins but not in DNA."], ["Q3", "The blender detached the phage coats from the outside of the bacteria [1]; the centrifuge separated the heavier bacteria (pellet) from the lighter phage coats in the supernatant [1]."]], "3": [["Q4", "Most ³²P (DNA) was in the pellet, so DNA entered the bacteria [1]; most ³⁵S (protein) stayed in the supernatant, so protein stayed outside [1]."], ["Q5", "Only DNA entered the bacterial cells [1]; yet new phages, complete with protein coats, were made inside, so the DNA must have carried the instructions (genetic information) [1]."]], "4": [["Q6", "C = G = 22 %, so G + C = 44 %; A + T = 56 %, so A = 28 %."], ["Q7", "φX174 DNA is single-stranded [1]; its bases are not paired, so the amounts of A and T (and of G and C) need not be equal [1]."], ["Q8", "The total amount of purines equals the total of pyrimidines (A + G = C + T) [1]; because every base pair contains one purine and one pyrimidine (A with T, G with C) [1]."]], "5": [["Q9", "Bacteriophage T2 infecting E. coli [1]; one batch labelled with ³²P (in DNA) [1]; another with ³⁵S (in protein) [1]; after infection the mixture was blended and centrifuged, and the radioactivity of the pellet (bacteria) and supernatant measured [1]; ³²P entered the bacteria but ³⁵S did not, so DNA is the genetic material [1]."]], "6": [["Revision plan", "Your own plan, for example: redraw a nucleotide and a section of double helix with 5′ and 3′ ends; practise Chargaff calculations; explain Hershey–Chase to someone else."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_0": "Q4", "q3_1": "Q5", "q4_1": "Q7", "q4_2": "Q8", "q5_0": "Q9", "q6_0": "Revision plan", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'eccf1612-1a24-5401-9c69-2fe0001447c1', (select id from public.topics where programme = 'IB DP' and code = 'A2.2' limit 1), 'A2.2 Cell structure · Lesson 1: Cell theory and microscopy', 'A2.2 Cell structure · Lesson 1 · A2.2.1–A2.2.3 (SL)', '/a22-lesson1/', 'DP1-A22-L1', 24, 51 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-A22-L1', 'A2.2 Cell structure · Lesson 1: Cell theory and microscopy', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["Inductive", "Deductive", "Inductive", "Deductive"], "tip": "Specific observations to a general rule, or a general rule to a specific prediction?"}, {"kind": "choice", "id": "q2_1", "q": "Q3", "max": 1, "n": 1, "ans": ["A broad explanation supported by a large body of evidence"], "tip": "Is a scientific theory a guess?"}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 1, "n": 1, "ans": ["×400"], "tip": "Multiply, do not add."}, {"kind": "choice", "id": "q3_1", "q": "Q5", "max": 1, "n": 1, "ans": ["50 µm"], "tip": "Convert 30 mm into µm first."}, {"kind": "text", "id": "q3_2", "q": "Q6", "max": 2, "pts": [["how many times", "larger", "bigger", "enlarg"], ["detail", "distinguish", "separate", "two points"]], "tips": ["One definition each."]}, {"kind": "choice", "id": "q3_3", "q": "Q7", "max": 5, "n": 5, "ans": ["Light microscope", "Light microscope", "Electron microscope", "Electron microscope", "Both"], "tip": "Which one uses electrons, which need a vacuum?"}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q8", "max": 3, "n": 3, "ans": ["shows where a specific protein is in a cell", "splits membranes to show proteins inside them", "builds 3D structures of proteins from frozen samples"], "tip": "Antibodies, fracture, frozen molecules."}, {"kind": "text", "id": "q4_1", "q": "Q9", "max": 3, "pts": [["antibod"], ["fluoresc", "dye", "glow"], ["specific", "binds", "bind", "attach"]], "tips": ["Antibody, dye, binding."]}], "5": [{"kind": "choice", "id": "q5_0", "q": "Q10 (a)", "max": 1, "n": 1, "ans": ["×30 000"], "tip": "Scale bar length ÷ what it represents, in the same units."}, {"kind": "choice", "id": "q5_1", "q": "Q10 (b)", "max": 1, "n": 1, "ans": ["1.5 µm"], "tip": "Actual size = image size ÷ magnification."}, {"kind": "text", "id": "q5_2", "q": "Q11", "max": 2, "pts": [["resolution", "detail"], ["ultrastructure", "ribosome", "membrane", "organelle", "smaller"]], "tips": ["Resolution, then what could now be seen."]}]}, "models": {"1": [["Q1", "The cell. Before microscopes nobody could see cells, so the idea could not be tested: cell theory depended on the technology to observe cells."]], "2": [["Q2", "Observations → general rule = inductive (1 and 3). General rule → prediction = deductive (2 and 4)."], ["Q3", "A theory is a well-tested, evidence-based explanation. It can still be revised if strong new evidence appears."]], "3": [["Q4", "10 × 40 = ×400."], ["Q5", "30 mm = 30 000 µm; 30 000 ÷ 600 = 50 µm."], ["Q6", "Magnification is how many times larger the image is than the actual object [1]; resolution is the ability to distinguish two points close together as separate, which determines the detail seen [1]."], ["Q7", "Living cells and 0.2 µm resolution: light. Ribosomes and vacuum: electron. Both produce magnified images."]], "4": [["Q8", "Immunofluorescence: locates specific proteins. Freeze-fracture: splits membranes. Cryo-EM: 3D protein structures."], ["Q9", "Antibodies specific to the protein are made [1]; a fluorescent dye is attached to the antibodies [1]; they bind only where the protein is, which glows under UV light, showing its location [1]."]], "5": [["Q10 (a)", "30 mm = 30 000 µm; 30 000 ÷ 1 = ×30 000."], ["Q10 (b)", "45 000 µm ÷ 30 000 = 1.5 µm."], ["Q11", "Its much higher resolution (about 1000 times better than light) [1] revealed the ultrastructure of cells, such as ribosomes, membranes and the inside of organelles [1]."]], "6": [["Exit ticket", "All organisms are made of cells; the cell is the smallest unit of life; cells come from pre-existing cells. For example: actual size = image size ÷ magnification."]]}, "labels": {"q1_0": "Q1", "q3_2": "Q6", "q4_1": "Q9", "q5_2": "Q11", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'd783d732-7e83-5c42-be07-f34febdd2e92', (select id from public.topics where programme = 'IB DP' and code = 'A2.2' limit 1), 'A2.2 Cell structure · Lesson 2: Common cell structures and prokaryotic cells', 'A2.2 Cell structure · Lesson 2 · A2.2.4–A2.2.5 (SL)', '/a22-lesson2/', 'DP1-A22-L2', 24, 52 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-A22-L2', 'A2.2 Cell structure · Lesson 2: Common cell structures and prokaryotic cells', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["controls what enters and leaves", "site of most metabolic reactions", "carries genetic information", "synthesise proteins"], "tip": "Barrier, reactions, information, proteins."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 6, "n": 6, "ans": ["All prokaryotes", "Some prokaryotes", "Some prokaryotes", "All prokaryotes", "Some prokaryotes", "All prokaryotes"], "tip": "Which structures are extras for particular lifestyles?"}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 2, "pts": [["histone", "protein"], ["not", "no", "without"]], "tips": ["What is DNA usually wrapped around in eukaryotes?"]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q5", "max": 5, "n": 5, "ans": ["prevents bursting by osmosis", "attachment and transfer of DNA", "movement", "extra genes such as antibiotic resistance", "protection and sticking to surfaces"], "tip": "Think about what each one would let the bacterium do."}, {"kind": "text", "id": "q4_1", "q": "Q6", "max": 2, "pts": [["resolution", "200 nm", "0.2"], ["ribosome", "small", "20", "nm"]], "tips": ["Compare the size of a ribosome with the resolution of light."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 4, "pts": [["cell wall", "peptidoglycan"], ["nucleoid", "circular", "naked"], ["70s", "ribosome"], ["no nucleus", "no membrane-bound", "no organelle", "plasmid", "flagell", "pili", "capsule"]], "tips": ["One mark per structure, with detail."]}, {"kind": "choice", "id": "q5_1", "q": "Q8", "max": 1, "n": 1, "ans": ["70S ribosome"], "tip": "Which of these is not surrounded by a membrane?"}]}, "models": {"1": [["Q1", "A plasma membrane (to control what enters and leaves), cytoplasm (where reactions happen), DNA (instructions) and ribosomes (to make proteins)."]], "2": [["Q2", "Membrane: controls entry and exit. Cytoplasm: metabolism. DNA: genetic information. Ribosomes: protein synthesis."]], "3": [["Q3", "All: cell wall (in most bacteria), 70S ribosomes, nucleoid DNA. Some: plasmids, flagellum, capsule."], ["Q4", "The DNA is not associated with (wrapped around) histone proteins [1], unlike eukaryotic chromosomes; it lies free in the nucleoid of the cytoplasm [1]."]], "4": [["Q5", "Wall: stops bursting. Pili: attachment and plasmid transfer. Flagellum: movement. Plasmid: extra genes. Capsule: protection and adhesion."], ["Q6", "Ribosomes are about 20–25 nm across [1], far smaller than the resolution of a light microscope (about 200 nm), so they cannot be distinguished [1]."]], "5": [["Q7", "Cell wall of peptidoglycan [1]; circular, naked DNA in a nucleoid region [1]; 70S ribosomes in the cytoplasm [1]; no nucleus or membrane-bound organelles, and may have plasmids, pili, flagella or a capsule [1]."], ["Q8", "Prokaryotes have 70S ribosomes but no membrane-bound organelles."]], "6": [["Exit ticket", "Plasma membrane, cytoplasm, DNA, ribosomes. Prokaryotes: naked circular DNA in a nucleoid; 70S ribosomes only; peptidoglycan wall; plasmids."]]}, "labels": {"q1_0": "Q1", "q3_1": "Q4", "q4_1": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '53f2adee-1221-5064-bc66-cc291dfdc802', (select id from public.topics where programme = 'IB DP' and code = 'A2.2' limit 1), 'A2.2 Cell structure · Lesson 3: Eukaryotic cells and the processes of life', 'A2.2 Cell structure · Lesson 3 · A2.2.6–A2.2.7 (SL)', '/a22-lesson3/', 'DP1-A22-L3', 26, 53 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-A22-L3', 'A2.2 Cell structure · Lesson 3: Eukaryotic cells and the processes of life', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 6, "n": 6, "ans": ["Both", "Eukaryote only", "Both", "Eukaryote only", "Prokaryote only", "Both"], "tip": "Remember the four structures common to all cells."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 6, "n": 6, "ans": ["aerobic respiration", "synthesis of proteins for secretion", "modifies and packages proteins", "digests old organelles", "photosynthesis", "holds the chromosomes"], "tip": "Follow a secreted protein: ribosome → rough ER → Golgi → vesicle."}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 2, "pts": [["concentrat", "efficien", "faster"], ["separate", "apart", "protect", "harmful", "different condition", "ph"]], "tips": ["Concentrating things, and keeping things apart."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q5", "max": 5, "n": 5, "ans": ["food vacuoles digest ingested food", "beating cilia", "contractile vacuoles expel water", "binary fission", "reverses when it hits an obstacle"], "tip": "Look for the structure that does each job."}, {"kind": "text", "id": "q4_1", "q": "Q6", "max": 2, "pts": [["heterotroph", "ingest", "food vacuole", "engulf"], ["autotroph", "photosynth", "chloroplast"]], "tips": ["One feeds on others; one makes its own food."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 4, "pts": [["nutrition", "food vacuole", "photosynth"], ["movement", "cilia", "flagell"], ["homeostasis", "contractile", "excret"], ["reproduc", "binary fission", "response", "eyespot"]], "tips": ["Name the process, then the structure that carries it out."]}, {"kind": "choice", "id": "q5_1", "q": "Q8", "max": 1, "n": 1, "ans": ["Rough endoplasmic reticulum"], "tip": "Where are proteins for secretion made?"}]}, "models": {"1": [["Q1", "It has a nucleus and membrane-bound organelles. Compartments keep incompatible reactions apart, concentrate enzymes and substrates, and protect the cell (for example from lysosome enzymes)."]], "2": [["Q2", "Both: ribosomes, plasma membrane, cytoplasm. Eukaryote only: nuclear membrane, Golgi. Prokaryote only: naked circular DNA."]], "3": [["Q3", "Mitochondrion: respiration. Rough ER: protein synthesis. Golgi: modifies and packages. Lysosome: digestion. Chloroplast: photosynthesis. Nucleus: chromosomes."], ["Q4", "Enzymes and substrates can be concentrated in one compartment, making reactions more efficient [1]; harmful or incompatible reactions are kept apart, for example digestive enzymes inside lysosomes, and each compartment can have its own conditions such as pH [1]."]], "4": [["Q5", "Nutrition: food vacuoles. Movement: cilia. Homeostasis: contractile vacuoles. Reproduction: binary fission. Response: reversing from obstacles."], ["Q6", "Paramecium is a heterotroph: it ingests food into food vacuoles and digests it [1]; Chlamydomonas is an autotroph: it makes its own food by photosynthesis in its chloroplast [1]."]], "5": [["Q7", "Nutrition: food vacuoles (Paramecium) or photosynthesis in the chloroplast (Chlamydomonas) [1]; movement: cilia or flagella [1]; homeostasis: contractile vacuoles remove excess water, and wastes such as CO₂ diffuse out [1]; reproduction by binary fission, or response such as moving towards light using the eyespot [1]."], ["Q8", "Rough ER, with its ribosomes, makes proteins for secretion; such cells also have a large Golgi apparatus and many vesicles."]], "6": [["Exit ticket", "Membranes divide the eukaryotic cell into organelles. This concentrates enzymes and substrates, separates incompatible reactions and allows each organelle its own conditions."]]}, "labels": {"q1_0": "Q1", "q3_1": "Q4", "q4_1": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '2637d427-c46c-5408-9b81-fe661798cbd4', (select id from public.topics where programme = 'IB DP' and code = 'A2.2' limit 1), 'A2.2 Cell structure · Lesson 4: Cell diversity, atypical cells and micrographs', 'A2.2 Cell structure · Lesson 4 · A2.2.8–A2.2.11 (SL)', '/a22-lesson4/', 'DP1-A22-L4', 20, 54 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-A22-L4', 'A2.2 Cell structure · Lesson 4: Cell diversity, atypical cells and micrographs', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["Fungus", "Animal", "Plant", "Plant"], "tip": "Wall material is the quickest clue."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["many nuclei from fused cells", "many nuclei, no cross-walls", "no nucleus, to fit more haemoglobin", "no nucleus, depends on a companion cell"], "tip": "Two have too many nuclei; two have none."}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 2, "pts": [["many nuclei", "multinucleate", "several nuclei"], ["fus", "continuous", "one cell", "single"]], "tips": ["How did the fibre form?"]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q5", "max": 1, "n": 1, "ans": ["Mitochondrion"], "tip": "Which organelle has cristae?"}, {"kind": "text", "id": "q4_1", "q": "Q6", "max": 4, "pts": [["pencil"], ["single line", "continuous", "clear line", "no sketch"], ["no shading", "shade"], ["ruled", "ruler", "label line", "not cross", "title", "scale", "magnification"]], "tips": ["Think of pencil, lines, shading and labels."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 3, "pts": [["both", "similar", "cell wall", "vacuole", "nucleus"], ["cellulose", "chitin"], ["chloroplast", "starch", "glycogen"]], "tips": ["One similarity and two differences."]}, {"kind": "text", "id": "q5_1", "q": "Q8", "max": 2, "pts": [["haemoglobin", "oxygen", "space", "room"], ["divide", "repair", "short life", "120", "cannot make"]], "tips": ["More of what? But unable to do what?"]}]}, "models": {"1": [["Q1", "Yes: they come from cells, have a membrane and cytoplasm and do a job, but they cannot divide. Different organisms and tissues need different structures for their environment and function."]], "2": [["Q2", "Chitin wall: fungus. No wall, centrioles: animal. Cellulose wall and chloroplasts, starch: plant."]], "3": [["Q3", "Muscle fibre: fused cells, many nuclei. Hypha: no septa, many nuclei. Red blood cell: no nucleus. Sieve tube: no nucleus, relies on a companion cell."], ["Q4", "A muscle fibre has many nuclei [1] because it forms from the fusion of many cells into one long continuous structure, so it is not a typical unit of one nucleus in one membrane [1]."]], "4": [["Q5", "A double membrane with an inner membrane folded into cristae is a mitochondrion."], ["Q6", "Use a sharp pencil [1]; clear continuous single lines [1]; no shading [1]; ruled label lines that do not cross, with a title and the magnification or a scale bar [1]."]], "5": [["Q7", "Both have a cell wall, nucleus and often a large vacuole [1]; the plant wall is cellulose but the fungal wall is chitin [1]; plants have chloroplasts and store starch, fungi have no chloroplasts and store glycogen [1]."], ["Q8", "Advantage: more space for haemoglobin, so more oxygen carried [1]; disadvantage: the cell cannot divide or repair itself (no genes to make new proteins), so it lives only about 120 days [1]."]], "6": [["Exit ticket", "No nucleus: mammalian red blood cell, phloem sieve tube element. Many nuclei: skeletal muscle fibre, aseptate fungal hypha."]]}, "labels": {"q1_0": "Q1", "q3_1": "Q4", "q4_1": "Q6", "q5_0": "Q7", "q5_1": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'aa1e0cfe-69bb-5be1-8e36-63f142c1f561', (select id from public.topics where programme = 'IB DP' and code = 'A2.2' limit 1), 'A2.2 Cell structure · Lesson 5 (HL): Endosymbiosis, differentiation and multicellularity', 'A2.2 Cell structure · Lesson 5 · A2.2.12–A2.2.14 (HL)', '/a22-lesson5/', 'DP1-A22-L5', 24, 55 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-A22-L5', 'A2.2 Cell structure · Lesson 5 (HL): Endosymbiosis, differentiation and multicellularity', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 6, "n": 6, "ans": ["Evidence", "Evidence", "Not evidence on its own", "Evidence", "Evidence", "Not evidence on its own"], "tip": "Which features are shared specifically with bacteria?"}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["engulf", "endocytosis", "vesicle"], ["inner", "outer", "bacteri", "own membrane"]], "tips": ["Where does each membrane come from?"]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 3, "pts": [["same", "identical", "all genes"], ["express", "switched on", "activ", "transcri"], ["protein", "signal", "position"]], "tips": ["Same genes, different ones in use, what results."]}, {"kind": "choice", "id": "q3_1", "q": "Q5", "max": 1, "n": 1, "ans": ["The insulin gene is expressed in the beta cell but not in the skin cell"], "tip": "Do the two cells have different DNA?"}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 4, "n": 4, "ans": ["1st", "2nd", "3rd", "4th"], "tip": "From least to most specialised."}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 2, "pts": [["efficien", "division of labour", "better at", "adapted"], ["larger", "size", "longer", "replace", "complex"]], "tips": ["Efficiency, and what it allows."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 4, "pts": [["double membrane", "two membranes"], ["circular", "naked", "own dna"], ["70s", "ribosome"], ["binary fission", "divide", "sequence", "antibiotic"]], "tips": ["Four separate pieces of evidence."]}, {"kind": "text", "id": "q5_1", "q": "Q9", "max": 2, "pts": [["different", "unrelated", "several", "groups", "animals", "plants", "fungi", "algae"], ["ancestor", "unicellular", "phylogen", "separately"]], "tips": ["Which groups, and what were their ancestors?"]}]}, "models": {"1": [["Q1", "A larger cell engulfed a bacterium but did not digest it. The bacterium got food and protection; the host got ATP (or sugars from photosynthesis). Over time the bacterium became an organelle."]], "2": [["Q2", "Evidence: circular naked DNA, 70S ribosomes, double membrane, binary fission. Being in all eukaryotes or making ATP does not by itself show a bacterial origin."], ["Q3", "The cyanobacterium was engulfed by endocytosis inside a vesicle [1]; the inner membrane comes from the bacterium''s own plasma membrane and the outer from the host''s vesicle membrane [1]."]], "3": [["Q4", "All cells contain the same genes [1]; different genes are expressed (switched on) in different cells [1]; so different proteins are made, controlled by signals such as the cell''s position, giving each cell type its structure and function [1]."], ["Q5", "Both cells have the insulin gene; only the beta cell expresses it."]], "4": [["Q6", "Single cells → colony → division of labour (somatic and reproductive cells, as in Volvox) → many interdependent cell types."], ["Q7", "Each cell type is adapted to carry out one function very efficiently (division of labour) [1]; this allows larger, more complex organisms that live longer because cells can be replaced [1]."]], "5": [["Q8", "Double membrane [1]; their own circular, naked DNA [1]; 70S ribosomes like prokaryotes [1]; they divide by binary fission and their DNA sequences are similar to bacteria [1]."], ["Q9", "Multicellular organisms occur in unrelated groups such as animals, plants, fungi and red and brown algae [1]; their closest relatives and common ancestors were unicellular, so multicellularity must have arisen separately in each lineage [1]."]], "6": [["Revision plan", "Your own plan, for example: redo the magnification calculations; redraw a prokaryote and a plant cell from memory; list the endosymbiosis evidence."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_0": "Q4", "q4_1": "Q7", "q5_0": "Q8", "q5_1": "Q9", "q6_0": "Revision plan", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '8b82c921-62de-5d1d-9fd3-0a852cd2d9fb', (select id from public.topics where programme = 'IB DP' and code = 'A2.3' limit 1), 'A2.3 Viruses · Lesson 1: Structural features common to viruses', 'A2.3 Viruses (HL) · Lesson 1 · A2.3.1', '/a23-lesson1/', 'DP1-A23-L1', 22, 91 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-A23-L1', 'A2.3 Viruses · Lesson 1: Structural features common to viruses', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 6, "n": 6, "ans": ["All viruses", "All viruses", "Some viruses", "No viruses", "No viruses", "All viruses"], "tip": "Ribosomes are found in cytoplasm. Is an envelope always there?"}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 1, "pts": [["protect", "shield", "enclose", "attach", "entry", "enter"]], "tips": ["What does it do for the nucleic acid?"]}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 1, "pts": [["host", "membrane"]], "tips": ["It is made of phospholipid."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q5", "max": 4, "n": 4, "ans": ["ATP from respiration", "nucleotides", "amino acids", "ribosomes and tRNA"], "tip": "A virus has no metabolism."}, {"kind": "text", "id": "q4_1", "q": "Q6", "max": 3, "pts": [["no cytoplasm", "no ribosome", "no metabolism", "cannot make protein", "no enzyme"], ["atp", "energy"], ["host", "obligate", "parasite"]], "tips": ["Three points: what they lack, what they need, where they get it."]}, {"kind": "text", "id": "q4_2", "q": "Q7", "max": 2, "pts": [["genetic code", "universal", "same code", "same codons"], ["ribosome", "translat", "amino acid"]], "tips": ["Think about how a ribosome reads codons."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 4, "pts": [["small", "fixed size", "nm"], ["dna or rna", "nucleic acid", "rna", "dna"], ["capsid", "protein coat"], ["no cytoplasm", "no ribosome", "few enzymes", "no enzymes", "few or no"]], "tips": ["One mark per feature."]}, {"kind": "choice", "id": "q5_1", "q": "Q9", "max": 1, "n": 1, "ans": ["They are surrounded by a membrane envelope"], "tip": "Look back at Figure 1."}]}, "models": {"1": [["Q1", "For: it has genes (DNA or RNA), it reproduces (inside cells) and it evolves. Against: it has no cytoplasm or metabolism, does not respire, grow or excrete, and cannot reproduce outside a host cell."]], "2": [["Q2", "All viruses: capsid, DNA or RNA, small fixed size. Some viruses: an envelope. No viruses: ribosomes or cytoplasm."]], "3": [["Q3", "It protects the nucleic acid and helps the virus attach to and enter a host cell."], ["Q4", "From the host cell''s membrane, taken as the new virus leaves the cell (budding)."]], "4": [["Q5", "Energy: ATP from the host''s respiration. Nucleic acid: host nucleotides. Proteins: host amino acids, made on host ribosomes with host tRNA."], ["Q6", "Viruses have no cytoplasm, ribosomes or metabolism, so they cannot make proteins [1]; they cannot make ATP or obtain nucleotides and amino acids [1]; so they must use the machinery of a host cell: they are obligate parasites [1]."], ["Q7", "The genetic code is shared (universal) [1], so the host''s ribosomes and tRNAs translate viral codons into the same amino acids as intended and make viral proteins [1]."]], "5": [["Q8", "Small, fixed size [1]; nucleic acid, DNA or RNA, as the genetic material [1]; a protein capsid [1]; no cytoplasm and few or no enzymes [1]."], ["Q9", "An envelope is found only in some viruses (for example HIV and coronaviruses); bacteriophage lambda has none."]], "6": [["Exit ticket", "(a) A protein capsid and DNA or RNA. (b) Cytoplasm, ribosomes and its own metabolism. (c) To get energy, building blocks and protein synthesis."]]}, "labels": {"q1_0": "Q1", "q3_0": "Q3", "q3_1": "Q4", "q4_1": "Q6", "q4_2": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'b839df63-cbf5-5e9e-9d53-f36de8c76a23', (select id from public.topics where programme = 'IB DP' and code = 'A2.3' limit 1), 'A2.3 Viruses · Lesson 2: Diversity of viral structure and genetic material', 'A2.3 Viruses (HL) · Lesson 2 · A2.3.2', '/a23-lesson2/', 'DP1-A23-L2', 22, 92 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-A23-L2', 'A2.3 Viruses · Lesson 2: Diversity of viral structure and genetic material', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["dsDNA", "+ssRNA", "+ssRNA", "−ssRNA", "+ssRNA"], "tip": "Use the simulator."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["positive", "directly", "mrna", "translated"], ["negative", "complementary", "copied", "polymerase", "first"]], "tips": ["Which can a ribosome read straight away?"]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 6, "n": 6, "ans": ["Bacteriophage lambda", "Bacteriophage lambda", "HIV", "Coronavirus", "Bacteriophage lambda", "HIV"], "tip": "Use Figure 1 and the simulator."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["rna"], ["dna"]], "tips": ["From what, to what?"]}, {"kind": "choice", "id": "q3_2", "q": "Q6", "max": 1, "n": 1, "ans": ["Soap dissolves the lipid envelope; lambda has no envelope"], "tip": "What is the envelope made of?"}], "4": [{"kind": "text", "id": "q4_0", "q": "Q7", "max": 2, "pts": [["host", "cell"], ["cannot", "do not", "no enzyme", "rna from rna", "rna template"]], "tips": ["Can a host cell copy RNA from an RNA template?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 4, "pts": [["dna", "double"], ["rna"], ["envelope", "enveloped"], ["tail", "capsid", "spike", "reverse transcriptase", "icosahedral", "helical"]], "tips": ["Similarities AND differences: all have a capsid and nucleic acid; then genome and envelope."]}]}, "models": {"1": [["Q1", "Advantage: the envelope fuses with the host membrane, helping entry, and hides the capsid from some antibodies. Disadvantage: it is fragile: soap, detergents and drying destroy it, so enveloped viruses survive less well outside the body."]], "2": [["Q2", "Lambda: dsDNA. SARS-CoV-2: +ssRNA. HIV: +ssRNA (copied into DNA by reverse transcriptase). Influenza A: −ssRNA (segmented). TMV: +ssRNA."], ["Q3", "The genome of a positive-sense virus acts as mRNA and is translated directly by host ribosomes [1]; a negative-sense genome must first be copied into a complementary (positive) strand by a viral RNA polymerase before it can be translated [1]."]], "3": [["Q4", "Lambda: dsDNA, infects bacteria, not enveloped. Coronavirus: spike proteins bind ACE2. HIV: reverse transcriptase, infects helper (CD4) T cells."], ["Q5", "Reverse transcriptase uses the viral RNA as a template [1] to make DNA, which is then inserted into the host cell''s DNA [1]."], ["Q6", "The coronavirus envelope is a phospholipid membrane, which detergents dissolve. Lambda has only a protein capsid."]], "4": [["Q7", "Host cells only make RNA from a DNA template [1], so they have no enzyme to copy the viral RNA genome; the virus must supply an RNA-dependent RNA polymerase [1]."]], "5": [["Q8", "All three have a protein capsid surrounding their nucleic acid [1]. Lambda has dsDNA while coronavirus and HIV have ssRNA [1]. Coronavirus and HIV are enveloped with surface glycoproteins; lambda is not enveloped [1]. Lambda has an icosahedral head and tail; coronavirus a helical nucleocapsid with spikes; HIV a cone-shaped capsid containing reverse transcriptase [1]."]], "6": [["Exit ticket", "Genetic material: DNA (lambda) or RNA (HIV); or ss vs ds. Structure: enveloped (HIV) or not (lambda); or helical vs icosahedral capsid."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_1": "Q5", "q4_0": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '46b2c04e-10f4-58bf-9e99-dbbd85fd6b90', (select id from public.topics where programme = 'IB DP' and code = 'A2.3' limit 1), 'A2.3 Viruses · Lesson 3: The lytic cycle of bacteriophage lambda', 'A2.3 Viruses (HL) · Lesson 3 · A2.3.3', '/a23-lesson3/', 'DP1-A23-L3', 21, 93 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-A23-L3', 'A2.3 Viruses · Lesson 3: The lytic cycle of bacteriophage lambda', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["Attachment", "Injection of DNA", "Replication and protein synthesis", "Assembly", "Lysis"], "tip": "Bind, enter, copy, build, burst."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 5, "n": 5, "ans": ["Attachment", "Injection", "Replication and protein synthesis", "Assembly", "Lysis"], "tip": "One event per phase."}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 2, "pts": [["specific", "shape", "complementary", "bind"], ["only", "host range", "particular", "e. coli", "which cell"]], "tips": ["Think about why lambda infects E. coli but not human cells."]}, {"kind": "text", "id": "q3_2", "q": "Q5", "max": 1, "pts": [["burst", "lysis", "wall", "break"]], "tips": ["What happens at the last phase?"]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q6", "max": 3, "pts": [["atp", "energy"], ["nucleotide", "amino acid"], ["ribosome", "enzyme", "trna", "protein synthesis"]], "tips": ["Energy, building blocks, machinery."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 4, "pts": [["attach", "receptor"], ["inject", "dna enters"], ["replicat", "protein synthesis", "copies", "transcri"], ["assembl", "lysis", "burst", "release"]], "tips": ["Name each phase and say what happens."]}, {"kind": "choice", "id": "q5_1", "q": "Q8", "max": 1, "n": 1, "ans": ["Its protein capsid"], "tip": "What is injected?"}]}, "models": {"1": [["Q1", "DNA (from host nucleotides, copied with energy from host ATP) and proteins for the capsid and tail (from host amino acids, made on host ribosomes). Almost everything came from the host."]], "2": [["Q2", "Attachment → injection → replication and protein synthesis → assembly → lysis."]], "3": [["Q3", "Receptor binding: attachment. Capsid outside: injection. Ribosomes make proteins: synthesis. Heads filled: assembly. Wall broken down: lysis."], ["Q4", "The tail fibre has a shape complementary to a particular receptor protein [1], so the phage can only attach to and infect cells that carry it (here E. coli): this decides its host range [1]."], ["Q5", "Viral enzymes break down the cell wall and the cell bursts (lysis) to release the new phages."]], "4": [["Q6", "The host supplies ATP from respiration for every energy-requiring step [1]; nucleotides to copy the phage DNA and amino acids for its proteins [1]; and ribosomes, tRNA and enzymes to transcribe and translate the viral genes [1]."]], "5": [["Q7", "The phage attaches to receptors on E. coli [1] and injects its DNA [1]; the host replicates the viral DNA and makes viral proteins [1]; new phages are assembled and released when the cell bursts (lysis) [1]."], ["Q8", "The protein capsid (head and tail) stays outside; only the DNA is injected."]], "6": [["Exit ticket", "Attach, inject, replicate and make proteins, assemble, burst."]]}, "labels": {"q1_0": "Q1", "q3_1": "Q4", "q3_2": "Q5", "q4_0": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '418ace68-a416-55f8-8cb0-2e782889084d', (select id from public.topics where programme = 'IB DP' and code = 'A2.3' limit 1), 'A2.3 Viruses · Lesson 4: The lysogenic cycle', 'A2.3 Viruses (HL) · Lesson 4 · A2.3.4', '/a23-lesson4/', 'DP1-A23-L4', 19, 94 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-A23-L4', 'A2.3 Viruses · Lesson 4: The lysogenic cycle', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["Attachment", "Injection", "Integration as a prophage", "Replication with the chromosome at cell division", "Induction into the lytic cycle"], "tip": "Same start as the lytic cycle."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 6, "n": 6, "ans": ["Both", "Lytic", "Lysogenic", "Lysogenic", "Lytic", "Lysogenic"], "tip": "Which steps are shared?"}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 1, "pts": [["integrat", "inserted", "part of the", "in the chromosome", "in the bacterial dna"]], "tips": ["Where is the phage DNA?"]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["die", "dying", "damaged", "not survive"], ["escape", "release", "new host", "infect other", "spread"]], "tips": ["What is about to happen to the host?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 5, "pts": [["attach", "inject", "both"], ["integrat", "prophage"], ["daughter", "cell division", "passed"], ["burst", "lysis", "die", "killed"], ["induc", "uv", "stress", "switch", "repressor"]], "tips": ["Similarity, then differences, then the switch."]}]}, "models": {"1": [["Q1", "The phage DNA was hidden inside the bacterial chromosome (a prophage). UV light damages DNA, and that signal switches the phage to the lytic cycle."]], "2": [["Q2", "Attachment → injection → integration (prophage) → copied at each cell division → induction → lytic cycle."]], "3": [["Q3", "Both: injection. Lytic: lysis, assembly of many phages. Lysogenic: prophage, passed to daughter cells, host survives."], ["Q4", "Phage DNA that has been integrated into the bacterial chromosome."]], "4": [["Q5", "A cell with damaged DNA may die, taking the prophage with it [1]; by switching to the lytic cycle the phage makes many copies and escapes to infect new hosts [1]."]], "5": [["Q6", "Both begin with attachment and injection of DNA [1]. In the lysogenic cycle the DNA integrates as a prophage [1] and is passed to daughter cells when the host divides [1]; in the lytic cycle new phages are made and the cell bursts and dies [1]. Stress such as UV light causes induction: the prophage is excised and the lytic cycle begins [1]."]], "6": [["Exit ticket", "In the lysogenic cycle the virus inserts its DNA into the bacterium''s chromosome, where it is called a prophage. It is copied every time the cell divides, until stress switches it to the lytic cycle."]]}, "labels": {"q1_0": "Q1", "q3_1": "Q4", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'f5b77018-7f11-543d-a8ba-76c82b667911', (select id from public.topics where programme = 'IB DP' and code = 'A2.3' limit 1), 'A2.3 Viruses · Lesson 5: Origins of viruses and convergent evolution', 'A2.3 Viruses (HL) · Lesson 5 · A2.3.5', '/a23-lesson5/', 'DP1-A23-L5', 13, 95 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-A23-L5', 'A2.3 Viruses · Lesson 5: Origins of viruses and convergent evolution', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 3, "n": 3, "ans": ["Progressive (escape)", "Regressive (reduction)", "Regressive (reduction)"], "tip": "Gained or lost?"}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 1, "pts": [["host", "need cells", "parasite", "cannot reproduce"]], "tips": ["What do all viruses need today?"]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 1, "pts": [["independent", "unrelated", "separate", "different ancestor", "not related"]], "tips": ["Similar features in…"]}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["cell", "organism", "living"], ["after", "from", "derived", "common", "origin"]], "tips": ["If viruses evolved separately, would they use the same code?"]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q6", "max": 2, "pts": [["lost", "loss", "fewer", "simpler", "reduc"], ["advantage", "selection", "not needed", "host provides", "parasit"]], "tips": ["What was lost, and why was that favoured?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 4, "pts": [["different origin", "several origin", "unrelated", "independent"], ["parasit", "host", "same way of life"], ["selection", "pressure", "favour"], ["capsid", "small genome", "no metabolism", "similar features"]], "tips": ["Several origins + same lifestyle + selection = similar features."]}]}, "models": {"1": [["Q1", "Viruses share no single gene found in all of them (no equivalent of ribosomal RNA genes), and their genomes are so diverse that they probably do not have one common ancestor."]], "2": [["Q2", "Plasmid-like genes support escape. Giant viruses with translation-related genes, and loss of metabolic genes, support reduction."], ["Q3", "All viruses are obligate parasites: they cannot reproduce without host cells, so cells must have existed first."]], "3": [["Q4", "The independent evolution of similar features in unrelated organisms (or lineages) facing similar selection pressures."], ["Q5", "Viruses probably evolved from (or after) cellular organisms [1]: they use the host''s code because they depend on host ribosomes, which suggests they arose from cellular genetic material [1]."]], "4": [["Q6", "Viruses may have evolved from cells by losing genes and structures [1]; inside a host that provides everything, losing them was not a disadvantage and may have been selected for (faster replication), so evolution produced simpler forms [1]."]], "5": [["Q7", "Viruses probably arose several times from different origins [1]. All share the same extreme way of life as obligate parasites of cells [1], so similar selection pressures acted on them [1], favouring similar features such as a protein capsid, a small genome and no metabolism, even though they are not closely related [1]."]], "6": [["Exit ticket", "Your own answer, with evidence: for example, finding a universal viral gene would support a single origin."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_0": "Q4", "q3_1": "Q5", "q4_0": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '97dd098c-3fbf-5294-b6a3-516aae7dac6f', (select id from public.topics where programme = 'IB DP' and code = 'A2.3' limit 1), 'A2.3 Viruses · Lesson 6: Rapid evolution in viruses', 'A2.3 Viruses (HL) · Lesson 6 · A2.3.6', '/a23-lesson6/', 'DP1-A23-L6', 19, 96 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-A23-L6', 'A2.3 Viruses · Lesson 6: Rapid evolution in viruses', '{"marks": {"2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["proofread", "error", "mistake", "mutation rate"], ["rna polymerase", "reverse transcriptase", "no proofreading", "cannot correct"]], "tips": ["Think about the enzyme that copies the genome."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 5, "n": 5, "ans": ["Antigenic drift", "Antigenic shift", "Antigenic shift", "Antigenic drift", "Antigenic shift"], "tip": "Small and gradual, or sudden and large?"}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 2, "pts": [["segment", "pieces"], ["swap", "reassort", "exchange", "mix", "two strains", "same cell"]], "tips": ["What can two strains in one cell do with separate pieces?"]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 3, "pts": [["mutation", "variation", "random"], ["survive", "selection", "killed", "not killed"], ["reproduce", "multiply", "replicate", "pass on", "increase"]], "tips": ["Variation → selection → reproduction."]}, {"kind": "choice", "id": "q4_1", "q": "Q6", "max": 1, "n": 1, "ans": ["A virus would need three resistance mutations at the same time, which is very unlikely"], "tip": "Try it in the simulator."}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 6, "pts": [["mutation", "mutate"], ["vaccine", "every year", "annual", "update"], ["drift", "shift", "pandemic"], ["resistan"], ["combination", "three drugs", "several drugs", "antiretroviral"], ["no vaccine", "difficult", "challenge", "lifelong", "cost"]], "tips": ["Both viruses; vaccines and drugs; problems and responses."]}]}, "models": {"1": [["Q1", "The influenza virus changes its surface proteins quickly by mutation, so antibodies made against last year''s strain no longer fit well."]], "2": [["Q2", "RNA viruses have a higher mutation rate [1], because RNA polymerases and reverse transcriptase cannot proofread and correct copying errors, unlike the DNA polymerases used by DNA viruses [1]."]], "3": [["Q3", "Drift: gradual point mutations, yearly vaccine updates. Shift: reassortment, new subtype, can start a pandemic."], ["Q4", "Its genome is in 8 separate segments [1], so when two strains infect the same cell, whole segments (genes such as H) can be swapped, producing a new combination in one step [1]."]], "4": [["Q5", "Random mutations produce some virus variants that are resistant to the drug [1]; the drug kills or blocks the sensitive variants, so the resistant ones survive (natural selection) [1]; they replicate and soon make up most of the population [1]."], ["Q6", "Resistance to all three drugs needs three separate mutations in one virus at once, which is extremely unlikely even in a huge population."]], "5": [["Q7", "Both viruses mutate rapidly [1]. For influenza, antigenic drift means vaccines must be updated every year [1], and antigenic shift can cause pandemics for which there is little immunity [1]. For HIV, resistance to single drugs evolves quickly [1], so combination therapy with several drugs is used [1]. Rapid change in HIV envelope proteins has so far prevented an effective vaccine, and treatment is lifelong and costly [1]."]], "6": [["Exit ticket", "High mutation rate, short generation time, large populations (plus recombination). Consequence: yearly flu vaccines, or combination therapy for HIV."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q2", "q3_1": "Q4", "q4_0": "Q5", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'c68c9579-bf4a-5f1f-845d-f1b43e0c704b', (select id from public.topics where programme = 'IB DP' and code = 'A2.3' limit 1), 'A2.3 Viruses · Lesson 7: Consolidation and exam practice', 'A2.3 Viruses (HL) · Lesson 7 · consolidation', '/a23-lesson7/', 'DP1-A23-L7', 20, 97 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-A23-L7', 'A2.3 Viruses · Lesson 7: Consolidation and exam practice', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "P1.1", "max": 1, "n": 1, "ans": ["A protein capsid"], "tip": "One feature only."}, {"kind": "choice", "id": "q1_1", "q": "P1.2", "max": 1, "n": 1, "ans": ["Coronavirus"], "tip": "Lambda and adenovirus are dsDNA."}, {"kind": "choice", "id": "q1_2", "q": "P1.3", "max": 1, "n": 1, "ans": ["Copies RNA into DNA"], "tip": "Reverse of transcription."}, {"kind": "choice", "id": "q1_3", "q": "P1.4", "max": 1, "n": 1, "ans": ["They can only reproduce inside a host cell"], "tip": "Obligate means \"must\"."}], "2": [{"kind": "choice", "id": "q2_0", "q": "P1.5", "max": 4, "n": 4, "ans": ["Lysogenic", "Lytic", "Both", "Lysogenic"], "tip": "Induction is the exit from which cycle?"}, {"kind": "text", "id": "q2_1", "q": "P2.1", "max": 2, "pts": [["uv", "stress", "damage", "repressor"], ["excis", "cut out", "removed", "lytic"]], "tips": ["Trigger, then result."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "P2.2 (a)", "max": 1, "n": 1, "ans": ["about 500 times"], "tip": "3 × 10⁻⁵ ÷ 6 × 10⁻⁸."}, {"kind": "text", "id": "q3_1", "q": "P2.2 (b)", "max": 1, "pts": [["rna"]], "tips": ["Which genomes have the higher rates?"]}, {"kind": "text", "id": "q3_2", "q": "P2.2 (c)", "max": 2, "pts": [["proofread"], ["dna polymerase", "rna polymerase", "reverse transcriptase", "host"]], "tips": ["Which enzymes copy each genome?"]}], "4": [{"kind": "text", "id": "q4_0", "q": "P2.3", "max": 3, "pts": [["divers", "different", "varied"], ["genetic code", "same code"], ["convergent", "parasit"]], "tips": ["Diversity, genetic code, convergence."]}, {"kind": "text", "id": "q4_1", "q": "P2.4", "max": 3, "pts": [["mutation", "mutate"], ["resistan"], ["three", "several", "multiple", "unlikely"]], "tips": ["Mutation rate, resistance, probability."]}]}, "models": {"1": [["P1.1", "A protein capsid. Envelopes and dsDNA are found only in some viruses; no virus has ribosomes."], ["P1.2", "Coronavirus (+ssRNA, enveloped)."], ["P1.3", "It copies an RNA template into DNA."], ["P1.4", "They can only reproduce inside a host cell, using its machinery."]], "2": [["P1.5", "Integration: lysogenic. Lysis: lytic. Attachment: both. Induction ends the lysogenic cycle and starts the lytic cycle."], ["P2.1", "Stress such as UV light inactivates the repressor [1]; the prophage is cut out of the chromosome and the lytic cycle begins [1]."]], "3": [["P2.2 (a)", "3 × 10⁻⁵ ÷ 6 × 10⁻⁸ = 500 times."], ["P2.2 (b)", "RNA viruses (HIV-1, influenza) have mutation rates hundreds of times higher than the dsDNA viruses."], ["P2.2 (c)", "DNA viruses are copied by DNA polymerases that proofread and correct errors [1]; RNA polymerases and reverse transcriptase cannot proofread, so errors remain [1]."]], "4": [["P2.3", "Viruses are extremely diverse in genome and structure, with no gene shared by all, suggesting several origins [1]; they use the same genetic code as living organisms, suggesting they arose from cellular material [1]; their shared features could be convergent evolution for an obligate parasitic way of life [1]."], ["P2.4", "HIV mutates very rapidly because reverse transcriptase cannot proofread [1]; resistance to any single drug evolves quickly by natural selection [1]; with several drugs at once, a virus would need several resistance mutations simultaneously, which is very unlikely [1]."]], "5": [["Link", "Viruses show that evolution can produce simplicity: under the regressive hypothesis they lost genes as parasites. Overall, complexity has increased in some lineages, while parasites and some microbes became simpler: selection favours what works in each environment."]], "6": [["Revision plan", "Your own plan, for example: redraw the lytic and lysogenic cycles from memory; make a comparison table of lambda, coronavirus and HIV."]]}, "labels": {"q2_1": "P2.1", "q3_1": "P2.2 (b)", "q3_2": "P2.2 (c)", "q4_0": "P2.3", "q4_1": "P2.4", "q5_0": "Link", "q6_0": "Revision plan", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'd4709d1f-b7a4-5166-b02a-2bb9d553ad5e', (select id from public.topics where programme = 'IB DP' and code = 'B1.1' limit 1), 'Carbon Compounds and Carbohydrates', 'B1.1 Carbohydrates and lipids · Lesson 1 · SL and HL', '/b11-lesson1/', 'DP1-B1.1-L1', 59, 21 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-B1.1-L1', 'Carbon Compounds and Carbohydrates', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "1", "max": 2, "pts": [["diamond"], ["not always", "does not mean", "doesn t mean", "not all", "not necessarily", "not every", "does not always", "doesn t always", "living", "organism"]], "tips": ["Name the carbon-containing substance that is not organic.", "Say what that tells you about carbon and \"organic\"."]}], "2": [{"kind": "rows", "id": "q2_0", "q": "2", "tip": "Each row needs a full answer: a number with a reason, both bond types, the main atoms, a reason for chains and rings.", "rows": [{"label": "How many covalent bonds does a carbon atom always form, and why?", "sel": [], "pts": [["four", "4"], ["outer", "shell", "electron"]]}, {"label": "Which types of covalent bond can carbon form?", "sel": [], "pts": [["single"], ["double"]]}, {"label": "Which other atoms does carbon most often bond to in living organisms?", "sel": [], "pts": [["hydrogen", "oxygen", "nitrogen"], ["hydrogen+oxygen", "hydrogen+nitrogen", "oxygen+nitrogen", "phosph", "sulf", "sulph", "other carbon"]]}, {"label": "Why can carbon form chains and rings?", "sel": [], "pts": [["strong", "stable", "four", "bond to other carbon", "other carbon", "carbon carbon", "each other", "itself"]]}]}, {"kind": "text", "id": "q2_1", "q": "3(a)", "max": 2, "pts": [["carbon+living", "carbon+organism", "produced by", "characteristic of"], ["carbon dioxide", "co2", "carbonate", "carbide", "cyanide", "diamond", "graphite"]], "tips": ["Organic: contains carbon AND is produced by or characteristic of living organisms.", "Name an exception, e.g. carbon dioxide."]}, {"kind": "text", "id": "q2_2", "q": "3(b)", "max": 2, "pts": [["shar"], ["strong", "fixed", "shape", "stable", "direction", "enzyme"]], "tips": ["Cause: what do the atoms do with electrons?", "Consequence: what does that do to the molecule (strength, fixed shape, stability)?"]}, {"kind": "choice", "id": "q2_3", "q": "4(a)", "max": 3, "n": 6, "ans": ["hydroxyl", "aldehyde", "ketone", "carboxyl", "amine", "phosphate"], "tip": "Use the word bank. Aldehyde and ketone both have C=O: at the END of a chain it is an aldehyde, WITHIN a chain a ketone."}, {"kind": "text", "id": "q2_4", "q": "4(b)(i)", "max": 1, "pts": [["carbohydrate+lipid+protein+nucleic"]], "tips": ["All four classes are in the word bank."]}, {"kind": "choice", "id": "q2_5", "q": "4(b)(ii)", "max": 2, "n": 4, "ans": ["unbranched chain", "branched chain", "single ring", "multiple rings"], "tip": "Look at each skeleton in Figure 3: is it a straight chain, a chain with a branch, one ring or several?"}], "3": [{"kind": "text", "id": "q3_0", "q": "5", "max": 3, "pts": [["monomer+small", "monomer+single", "monomer+join", "monomer+unit"], ["polymer+many", "polymer+chain", "polymer+long"], ["macromolecule+large", "macromolecule+big"]], "tips": ["Monomer: a small molecule that can join to others.", "Polymer: many monomers joined.", "Macromolecule: a very large molecule."]}, {"kind": "text", "id": "q3_1", "q": "6(a)", "max": 3, "pts": [["water"], ["atp"], ["covalent", "bond forms", "new bond", "join", "enzyme", "anabolic", " oh ", "hydroxyl"]], "tips": ["What is released?", "Where does the energy come from?", "What forms between the monomers, and what catalyses it?"]}, {"kind": "text", "id": "q3_2", "q": "6(b)", "max": 3, "pts": [["water+add", "water is added", "adding water", "add water", "uses water", "water is used", "using water", "water+used"], ["break", "released", "split", "releases"], ["small intestine", "stomach", "mouth", " gut", "digest", "liver", "muscle", "intestine", "lysosome"]], "tips": ["What happens to water?", "What happens to the bond?", "Name a place in the body."]}, {"kind": "choice", "id": "q3_3", "q": "7", "max": 3, "n": 6, "ans": ["amino acid", "peptide bond", "nucleotide", "phosphodiester bond", "removed", "added"], "tip": "Use the word bank: amino acid, nucleotide, peptide bond, phosphodiester bond."}, {"kind": "text", "id": "q3_4", "q": "8(a)", "max": 1, "pts": [["single sugar", "one sugar", "monomer", "simple sugar", "sugar unit", "ch2o"]], "tips": ["A single sugar unit: the monomer of carbohydrates."]}, {"kind": "rows", "id": "q3_5", "q": "8(b)", "tip": "Count carbons only. For B and C, look at the –OH on carbon 1: down is alpha, up is beta.", "rows": [{"label": "A", "sel": ["5", "pentose", "ribose"], "pts": []}, {"label": "B", "sel": ["6", "hexose", "α-glucose"], "pts": []}, {"label": "C", "sel": ["6", "hexose", "β-glucose"], "pts": []}]}, {"kind": "rows", "id": "q3_6", "q": "9", "tip": "Give property AND reason each time.", "rows": [{"label": "Solubility", "sel": [], "pts": [[" oh ", "hydroxyl", "hydrogen bond", "polar"]]}, {"label": "Transportability", "sel": [], "pts": [["soluble", "small", "dissolv", "plasma", "phloem", "blood"]]}, {"label": "Stability", "sel": [], "pts": [["stable", "enzyme", "does not break", "doesn t break", "ring"]]}, {"label": "Energy yield in respiration", "sel": [], "pts": [["2870", "30", "lot of energy", "large amount", "much energy", "high", "many c h", "atp"]]}]}], "4": [{"kind": "text", "id": "q4_0", "q": "10(a)", "max": 1, "pts": [["many+monosaccharide", "many+glucose", "many+sugar", "polymer+monosaccharide", "polymer+glucose", "polymer+sugar"]], "tips": ["Include: many monosaccharides, joined by glycosidic bonds."]}, {"kind": "rows", "id": "q4_1", "q": "10(b)", "tip": "All three are alpha-glucose; they differ in branching. Starch (amylose and amylopectin) is in plants, glycogen in animals.", "rows": [{"label": "Monomer", "sel": ["α-glucose", "α-glucose", "α-glucose"], "pts": []}, {"label": "Branched?", "sel": ["unbranched", "branched about every 25 units", "branched about every 10 units"], "pts": []}, {"label": "Overall shape", "sel": ["helix (coiled)", "branched with a helical core", "compact and highly branched"], "pts": []}, {"label": "Found in", "sel": ["plants (starch)", "plants (starch)", "animals (liver and muscle)"], "pts": []}]}, {"kind": "text", "id": "q4_2", "q": "11(a)", "max": 3, "pts": [["compact", "small volume", "space", "coil"], ["water potential", "osmo", "insoluble", "less soluble"], ["cannot leave", "can t leave", "stays in", "large", "membrane"], ["many ends", "ends", "quick", "rapid", "fast"], ["cost", "disadvantage", "extra enzyme", "energy to make"]], "tips": ["Use the prompts: space, water potential, leaving the cell, number of ends, and a cost (discuss)."]}, {"kind": "text", "id": "q4_3", "q": "11(b)", "max": 2, "pts": [["condensation"], ["hydrolysis"]], "tips": ["Condensation builds the store when glucose is plentiful.", "Hydrolysis releases glucose when it is needed."]}, {"kind": "text", "id": "q4_4", "q": "12", "max": 2, "pts": [["carbon 1", "c1", " oh ", "hydroxyl"], ["alpha+starch", "alpha+glycogen", "beta+cellulose"]], "tips": ["Name the one structural difference (the –OH on carbon 1: down in alpha, up in beta).", "Say which polysaccharide each forms."]}, {"kind": "text", "id": "q4_5", "q": "13(a)", "max": 3, "pts": [["beta"], ["rotat", "180", "straight", "not coiled"], ["hydrogen bond"], ["microfibril", "bundle", "parallel"]], "tips": ["Follow the idea chain in the box: beta-glucose → rotated 180° → straight chains → hydrogen bonds → microfibrils."]}, {"kind": "text", "id": "q4_6", "q": "13(b)", "max": 2, "pts": [["burst", "turgid", "turgor", "osmosis", "pressure", "support", "wilt"], ["shape", "direction", "fibre", "fiber", "digest", "cotton", "paper", "timber", "grow", "herbivore", "support"]], "tips": ["Two different consequences: e.g. stops cells bursting / turgor support, controls cell shape, dietary fibre, materials like cotton and paper."]}], "5": [{"kind": "text", "id": "q5_0", "q": "14(a)", "max": 1, "pts": [["recognition", "recognis", "recogniz", "label", "marker", "receptor", "adhesion", "identif", "antigen"]], "tips": ["Think: labels on the cell surface."]}, {"kind": "text", "id": "q5_1", "q": "14(b)", "max": 2, "pts": [["same", "h antigen", "identical", "basic chain", "all have", "similar"], ["last sugar", "terminal", "end", "added", "galactose", "acetylgalactosamine", "nothing"]], "tips": ["A similarity (same H antigen chain).", "The difference (only the last sugar: A, B or nothing for O)."]}, {"kind": "text", "id": "q5_2", "q": "14(c)", "max": 3, "pts": [["anti b", "antibod"], ["agglutin", "clump"], ["group o", "type o", "blood o", "o is", "o negative", "o red", "o blood", "o cells"]], "tips": ["Which antibodies are in group A plasma?", "What happens to the transfused cells?", "Which group has neither A nor B antigens?"]}]}, "models": {"1": [["1", "All except water contain carbon (cellulose, hydrocarbons, keratin, sucrose, carbon). Diamond contains carbon but is not organic, so containing carbon does not always make a substance organic."]], "2": [["2", "Always four, because carbon has four outer-shell electrons and needs four more. Single and double bonds (triple are rare). Other carbon atoms, hydrogen, oxygen, nitrogen, phosphorus, sulfur. Carbon–carbon bonds are strong and stable and each carbon can bond to up to four atoms, so chains, branches and rings form."], ["3(a)", "An organic compound contains carbon and is produced by, or characteristic of, living organisms. Not organic: carbon dioxide, carbonates, hydrogencarbonates, carbides, cyanides, diamond or graphite."], ["3(b)", "Cause: atoms share pairs of electrons so each gets a full outer shell. Consequence: the atoms are held strongly together in fixed directions, so molecules have a definite 3D shape and are stable (enzymes are needed to break them)."], ["4(a)", "A hydroxyl –OH (ethanol); B aldehyde –CHO (propanal); C ketone C=O (propanone); D carboxyl –COOH (ethanoic acid); E amine –NH₂ (ethylamine); F phosphate (methyl phosphate)."], ["4(b)(i)", "Carbohydrates, lipids, proteins and nucleic acids."], ["4(b)(ii)", "A butanoic acid: unbranched chain. B leucine: branched chain. C glucose: single ring. D cholesterol: multiple rings."]], "3": [["5", "Monomer: a small molecule that can join with others of the same type. Polymer: a long molecule of many monomers joined together. Macromolecule: a very large molecule (most, not all, are polymers)."], ["6(a)", "Two monomers join and one molecule of water is released (–OH from one and –H from the other); a new covalent bond forms; it is anabolic, needs energy from ATP and is catalysed by an enzyme."], ["6(b)", "Water is added across the bond between two monomers; the bond breaks and the monomers are released; catabolic and enzyme-catalysed, e.g. amylase hydrolysing starch in the small intestine, or glycogen breakdown in liver cells."], ["7", "Polypeptide: amino acid, peptide bond, water. Nucleic acid: nucleotide, phosphodiester bond, water. Water is removed in condensation and added in hydrolysis in every case."], ["8(a)", "A single sugar unit, the monomer of carbohydrates, general formula (CH₂O)ₙ with n usually 3 to 7."], ["8(b)", "A: 5 carbons, pentose, ribose. B: 6 carbons, hexose, α-glucose. C: 6 carbons, hexose, β-glucose."], ["9", "Solubility: many –OH groups hydrogen bond with water, so it dissolves. Transportability: small and soluble, so it is carried in blood plasma and phloem sap. Stability: the ring is chemically stable; its bonds do not break spontaneously, so enzymes are needed. Energy: complete oxidation releases about 2870 kJ mol⁻¹, enough for about 30 ATP."]], "4": [["10(a)", "A polymer of many monosaccharides joined by glycosidic bonds (formed by condensation)."], ["10(b)", "Monomer: alpha-glucose for all three. Branched: amylose unbranched (1,4 only); amylopectin about every 25 units; glycogen about every 10 (1,4 and 1,6 bonds). Shape: helix; branched with a helical core; compact and highly branched. Found in: plants (starch grains in chloroplasts, seeds, roots, tubers); plants (the other part of starch); animals (granules in liver and muscle)."], ["11(a)", "Compact: coiling and branching store many glucose units in a small volume. Little effect on water potential: insoluble, unlike free glucose which would draw water in by osmosis. Too large to leave the cell. Branching gives many ends for enzymes to work on at once, so glucose is released quickly. Cost: extra enzymes are needed to make the 1,6 branch points."], ["11(b)", "When glucose is plentiful (after a meal), condensation joins alpha-glucose by glycosidic bonds, releasing water, building the store. When glucose is needed (between meals, exercise), hydrolysis adds water to break the bonds and release glucose."], ["12", "Both C₆H₁₂O₆; the –OH on carbon 1 points down in alpha-glucose and up in beta-glucose. Alpha-glucose forms starch and glycogen; beta-glucose forms cellulose."], ["13(a)", "Unbranched polymer of beta-glucose joined by 1,4 glycosidic bonds; every second glucose rotated 180°, so the chain is straight with –OH groups on both sides; hydrogen bonds form between neighbouring parallel chains; many chains bundle into a microfibril with high tensile strength."], ["13(b)", "Any two: resists pressure so cells become turgid rather than bursting; turgid cells support herbaceous plants (loss causes wilting); microfibril direction controls the shape a cell grows into; humans cannot digest it, so it acts as dietary fibre; materials such as cotton, paper and timber are strong."]], "5": [["14(a)", "Cell–cell recognition: the carbohydrate chain projects from the cell surface as a label recognised by other cells and antibodies (also receptors, cell adhesion)."], ["14(b)", "All share the same carbohydrate chain (the H antigen) and are identical except for the terminal sugar: A has N-acetylgalactosamine added, B has galactose added, O has nothing added."], ["14(c)", "Group A plasma contains anti-B antibodies; they bind the B antigens on the donor red cells, which clump together (agglutination), blocking small vessels and breaking open (kidney damage, possibly fatal). Group O red cells are the universal donor: they carry neither A nor B antigen."]]}, "labels": {"q1_0": "1", "q2_0_r0_t": "2 How many covalent bonds does a carbon atom always form, and why?", "q2_0_r1_t": "2 Which types of covalent bond can carbon form?", "q2_0_r2_t": "2 Which other atoms does carbon most often bond to in living organisms?", "q2_0_r3_t": "2 Why can carbon form chains and rings?", "q2_1": "3(a)", "q2_2": "3(b)", "q2_4": "4(b)(i)", "q3_0": "5", "q3_1": "6(a)", "q3_2": "6(b)", "q3_4": "8(a)", "q3_6_r0_t": "9 Solubility", "q3_6_r1_t": "9 Transportability", "q3_6_r2_t": "9 Stability", "q3_6_r3_t": "9 Energy yield in respiration", "q4_0": "10(a)", "q4_2": "11(a)", "q4_3": "11(b)", "q4_4": "12", "q4_5": "13(a)", "q4_6": "13(b)", "q5_0": "14(a)", "q5_1": "14(b)", "q5_2": "14(c)", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '3905e41a-e84c-5b39-a55c-9a76ce38795d', (select id from public.topics where programme = 'IB DP' and code = 'B1.1' limit 1), 'Lipids', 'B1.1 Carbohydrates and lipids · Lesson 2 · SL and HL', '/b11-lesson2/', 'DP1-B1.1-L2', 64, 22 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-B1.1-L2', 'Lipids', '{"marks": {"2": [{"kind": "text", "id": "q2_0", "q": "2", "max": 3, "pts": [["water+polar", "oxygen+partial", "partial negative", "partial positive"], ["non polar", "nonpolar", "no charge", "equally", "uncharged"], ["hydrogen bond"]], "tips": ["Why is water polar?", "Why is a hydrocarbon chain non-polar?", "What follows: no hydrogen bonds with water, so the lipid is excluded."]}, {"kind": "rows", "id": "q2_1", "q": "3", "tip": "Each row needs a structure AND a function. Use the word bank.", "rows": [{"label": "Fats", "sel": [], "pts": [["triglycerid", "glycerol", "saturated", "solid"], ["energy", "insulat", "protect", "animal"]]}, {"label": "Oils", "sel": [], "pts": [["unsaturated", "liquid", "triglycerid"], ["seed", "plant", "energy"]]}, {"label": "Waxes", "sel": [], "pts": [["alcohol", "one fatty acid", "ester"], ["waterproof", "cuticle", "feather", " ear"]]}, {"label": "Steroids", "sel": [], "pts": [["four", " 4 ", "ring", "fused"], ["hormone", "cholesterol", "membrane", "testosterone", "oestradiol", "progesterone", "estrogen", "oestrogen"]]}]}, {"kind": "text", "id": "q2_2", "q": "4", "max": 3, "pts": [[" oh+cooh", "hydroxyl+carboxyl"], ["water"], ["ester"], ["three", " 3 "]], "tips": ["Which groups react (–OH of glycerol, –COOH of fatty acid)?", "What is removed?", "Which bond forms, and how many times?"]}, {"kind": "text", "id": "q2_3", "q": "5", "max": 3, "pts": [["two fatty", "2 fatty"], ["phosphate"], ["water", "condensation"], ["ester", "three", "hydrophilic", "head"]], "tips": ["How many fatty acids?", "What goes on the third position?", "What is released, and what does the product look like?"]}, {"kind": "rows", "id": "q2_4", "q": "6", "tip": "One mark per row. Remember a phospholipid still has three condensations: two fatty acids and one phosphate.", "rows": [{"label": "Number of fatty acids", "sel": ["3", "2"], "pts": []}, {"label": "What is attached to the third position on the glycerol?", "sel": ["a third fatty acid", "a phosphate group"], "pts": []}, {"label": "Number of condensation reactions", "sel": ["3", "3"], "pts": []}, {"label": "Number of water molecules released", "sel": ["3", "3"], "pts": []}, {"label": "Name of the bond formed", "sel": ["ester bond", "ester bond"], "pts": []}, {"label": "Whole molecule hydrophobic, or partly hydrophilic?", "sel": ["entirely hydrophobic", "amphipathic (hydrophilic head)"], "pts": []}]}], "3": [{"kind": "text", "id": "q3_0", "q": "7", "max": 3, "pts": [["hydrocarbon", "chain"], ["carboxyl", "cooh"], ["hydrophilic+hydrophobic", "polar+non polar"]], "tips": ["The chain.", "The group at one end.", "Which end is hydrophilic and which hydrophobic?"]}, {"kind": "rows", "id": "q3_1", "q": "8", "tip": "Use the melting points as evidence: the more kinks, the less closely the molecules pack and the lower the melting point. D breaks the pattern: it is trans.", "rows": [{"label": "Number of C=C double bonds", "sel": ["0", "1", "2", "1"], "pts": []}, {"label": "Saturated, mono- or polyunsaturated?", "sel": ["saturated", "monounsaturated", "polyunsaturated", "monounsaturated"], "pts": []}, {"label": "Shape of the hydrocarbon chain", "sel": ["straight", "one kink", "two kinks", "straight despite the double bond"], "pts": []}, {"label": "How closely can the molecules pack?", "sel": ["very closely", "not closely", "not closely", "very closely"], "pts": []}, {"label": "Solid or liquid at 20 °C?", "sel": ["solid", "liquid", "liquid", "solid"], "pts": []}, {"label": "A typical source", "sel": ["animal fat (butter, lard)", "olive oil", "sunflower or maize oil", "partly hydrogenated oils"], "pts": []}]}, {"kind": "text", "id": "q3_2", "q": "9", "max": 4, "pts": [["same side"], ["opposite"], ["kink", "bend", "bent"], ["pack", "melting"], ["hydrogenat", "industr", "processed", "ldl", "heart"]], "tips": ["Where are the hydrogens in cis? In trans?", "What does each do to the chain shape?", "Link shape to packing and melting point."]}], "4": [{"kind": "rows", "id": "q4_0", "q": "10", "tip": "Name the better store in each row and give the reason, using the figures.", "rows": [{"label": "Energy released per gram", "sel": [], "pts": [["triglycerid", "fat", "lipid"], ["37", "more", "twice", "double", "higher"]]}, {"label": "Water stored with it", "sel": [], "pts": [["triglycerid", "fat", "lipid", "none", "no water", "lighter"]]}, {"label": "Effect on water potential of the cytoplasm", "sel": [], "pts": [["no effect", "little effect", "both", "insoluble", "osmo", "not affect", "doesn t affect", "does not affect"]]}, {"label": "Speed at which it can be mobilised", "sel": [], "pts": [["glycogen"], ["fast", "quick", "rapid"]]}, {"label": "Best use", "sel": [], "pts": [["long term"], ["short term"]]}]}, {"kind": "text", "id": "q4_1", "q": "11", "max": 2, "pts": [["energy", "store", "storage"], ["insulat", "protect", "cushion", "hormone", "leptin"]], "tips": ["One about storage.", "One about insulation, protection or hormones."]}, {"kind": "text", "id": "q4_2", "q": "12", "max": 4, "pts": [["conduct", "insulat"], ["water+25", "water+faster", "marine", "whale", "seal", "aquatic", "walrus"], ["energy store", "buoyan", "streamlin", " fur"], ["cost", "heavy", "mass", "overheat", "hard to lose", "difficult to lose", "active", "warm water"]], "tips": ["Discuss = both sides: how it insulates, where it matters most, extra benefits, and the costs."]}, {"kind": "choice", "id": "q4_3", "q": "13", "max": 2, "n": 3, "ans": ["two", "hydrophilic (phosphate–glycerol)", "hydrophobic (fatty acids)"], "tip": "Two tails, a labelled hydrophilic head and labelled hydrophobic tails. Correct your drawing."}, {"kind": "rows", "id": "q4_4", "q": "14", "tip": "Amphipathic: BOTH a hydrophilic and a hydrophobic region in one molecule.", "rows": [{"label": "Hydrophilic", "sel": [], "pts": [["attract", "dissolv", "polar", "charged", "water loving", "soluble"]]}, {"label": "Hydrophobic", "sel": [], "pts": [["not attract", "insoluble", "non polar", "nonpolar", "cannot form", "not dissolv", "doesn t dissolv", "water fearing", "excluded"]]}, {"label": "Amphipathic", "sel": [], "pts": [["both"]]}]}, {"kind": "text", "id": "q4_5", "q": "15", "max": 4, "pts": [["head+hydrophilic", "head+polar", "phosphate+hydrophilic"], ["tail+hydrophobic", "tail+non polar"], ["face the water", "facing the water", "face water", "facing water", "outward", "towards the water", "towards water", "inward", "point in", "away from water", "away from the water"], ["stable", "spontaneous", "lowest energy", "no energy", "barrier", "self seal"]], "tips": ["Use the four steps in the support box."]}], "5": [{"kind": "rows", "id": "q5_0", "q": "16(a)", "tip": "Look for four fused carbon rings.", "rows": [{"label": "A", "sel": ["✓ steroid"], "pts": []}, {"label": "B", "sel": ["✗ not a steroid"], "pts": []}, {"label": "C", "sel": ["✗ not a steroid"], "pts": []}, {"label": "D", "sel": ["✓ steroid"], "pts": []}]}, {"kind": "text", "id": "q5_1", "q": "16(b)", "max": 1, "pts": [["four+ring", "4+ring", "fused"]], "tips": ["Count the rings."]}, {"kind": "text", "id": "q5_2", "q": "17", "max": 3, "pts": [["non polar", "nonpolar", "hydrophobic", "lipid soluble"], ["small", "diffus", "through the bilayer", "dissolve in", "pass between"], ["inside", "cytoplasm", "nucleus"]], "tips": ["What kind of molecule is a steroid?", "How does it cross?", "So where must the receptor be?"]}, {"kind": "text", "id": "q5_3", "q": "Exit (a)", "max": 2, "pts": [["amphipathic", "hydrophilic head", "head"], ["triglyceride+hydrophobic", "no hydrophilic", "droplet", "three fatty"]], "tips": ["What does a phospholipid have that a triglyceride lacks?"]}, {"kind": "text", "id": "q5_4", "q": "Exit (b)", "max": 2, "pts": [["testosterone+non polar", "steroid", "non polar", "nonpolar"], ["insulin+protein", "large", "water soluble", "receptor", "charged", "polar"]], "tips": ["Compare the two molecules'' size and polarity."]}]}, "models": {"1": [["1(a)", "Water molecules hydrogen bond to each other and exclude the non-polar oil, which is left clustered together (nothing pushes it)."], ["1(b)", "Fat: about 37 kJ per gram against about 17 kJ per gram for carbohydrate, more than twice as much."]], "2": [["2", "Water is polar: oxygen attracts shared electrons more strongly, so water molecules hydrogen bond to each other. A lipid''s hydrocarbon chains are non-polar (carbon and hydrogen share electrons almost equally), so a lipid cannot form hydrogen bonds with water; water bonds to itself and the lipid is excluded and clusters. It is not repelled, just left out."], ["3", "Fats: triglycerides with mostly saturated fatty acids, solid at room temperature; energy storage, insulation and protection in animals. Oils: triglycerides with mostly unsaturated fatty acids, liquid; energy storage in plants, especially seeds. Waxes: one fatty acid joined to a long-chain alcohol, solid and very hydrophobic; waterproofing (leaf cuticle, feathers, earwax). Steroids: four fused carbon rings (three six-membered, one five-membered); cholesterol regulates membrane fluidity; testosterone, oestradiol and progesterone are hormones."], ["4", "The –OH of glycerol reacts with the –COOH of a fatty acid; H and OH are removed as water and a covalent ester bond forms; this happens three times, so three fatty acids attach and three water molecules are released (enzyme-catalysed, needs ATP)."], ["5", "Only two positions on the glycerol receive fatty acids; the third –OH condenses with a phosphate group, again releasing water; three condensations, three water molecules; the product has two hydrophobic tails and a charged, hydrophilic phosphate head."], ["6", "Fatty acids: 3 / 2. Third position: a third fatty acid / a phosphate group. Condensations: 3 / 3. Water released: 3 / 3. Bond: ester / ester (plus a phosphate ester bond). In water: entirely hydrophobic / amphipathic."]], "3": [["7", "A hydrocarbon chain (usually 14 to 20 carbons) with a carboxyl group (–COOH) at one end and a methyl group at the other; the carboxyl end is polar and hydrophilic; the chain is non-polar and hydrophobic; saturated (no C=C) or unsaturated."], ["8", "Double bonds 0, 1 (cis), 2 (both cis), 1 (trans). Saturated, monounsaturated, polyunsaturated, monounsaturated (trans). Straight, one kink, two kinks, straight despite the double bond. Packing: very close, poor, poorest, close. At 20 °C: solid, liquid, liquid, solid. Sources: animal fat (stearic acid), olive oil (oleic), sunflower/maize oil (linoleic), partly hydrogenated oils (elaidic). Kinks prevent close packing, so attractions are weaker and the melting point lower."], ["9", "Cis: the two hydrogens at the double bond are on the same side, putting a kink in the chain. Trans: they are on opposite sides, so the chain stays almost straight. Kinked cis molecules cannot pack closely, so the melting point is low (13 °C); straight trans molecules pack closely like saturated ones (45 °C). Most dietary trans fats come from partial hydrogenation of oils; they raise LDL cholesterol, so many countries restrict them."]], "4": [["10", "Energy: triglyceride, about 37 vs 17 kJ per gram (many C–H bonds). Water: triglyceride, stored without water, while glycogen holds about 2 g per gram. Water potential: both have little effect (triglyceride insoluble; glycogen a large polymer), unlike free glucose. Speed: glycogen, hydrolysed at many ends and usable anaerobically. Best use: triglyceride for long-term storage (and insulation); glycogen for short-term demand."], ["11", "Long-term energy storage as triglycerides; thermal insulation; protection and cushioning of organs; secretes hormones such as leptin."], ["12", "Fat has low thermal conductivity, slowing heat loss and keeping core temperature constant; most valuable in water, which conducts heat about 25× faster than air (whales, seals, walruses); blubber works at depth where fur fails, and also stores energy and gives buoyancy and streamlining. Costs: heavy to carry and build, and it is hard to lose heat when active or in warm water. In cold water the benefits outweigh the costs."], ["13", "A circle labelled \"phosphate–glycerol head (hydrophilic)\" with two wavy lines labelled \"fatty acid tails (hydrophobic)\". Two tails, not one or three."], ["14", "Hydrophilic: attracted to water; polar or charged, dissolves and forms hydrogen bonds with water. Hydrophobic: not attracted to water; non-polar, cannot hydrogen bond with water, insoluble and excluded. Amphipathic: having both a hydrophilic and a hydrophobic region in the same molecule."], ["15", "The phosphate–glycerol head is charged and polar, so hydrophilic; the two hydrocarbon tails are non-polar, so hydrophobic: the molecule is amphipathic. In water the heads face the water on both sides and the tails point inwards, away from it. This is the most stable (lowest energy) arrangement, so it forms spontaneously with no energy or enzymes, giving a stable, self-sealing barrier to charged and large molecules."]], "5": [["16(a)", "A ✓ testosterone. B ✗ a short fatty acid (chain, no rings). C ✗ glucose (one ring containing oxygen). D ✓ cholesterol."], ["16(b)", "Four fused rings (three six-membered and one five-membered) made only of carbon."], ["17", "Steroid hormones are small, non-polar and hydrophobic, so they dissolve in the hydrophobic core and diffuse straight through the bilayer without a transport protein; their receptors must be inside the cell, in the cytoplasm or nucleus."], ["Exit (a)", "A phospholipid is amphipathic (hydrophilic head, hydrophobic tails) so it forms a bilayer; a triglyceride has three fatty acids and no hydrophilic head, so it is hydrophobic all over and forms droplets."], ["Exit (b)", "Testosterone is a small non-polar steroid that dissolves in the hydrophobic core and diffuses through; insulin is a large, water-soluble protein that cannot cross the core, so it binds a receptor on the outside of the membrane."]]}, "labels": {"q1_0": "1(a)", "q1_1": "1(b)", "q2_0": "2", "q2_1_r0_t": "3 Fats", "q2_1_r1_t": "3 Oils", "q2_1_r2_t": "3 Waxes", "q2_1_r3_t": "3 Steroids", "q2_2": "4", "q2_3": "5", "q3_0": "7", "q3_2": "9", "q4_0_r0_t": "10 Energy released per gram", "q4_0_r1_t": "10 Water stored with it", "q4_0_r2_t": "10 Effect on water potential of the cytoplasm", "q4_0_r3_t": "10 Speed at which it can be mobilised", "q4_0_r4_t": "10 Best use", "q4_1": "11", "q4_2": "12", "q4_4_r0_t": "14 Hydrophilic", "q4_4_r1_t": "14 Hydrophobic", "q4_4_r2_t": "14 Amphipathic", "q4_5": "15", "q5_1": "16(b)", "q5_2": "17", "q5_3": "Exit (a)", "q5_4": "Exit (b)", "s6revisit": "Predictions revisited", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '0bf33f8d-efeb-54ad-aeef-6cd0ea7f23df', (select id from public.topics where programme = 'IB DP' and code = 'B1.2' limit 1), 'Proteins: Amino Acids, Peptide Bonds and Denaturation', 'B1.2 Proteins · Lesson 1 · SL and HL', '/b12-lesson1/', 'DP1-B1.2-L1', 42, 31 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-B1.2-L1', 'Proteins: Amino Acids, Peptide Bonds and Denaturation', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "1(a)", "max": 1, "pts": [["haemoglobin+oxygen", "insulin+glucose", "amylase+starch", "antibod+infection", "antibod+pathogen", "collagen+skin", "keratin+hair", "collagen+strength"]], "tips": ["Two proteins, each with its job."]}, {"kind": "text", "id": "q1_1", "q": "1(b)", "max": 1, "pts": [["order", "sequence", "shape", "fold", "combination", "arrangement"]], "tips": ["Link the variable sequence to a variable shape."]}], "2": [{"kind": "choice", "id": "q2_0", "q": "2(a)(b)", "max": 4, "n": 5, "ans": ["alpha carbon", "amine group –NH₂", "carboxyl group –COOH", "R group", "hydrogen atom"], "tip": "Check your drawing against Figure 1: a central alpha carbon carrying –NH₂, –COOH, H and R. Do not forget the H on the alpha carbon."}, {"kind": "choice", "id": "q2_1", "q": "2(c)", "max": 1, "n": 4, "ans": ["amine group", "carboxyl group", "R group", "alpha carbon"], "tip": "All four must be right for the mark. Follow each arrow to the atom it points at."}, {"kind": "text", "id": "q2_2", "q": "3(a)", "max": 1, "pts": [["r group", "side chain", "r "]], "tips": ["Everything else is identical."]}, {"kind": "text", "id": "q2_3", "q": "3(b)", "max": 2, "pts": [["glycine+hydrogen", "glycine+small", "glycine+tiny", "glycine+non polar"], ["glutamic+charge", "glutamic+negative", "glutamic+coo", "glutamic+hydrophilic", "glutamic+polar", "glutamic+ionic"]], "tips": ["Describe glycine''s R group and its effect.", "Describe glutamic acid''s R group (charged) and its effect."]}], "3": [{"kind": "text", "id": "q3_0", "q": "4(a)", "max": 3, "pts": [["dipeptide+two", "dipeptide+2"], ["oligopeptide+short", "oligopeptide+few", "oligopeptide+20"], ["polypeptide+long", "polypeptide+many", "polypeptide+more than"]], "tips": ["Dipeptide: two amino acids.", "Oligopeptide: a short chain.", "Polypeptide: a long chain."]}, {"kind": "text", "id": "q3_1", "q": "4(b)", "max": 1, "pts": [["ribosome+cytoplasm+rough", "ribosome+cytoplasm+er", "ribosome+free+er", "ribosome+free+endoplasmic"]], "tips": ["Ribosomes, and both locations: free in the cytoplasm and on the rough ER."]}, {"kind": "choice", "id": "q3_2", "q": "5(a)", "max": 3, "n": 4, "ans": ["water (H₂O)", "–OH of the carboxyl and –H of the amine", "C of one amino acid to N of the next", "peptide bond"], "tip": "Water, not H₂ or OH; the –OH comes from the carboxyl group and the –H from the amine group; the peptide bond is C–N. Correct your drawing."}, {"kind": "text", "id": "q3_3", "q": "5(b)", "max": 1, "pts": [["anabolic", "not spontaneous", "energy", "builds", "larger molecule"]], "tips": ["What kind of reaction is it?"]}], "4": [{"kind": "text", "id": "q4_0", "q": "6(a)", "max": 2, "pts": [["plant+synthes", "plant+make", "plant+nitrate", "plant+all twenty", "plant+all 20"], ["animal+diet", "animal+eat", "animal+food", "animal+digest", "animal+cannot"]], "tips": ["Plants: synthesise all twenty from nitrate and photosynthesis products.", "Animals: obtain some from the diet. Both sides are needed."]}, {"kind": "text", "id": "q4_1", "q": "6(b)", "max": 2, "pts": [["essential+cannot", "essential+can t", "essential+not able", "essential+unable"], ["non essential+can synthes", "non essential+can make", "non essential+can be made", "non essential+can be synthes", "non essential+body makes", "non essential+produce"]], "tips": ["Essential: the body cannot SYNTHESISE it (\"the body needs it\" scores zero).", "Non-essential: the body can synthesise it."]}, {"kind": "choice", "id": "q4_2", "q": "7(a)", "max": 1, "n": 2, "ans": ["lysine", "methionine"], "tip": "The limiting amino acid is the one with the LOWER percentage of the requirement."}, {"kind": "text", "id": "q4_3", "q": "7(b)", "max": 2, "pts": [["all nine", "all essential", "runs out", "stops", "limit"], ["lysine", "cannot be stored", "not stored", "deaminat", "urea", "44"]], "tips": ["Protein synthesis needs every essential amino acid at once.", "Use the lysine figure, and what happens to the surplus of the others."]}, {"kind": "text", "id": "q4_4", "q": "7(c)", "max": 1, "pts": [["combin", "complementary", "githeri", "maize and beans", "rice and lentils", "together", "soya", "quinoa"]], "tips": ["Cereals lack lysine and legumes lack methionine: what is the fix?"]}, {"kind": "text", "id": "q4_5", "q": "8(a)", "max": 1, "pts": [["20", "twenty"]], "tips": ["It is in the notes."]}, {"kind": "text", "id": "q4_6", "q": "8(b)", "max": 2, "pts": [["20 x 20 x 20", "20x20x20", "20 20 20", "20 3", "cubed", "power", "20*20*20"], ["8000", "8 000"]], "tips": ["20 choices at each of three positions: 20 × 20 × 20 (not 20 × 3).", "Work out the answer."]}, {"kind": "text", "id": "q4_7", "q": "8(c)", "max": 2, "pts": [["any order", "any position", "sequence", "20n", "20 n", "any of the twenty", "any amino acid"], ["length", "no limit", "any length", "no upper limit", "titin", "long"]], "tips": ["Any amino acid at any position.", "No limit to chain length."]}], "5": [{"kind": "text", "id": "q5_0", "q": "9(a)", "max": 2, "pts": [["shape", "conformation", "structure"], ["function", "permanent", "no longer work", "stops working", "cannot work"]], "tips": ["A change in 3D shape...", "...that causes loss of function."]}, {"kind": "text", "id": "q5_1", "q": "9(b)", "max": 2, "pts": [["peptide"], ["sequence", "primary structure+same", "primary structure+unchanged", "unchanged", "same order"]], "tips": ["Name the bond.", "So what happens to the amino acid sequence?"]}, {"kind": "text", "id": "q5_2", "q": "10(a)", "max": 3, "pts": [["kinetic", "collision"], ["vibrat", "hydrogen bond", "ionic", "weak", "interactions"], ["unfold", "active site", "denature", "shape change", "changes shape", "function"]], "tips": ["Up to the optimum: kinetic energy and collisions.", "Above it: vibration breaks weak interactions.", "Result: unfolds, active site no longer complementary."]}, {"kind": "text", "id": "q5_3", "q": "10(b)", "max": 3, "pts": [["hydrogen ion", "h ion", "proton", "concentration"], ["r group+charge", "charge+r group", "coo", "nh3"], ["ionic", "unfold", "tertiary", "shape", "denature"]], "tips": ["pH change alters H⁺ concentration.", "This changes the charge on R groups (–COO⁻, –NH₃⁺).", "So ionic bonds break and the protein unfolds."]}, {"kind": "text", "id": "q5_4", "q": "10(c)", "max": 1, "pts": [["stomach+intestine", "different part", "different place", "where it works", "acid+alkaline"]], "tips": ["Where does each enzyme work?"]}]}, "models": {"1": [["1(a)", "Any two with a correct function: haemoglobin transports oxygen; insulin regulates blood glucose; amylase digests starch; antibodies bind pathogens; collagen gives strength to skin; keratin forms hair."], ["1(b)", "The twenty amino acids can be joined in any order and in chains of any length, so an enormous number of sequences is possible; each folds into a different 3D shape, and the shape determines the function."]], "2": [["2(a)(b)", "A central alpha carbon bonded to an amine group (–NH₂), a carboxyl group (–COOH, with C=O and O–H), a hydrogen atom and an R group. Common losses: the H on the alpha carbon left out; –COOH drawn without the double-bonded O; R bonded to the nitrogen."], ["2(c)", "A amine group (–NH₂); B carboxyl group (–COOH); C R group; D alpha carbon."], ["3(a)", "The R group (side chain)."], ["3(b)", "Glycine''s R group is a single hydrogen: tiny and non-polar, so the chain can bend tightly. Glutamic acid''s R group ends in a carboxyl that ionises to –COO⁻: negatively charged and hydrophilic, so it sits on the surface in contact with water and can form ionic bonds."]], "3": [["4(a)", "Dipeptide: two amino acids joined by one peptide bond. Oligopeptide: a short chain, roughly 2 to 20 amino acids. Polypeptide: a long chain of many amino acids, usually more than 20, joined by peptide bonds."], ["4(b)", "On ribosomes: free in the cytoplasm or attached to the rough endoplasmic reticulum."], ["5(a)", "Two amino acids with R₁ and R₂; the product with a C–N peptide bond circled; one molecule of water released, formed from the –OH of the first amino acid''s carboxyl group and an –H of the second''s amine group."], ["5(b)", "Condensation is anabolic: it builds a larger molecule and is not energetically spontaneous, so energy from ATP is needed to drive it."]], "4": [["6(a)", "Plant cells synthesise all twenty amino acids, using nitrate or ammonium from the soil and carbon compounds from photosynthesis; animal cells can make only some, so the rest must come from digesting dietary protein."], ["6(b)", "Essential: the body cannot synthesise it (or not fast enough), so it must be supplied in the diet; nine for adults. Non-essential: the body can synthesise it, usually from another amino acid, so it need not be eaten."], ["7(a)", "Lysine in maize (44 %); methionine in beans (55 %)."], ["7(b)", "Protein synthesis needs all nine essential amino acids present together and stops when one runs out; maize gives only 44 % of the lysine requirement, so lysine limits how much protein is made, and the surplus of the others cannot be stored (it is deaminated and excreted as urea)."], ["7(c)", "No single plant staple supplies all nine essential amino acids in adequate amounts (cereals low in lysine, legumes low in methionine), so complementary plant proteins must be combined, e.g. maize with beans (githeri), rice with lentils."], ["8(a)", "Twenty."], ["8(b)", "20 × 20 × 20 = 20³ = 8000. (20 × 3 = 60 scores zero.)"], ["8(c)", "Any of the twenty amino acids can occupy any position, so the number of sequences rises as 20ⁿ (20¹⁰⁰ ≈ 10¹³⁰ for a small protein); and there is no upper limit to chain length, so no finite number can be written down."]], "5": [["9(a)", "A change in the three-dimensional conformation of a protein that results in the loss of its biological function (usually permanent)."], ["9(b)", "Peptide bonds are not broken, so the amino acid sequence (primary structure) is unchanged; only the weak interactions holding the 3D shape are disrupted, which is why denaturation is not digestion."], ["10(a)", "Up to the optimum, kinetic energy and successful collisions increase, so the rate rises; above it, increased vibration breaks the hydrogen bonds, ionic bonds and hydrophobic interactions holding the tertiary structure; the protein unfolds, the active site is no longer complementary to the substrate and function is lost permanently."], ["10(b)", "A pH change alters the H⁺ concentration; this changes the charge on ionisable R groups (at low pH –COO⁻ becomes –COOH; at high pH –NH₃⁺ becomes –NH₂); ionic bonds between oppositely charged R groups break and hydrogen bonding is disrupted, so the tertiary structure changes and function is lost."], ["10(c)", "Each works in a different part of the gut: pepsin in the stomach (HCl, pH about 2), trypsin in the small intestine (hydrogencarbonate, pH about 8); each is stable and correctly shaped only at the pH where it works."]]}, "labels": {"q1_0": "1(a)", "q1_1": "1(b)", "q2_2": "3(a)", "q2_3": "3(b)", "q3_0": "4(a)", "q3_1": "4(b)", "q3_3": "5(b)", "q4_0": "6(a)", "q4_1": "6(b)", "q4_3": "7(b)", "q4_4": "7(c)", "q4_5": "8(a)", "q4_6": "8(b)", "q4_7": "8(c)", "q5_0": "9(a)", "q5_1": "9(b)", "q5_2": "10(a)", "q5_3": "10(b)", "q5_4": "10(c)", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '896b5148-73f1-5971-8ece-794ea170373e', (select id from public.topics where programme = 'IB DP' and code = 'B1.2' limit 1), 'AHL Proteins: R Groups and the Levels of Structure', 'B1.2 Proteins · Lesson 2 · HL only', '/b12-lesson2/', 'DP1-B1.2-L2', 42, 32 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-B1.2-L2', 'AHL Proteins: R Groups and the Levels of Structure', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "1(a)", "max": 1, "pts": [["r group", "side chain"]], "tips": ["Only one part varies."]}, {"kind": "text", "id": "q1_1", "q": "1(b)", "max": 1, "pts": [["shape", "fold", "conformation", "function"]], "tips": ["Link R group chemistry to shape and function."]}], "2": [{"kind": "rows", "id": "q2_0", "q": "2", "tip": "Each row needs the right choices and what the R group contains.", "rows": [{"label": "Non-polar", "sel": ["hydrophobic", "interior, away from water"], "pts": [["carbon+hydrogen", "hydrocarbon"]]}, {"label": "Polar, uncharged", "sel": ["hydrophilic", "surface, in contact with water"], "pts": [["oxygen", "nitrogen", "electronegative", " oh ", " sh ", "conh2", "hydroxyl"]]}, {"label": "Acidic (negative)", "sel": ["hydrophilic", "surface, in contact with water"], "pts": [["carboxyl", "coo", "cooh"]]}, {"label": "Basic (positive)", "sel": ["hydrophilic", "surface, in contact with water"], "pts": [["amine", "nh3", "nh2", "amino"]]}]}, {"kind": "text", "id": "q2_1", "q": "3(a)", "max": 2, "pts": [["electronegativ", "evenly", "equally", "no partial"], ["hydrogen bond"]], "tips": ["Carbon and hydrogen have almost the same electronegativity.", "So no hydrogen bonds with water."]}, {"kind": "text", "id": "q2_2", "q": "3(b)", "max": 2, "pts": [["ionic", "opposite", "negative+positive", "attract"], ["serine+hydrogen bond", "serine+uncharged", "serine+polar", "weaker"]], "tips": ["Glutamic acid is negative, lysine positive: what bond forms?", "What can two serines form instead?"]}], "3": [{"kind": "choice", "id": "q3_0", "q": "4(a)", "max": 1, "n": 3, "ans": ["nitrogen", "alpha carbon", "carbonyl carbon"], "tip": "N–Cα–C. The R groups are not part of the backbone."}, {"kind": "text", "id": "q3_1", "q": "4(b)", "max": 1, "pts": [["three dimensional", "3d", "shape", "arrangement"]], "tips": ["Its precise 3D shape."]}, {"kind": "text", "id": "q3_2", "q": "4(c)", "max": 2, "pts": [["sequence", "order"], ["peptide"]], "tips": ["Number and sequence of amino acids.", "Name the bond."]}, {"kind": "choice", "id": "q3_3", "q": "4(d)", "max": 1, "n": 1, "ans": ["the N-terminal (free amine group)"], "tip": "It is always written N-terminal first."}, {"kind": "text", "id": "q3_4", "q": "5(a)", "max": 2, "pts": [["transcri", "mrna", "codon"], ["translat", "ribosome", "one amino acid", "each codon"]], "tips": ["DNA to mRNA codons.", "Codons to amino acids at the ribosome."]}, {"kind": "text", "id": "q3_5", "q": "5(b)", "max": 2, "pts": [["r group+position", "r group+fixed", "same interactions", "r groups+same"], ["lowest", "stable", "free energy", "most stable"]], "tips": ["The sequence fixes where every R group is.", "The chain folds into the most stable (lowest energy) arrangement, which is always the same."]}], "4": [{"kind": "text", "id": "q4_0", "q": "6(a)", "max": 1, "pts": [["helix", "sheet", "regular", "repeating", "folding of the backbone", "coil"]], "tips": ["Regular, repeating folding: helix or sheet."]}, {"kind": "text", "id": "q4_1", "q": "6(b)", "max": 2, "pts": [["hydrogen bond"], ["c o+n h", "oxygen+hydrogen", "carbonyl+n h", "carbonyl+amine", "c=o+n-h"]], "tips": ["Name the bond.", "Name both atoms: the O of C=O and the H of N–H."]}, {"kind": "text", "id": "q4_2", "q": "6(c)", "max": 1, "pts": [["backbone"]], "tips": ["Where are the C=O and N–H groups?"]}, {"kind": "choice", "id": "q4_3", "q": "7(a)", "max": 1, "n": 2, "ans": ["alpha helix", "beta pleated sheet"], "tip": "A coil or a zig-zag sheet?"}, {"kind": "text", "id": "q4_4", "q": "7(b)", "max": 1, "pts": [["parallel+right angle", "parallel+perpendicular", "axis+between strands", "parallel+across", "same chain+between strands", "along+across", "axis+strands"]], "tips": ["In the helix they run along the axis; in the sheet, across between strands."]}, {"kind": "text", "id": "q4_5", "q": "7(c)", "max": 1, "pts": [["many", "large number", "lots", "numerous", "collective"]], "tips": ["How many are there?"]}], "5": [{"kind": "rows", "id": "q5_0", "q": "8(i)", "tip": "Polar; oppositely charged; two cysteines; non-polar.", "rows": [{"label": "Hydrogen bond", "sel": [], "pts": [["polar", " oh ", "serine", "threonine"]]}, {"label": "Ionic bond", "sel": [], "pts": [["charged", "coo", "nh3", "opposite", "positive", "negative", "acidic", "basic"]]}, {"label": "Disulfide bridge", "sel": [], "pts": [["cysteine"]]}, {"label": "Hydrophobic interaction", "sel": [], "pts": [["non polar", "nonpolar", "hydrocarbon", "valine", "leucine", "phenylalanine"]]}]}, {"kind": "rows", "id": "q5_1", "q": "8(ii)", "tip": "Disulfide bridges are covalent and survive heat; ionic bonds are the ones broken by pH.", "rows": [{"label": "Hydrogen bond", "sel": ["weak, but numerous", "heat and extremes of pH"], "pts": []}, {"label": "Ionic bond", "sel": ["stronger than a hydrogen bond", "a change in pH that removes charges"], "pts": []}, {"label": "Disulfide bridge", "sel": ["strong: covalent", "only reducing agents, not heat or moderate pH"], "pts": []}, {"label": "Hydrophobic interaction", "sel": ["weak individually, strong collectively", "detergents, non-polar solvents and heat"], "pts": []}]}, {"kind": "text", "id": "q5_2", "q": "9(a)", "max": 3, "pts": [["non polar+interior", "non polar+inside", "non polar+core", "hydrophobic+interior", "hydrophobic+inside", "hydrophobic+core", "nonpolar+inside", "nonpolar+core"], ["polar+outside", "polar+surface", "hydrophilic+surface", "hydrophilic+outside"], ["soluble", "fold", "shape", "determines"]], "tips": ["Where do non-polar R groups go, and why?", "Where do polar R groups go?", "What does that do to the fold?"]}, {"kind": "text", "id": "q5_3", "q": "9(b)", "max": 2, "pts": [["ionic", "attract"], ["coo+cooh", "protonat", "gain", "uncharged", "break", "unfold", "denature"]], "tips": ["Opposite charges form ionic bonds that hold the fold.", "Low pH: –COO⁻ gains H⁺, the charge goes, the bond breaks."]}, {"kind": "text", "id": "q5_4", "q": "10(a)", "max": 1, "pts": [["cysteine+covalent"]], "tips": ["Name the amino acid AND the bond type."]}, {"kind": "text", "id": "q5_5", "q": "10(b)", "max": 2, "pts": [["outside", "heat", "sunlight", "stress", "exposed", "pull", "strong"], ["cytoplasm+stable", "controlled", "change shape", "flexib", "reducing"]], "tips": ["Hair is exposed to harsh conditions: what does it need?", "Enzymes work in controlled conditions and need flexibility."]}]}, "models": {"1": [["1(a)", "The R group (side chain)."], ["1(b)", "The R groups determine how the chain folds and what chemistry the folded protein can do; twenty different R groups allow an enormous number of shapes and functions, whereas two kinds could fold in very few useful ways."]], "2": [["2", "Non-polar: carbon and hydrogen only; hydrophobic; interior. Polar uncharged: an electronegative atom, usually O or N (–OH, –SH, –CONH₂); hydrophilic; surface. Acidic: a carboxyl that loses H⁺ to become –COO⁻; hydrophilic; surface. Basic: an amine that gains H⁺ to become –NH₃⁺; hydrophilic; surface."], ["3(a)", "Carbon and hydrogen have almost the same electronegativity, so electrons are shared evenly and no partial charges arise; it cannot hydrogen bond with water, so water bonds to itself and the R group is excluded."], ["3(b)", "Glutamic acid is negatively charged (–COO⁻) and lysine positively charged (–NH₃⁺), so they attract and form an ionic bond; two serines are polar but uncharged, so they can only form a weaker hydrogen bond."]], "3": [["4(a)", "Nitrogen, the alpha carbon and the carbonyl carbon, repeating as N–Cα–C."], ["4(b)", "The precise three-dimensional shape of the protein: the arrangement in space of all its atoms."], ["4(c)", "The number and sequence of amino acids in the polypeptide, joined by covalent peptide bonds (no other bond type is involved)."], ["4(d)", "From the N-terminal (free amine group) to the C-terminal."], ["5(a)", "The base sequence of the gene is transcribed into a sequence of codons in mRNA; at the ribosome each codon is translated into one specific amino acid, so the order of bases sets the order of amino acids."], ["5(b)", "The fixed sequence fixes the position of every R group, so the same interactions are available every time; the chain folds into its lowest free energy (most stable) arrangement, which is the same on every occasion."]], "4": [["6(a)", "Regular, repeating folding of part of the polypeptide backbone into an alpha helix or beta pleated sheet, stabilised by hydrogen bonds."], ["6(b)", "Hydrogen bonds, between the oxygen of the C=O group of one peptide bond and the hydrogen of the N–H group of another."], ["6(c)", "Both the C=O and N–H involved are part of the backbone, identical in every protein; the R groups project away and take no part in the bonding."], ["7(a)", "A is the alpha helix; B is the beta pleated sheet."], ["7(b)", "In the alpha helix the hydrogen bonds run roughly parallel to the long axis, between amino acids four apart in the same chain; in the beta sheet they run between neighbouring strands, at right angles to them."], ["7(c)", "There are very many hydrogen bonds acting together along the structure, so their combined effect is strong."]], "5": [["8(i)", "Hydrogen bond: polar uncharged R groups (e.g. –OH of serine and threonine). Ionic bond: a negative –COO⁻ (aspartic/glutamic acid) and a positive –NH₃⁺ (lysine, arginine, histidine). Disulfide bridge: the –CH₂SH of two cysteines. Hydrophobic interaction: non-polar R groups (valine, leucine, phenylalanine)."], ["8(ii)", "Hydrogen bond: weak but numerous; heat, extremes of pH. Ionic bond: stronger than a hydrogen bond; a change in pH that removes the charges (and heat). Disulfide bridge: strong covalent; not by heat or moderate pH, only reducing agents. Hydrophobic interaction: weak individually, strong collectively; non-polar solvents, detergents, heat."], ["9(a)", "Non-polar R groups cannot hydrogen bond with water, so they are pushed into the interior, forming a hydrophobic core; polar R groups hydrogen bond with water and end up on the surface; this makes the protein soluble and largely dictates how the chain folds."], ["9(b)", "Oppositely charged R groups attract and form ionic bonds, holding distant parts of the chain together; if pH falls sharply, H⁺ protonates –COO⁻ to uncharged –COOH, the attraction is lost, the ionic bonds break and the protein unfolds (denaturation)."], ["10(a)", "Cysteine; a covalent disulfide bond between the sulfur atoms of two cysteine R groups."], ["10(b)", "Hair is outside the controlled conditions of the cell, exposed to heat, sunlight, water and stress, so keratin needs strong covalent cross-links; cytoplasmic enzymes work in stable conditions and often change shape slightly on binding, so weaker, flexible interactions suffice (the cytoplasm is also a reducing environment)."]]}, "labels": {"q1_0": "1(a)", "q1_1": "1(b)", "q2_0_r0_t": "2 Non-polar", "q2_0_r1_t": "2 Polar, uncharged", "q2_0_r2_t": "2 Acidic (negative)", "q2_0_r3_t": "2 Basic (positive)", "q2_1": "3(a)", "q2_2": "3(b)", "q3_1": "4(b)", "q3_2": "4(c)", "q3_4": "5(a)", "q3_5": "5(b)", "q4_0": "6(a)", "q4_1": "6(b)", "q4_2": "6(c)", "q4_4": "7(b)", "q4_5": "7(c)", "q5_0_r0_t": "8(i) Hydrogen bond", "q5_0_r1_t": "8(i) Ionic bond", "q5_0_r2_t": "8(i) Disulfide bridge", "q5_0_r3_t": "8(i) Hydrophobic interaction", "q5_2": "9(a)", "q5_3": "9(b)", "q5_4": "10(a)", "q5_5": "10(b)", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '31acb4e0-3b62-5859-b3f0-ac5abc41b373', (select id from public.topics where programme = 'IB DP' and code = 'B1.2' limit 1), 'AHL Proteins: Arrangement, Quaternary Structure, Collagen and Insulin', 'B1.2 Proteins · Lesson 3 · HL only', '/b12-lesson3/', 'DP1-B1.2-L3', 41, 33 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-B1.2-L3', 'AHL Proteins: Arrangement, Quaternary Structure, Collagen and Insulin', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "1(a)", "max": 1, "pts": [["r group", "side chain"]], "tips": ["Which part of the amino acid?"]}, {"kind": "text", "id": "q1_1", "q": "1(b)", "max": 1, "pts": [["outside+tail", "outside+non polar", "surface+tail", "surface+non polar", "contact+tail", "outer+tail", "outer+lipid", "outside+lipid", "surface+lipid", "fatty acid"]], "tips": ["What is the middle of the bilayer made of?"]}], "2": [{"kind": "text", "id": "q2_0", "q": "2(a)", "max": 3, "pts": [["hydrophobic+interior", "hydrophobic+inside", "hydrophobic+core", "hydrophobic+centre", "hydrophobic+center"], ["hydrophilic+surface", "hydrophilic+outside", "hydrophilic+outer"], ["sequence", "primary", "hydrogen bond", "cannot", "excluded"]], "tips": ["Hydrophobic inside, and why.", "Hydrophilic outside, and why.", "Link it to the sequence."]}, {"kind": "text", "id": "q2_1", "q": "2(b)", "max": 2, "pts": [["surface", "outside"], ["hydrogen bond", "water", "dissolv"]], "tips": ["What covers the surface?", "How does that interact with water?"]}, {"kind": "text", "id": "q2_2", "q": "2(c)", "max": 1, "pts": [["compact", "spherical", "ball", "round"]], "tips": ["What shape does burying the hydrophobic residues give?"]}], "3": [{"kind": "text", "id": "q3_0", "q": "3(a)", "max": 3, "pts": [["hydrophobic+tail", "hydrophobic+bilayer", "hydrophobic+membrane", "non polar+tail"], ["hydrophilic+cytoplasm", "hydrophilic+water", "hydrophilic+extracellular", "hydrophilic+outside", "hydrophilic+ends"], ["reverse", "opposite", "helix", "twenty", "20"]], "tips": ["Membrane-spanning region: which amino acids face the tails?", "Regions in the watery compartments?", "Compare with a soluble protein."]}, {"kind": "text", "id": "q3_1", "q": "3(b)", "max": 1, "pts": [["hydrophilic+through", "hydrophilic+interior", "hydrophilic+pass", "anchor", "unfavourable", "unfavorable"]], "tips": ["What would have to cross the non-polar middle?"]}, {"kind": "text", "id": "q3_2", "q": "4(a)", "max": 2, "pts": [["hydrophobic+outside", "hydrophobic+tail", "hydrophobic+bilayer", "hydrophobic+outer"], ["hydrophilic+pore", "hydrophilic+lin", "hydrophilic+channel", "hydrophilic+inside"]], "tips": ["Outer surface in the bilayer.", "Lining of the pore."]}, {"kind": "text", "id": "q3_3", "q": "4(b)", "max": 2, "pts": [["water", "aqueous"], ["non polar", "nonpolar", "hydrophobic", "facilitated", "cannot cross", "can t cross"]], "tips": ["What does the hydrophilic lining hold?", "Why can ions not cross the bilayer directly?"]}], "4": [{"kind": "text", "id": "q4_0", "q": "5(a)", "max": 2, "pts": [["two or more", "more than one", "several", "multiple", "2 or more"], ["subunit", "arrangement", "linked", "held together", "bonded together"]], "tips": ["How many chains?", "What is the quaternary structure itself?"]}, {"kind": "text", "id": "q4_1", "q": "5(b)", "max": 1, "pts": [["hydrogen+ionic+disulfide", "hydrogen+ionic+hydrophobic", "same as tertiary"]], "tips": ["The tertiary interactions, not peptide bonds."]}, {"kind": "text", "id": "q4_2", "q": "5(c)", "max": 1, "pts": [["one chain", "single", "only one", "two or more", "more than one"]], "tips": ["Quaternary needs at least two chains."]}, {"kind": "text", "id": "q4_3", "q": "6(a)", "max": 2, "pts": [["both", "polypeptide"], ["prosthetic", "non polypeptide", "only polypeptide", "polypeptide only"]], "tips": ["A similarity.", "The difference: a prosthetic group."]}, {"kind": "text", "id": "q4_4", "q": "6(b)", "max": 2, "pts": [["haemoglobin+haem", "hemoglobin+heme", "hemoglobin+haem", "haemoglobin+heme", "glycoprotein+carbohydrate", "lipoprotein+lipid", "cytochrome+haem", "cytochrome+heme"], ["insulin", "collagen", "lysozyme"]], "tips": ["Conjugated example with its prosthetic group.", "Non-conjugated example."]}, {"kind": "text", "id": "q4_5", "q": "6(c)", "max": 1, "pts": [["iron", "fe", "haem", "heme"]], "tips": ["What does the oxygen actually bind to?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "7(a)", "max": 3, "pts": [["triple helix", "three chains", "three polypeptide", "3 chains", "3 polypeptide"], ["glycine", "repetitive", "proline", "every third"], ["stagger", "cross link", "crosslink", "fibril", "fibre", "fiber"]], "tips": ["Three chains in a triple helix.", "The repeating sequence.", "How the molecules are arranged into fibrils."]}, {"kind": "text", "id": "q5_1", "q": "7(b)", "max": 2, "pts": [["centre", "center", "close", "crowded", "tight", "pack"], ["hydrogen atom", "smallest", "small", "single h"]], "tips": ["What is it like at the centre of the triple helix?", "What is special about glycine''s R group?"]}, {"kind": "text", "id": "q5_2", "q": "7(c)", "max": 1, "pts": [["tendon+pull", "tendon+muscle", "ligament", "skin+stretch", "artery+stretch", "resist+pull", "pulling"]], "tips": ["Link the function to resisting a PULLING force."]}, {"kind": "text", "id": "q5_3", "q": "8(a)", "max": 2, "pts": [["two chains", "2 chains", "two polypeptide", "a chain+b chain", "51"], ["disulfide", "disulphide"]], "tips": ["How many chains and amino acids?", "What holds the chains together?"]}, {"kind": "text", "id": "q5_4", "q": "8(b)", "max": 1, "pts": [["hydrophilic+surface", "hydrophilic+outside", "polar+surface", "soluble"]], "tips": ["What is on its surface?"]}, {"kind": "text", "id": "q5_5", "q": "8(c)", "max": 2, "pts": [["only", "specific", "target"], ["complementary", "receptor+shape", "fits"]], "tips": ["It binds only to its own receptor.", "Its shape is complementary to the receptor."]}, {"kind": "rows", "id": "q5_6", "q": "9", "tip": "Fibrous: long, repetitive, insoluble, structural, stable. Globular: the opposite on each row.", "rows": [{"label": "Overall shape", "sel": ["long, narrow and thread-like", "compact and roughly spherical"], "pts": []}, {"label": "Amino acid sequence", "sel": ["highly repetitive", "irregular"], "pts": []}, {"label": "Solubility in water", "sel": ["insoluble", "soluble"], "pts": []}, {"label": "Role in the body", "sel": ["structural", "metabolic"], "pts": []}, {"label": "Stability to heat and pH", "sel": ["stable over a wide range", "denatures readily"], "pts": []}]}]}, "models": {"1": [["1(a)", "Its R group: non-polar R groups make it hydrophobic; polar or charged R groups make it hydrophilic."], ["1(b)", "On the outside of the protein, in contact with the fatty acid tails, because the centre of the bilayer is non-polar."]], "2": [["2(a)", "Hydrophobic amino acids are in the interior, forming a hydrophobic core, because their non-polar R groups cannot hydrogen bond with water; hydrophilic amino acids are on the outer surface, hydrogen bonding with water; this follows from the primary structure, which fixes how the chain must fold to bury the hydrophobic residues."], ["2(b)", "The surface is covered in polar and charged R groups; these hydrogen bond and interact ionically with water, which surrounds the protein and keeps it in solution, so it can be carried in plasma or move in the cytoplasm."], ["2(c)", "Burying the hydrophobic residues pulls the chain into a compact, roughly spherical ball rather than a long thread."]], "3": [["3(a)", "The membrane-spanning region has hydrophobic amino acids on its surface in contact with the fatty acid tails (often an alpha helix of about twenty non-polar residues); the regions in the cytoplasm and extracellular fluid have hydrophilic surfaces; this is the reverse of a soluble protein."], ["3(b)", "Flipping would drag the hydrophilic regions through the non-polar interior of the bilayer, which is energetically very unfavourable, so the protein is held in a fixed orientation."], ["4(a)", "The outer surface within the bilayer is hydrophobic, in contact with the tails; the amino acids lining the central pore are hydrophilic, with polar or charged R groups facing inwards."], ["4(b)", "The hydrophilic lining holds a column of water, making an aqueous pathway through the membrane; ions cannot cross the non-polar interior of the bilayer directly, but can pass through this pore by facilitated diffusion."]], "4": [["5(a)", "Present when a functional protein has two or more polypeptide chains (subunits); the arrangement of those linked subunits is the quaternary structure."], ["5(b)", "The same interactions as tertiary structure: hydrogen bonds, ionic bonds, disulfide bridges and hydrophobic interactions (not peptide bonds)."], ["5(c)", "It has only one polypeptide chain, and quaternary structure needs two or more; its highest level is tertiary."], ["6(a)", "Both consist of polypeptide chains folded into a specific conformation; a non-conjugated protein is polypeptide only, while a conjugated protein also has a non-polypeptide prosthetic group, permanently bound."], ["6(b)", "Conjugated: haemoglobin, prosthetic group haem (each with Fe²⁺). Non-conjugated: insulin (also collagen, lysozyme)."], ["6(c)", "Oxygen binds to the Fe²⁺ in the haem group, not to the polypeptide, so without haem there is nothing for oxygen to bind."]], "5": [["7(a)", "Three polypeptide chains wound into a triple helix held by hydrogen bonds; a highly repetitive sequence with glycine at every third position and much proline; many triple helices staggered and joined by covalent cross-links into fibrils and fibres."], ["7(b)", "At the centre of the triple helix the chains are packed extremely closely, so only a very small R group fits; glycine''s R group is a single hydrogen atom, the smallest, so only glycine fits there."], ["7(c)", "In a tendon it transmits the pull of a contracting muscle to a bone without stretching or tearing (or skin/artery walls resisting stretching; ligaments holding bone to bone)."], ["8(a)", "51 amino acids in two chains, A (21) and B (30), held together by two disulfide bridges; compact and globular."], ["8(b)", "Its hydrophilic R groups are on the surface, hydrogen bonding with water, so insulin dissolves in plasma and is carried to target cells."], ["8(c)", "Specificity: insulin binds only its own receptor and so affects only certain target cells (liver, muscle, adipose); its precise conformation is complementary to the receptor''s binding site, so no other molecule fits."], ["9", "Shape: long, narrow, thread-like / compact, roughly spherical. Sequence: highly repetitive (glycine every third) / irregular. Solubility: insoluble / soluble. Role: structural (tensile strength) / metabolic (hormone regulating blood glucose). Stability: stable over a wide range / denatures readily."], ["E1", "Hydrophobic (non-polar) amino acids, because that surface is in contact with the non-polar fatty acid tails."], ["E2", "Water is polar, so it hydrogen bonds with the polar R groups lining the pore and moves through an aqueous pathway; a non-polar lining would exclude it."], ["E3", "H⁺ is positively charged and the two arginine R groups are also positive, so like charges repel and the proton is turned back: the gate is electrostatic, not a matter of size."]]}, "labels": {"q1_0": "1(a)", "q1_1": "1(b)", "q2_0": "2(a)", "q2_1": "2(b)", "q2_2": "2(c)", "q3_0": "3(a)", "q3_1": "3(b)", "q3_2": "4(a)", "q3_3": "4(b)", "q4_0": "5(a)", "q4_1": "5(b)", "q4_2": "5(c)", "q4_3": "6(a)", "q4_4": "6(b)", "q4_5": "6(c)", "q5_0": "7(a)", "q5_1": "7(b)", "q5_2": "7(c)", "q5_3": "8(a)", "q5_4": "8(b)", "q5_5": "8(c)", "q5_7": "E1", "q5_8": "E2", "q5_9": "E3", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '0f61a9c8-b3ca-54e4-8d68-9971f39bb30b', (select id from public.topics where programme = 'IB DP' and code = 'B2.2' limit 1), 'B2.2 Organelles and compartmentalization · Lesson 1: Organelles and the advantages of compartmentalization', 'B2.2 Organelles and compartmentalization · Lesson 1 · B2.2.1–B2.2.3 (SL)', '/b22-lesson1/', 'DP1-B22-L1', 22, 61 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-B22-L1', 'B2.2 Organelles and compartmentalization · Lesson 1: Organelles and the advantages of compartmentalization', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 7, "n": 7, "ans": ["No membrane", "Double membrane", "Single membrane", "Single membrane", "Double membrane", "Single membrane", "Double membrane"], "tip": "Three organelles have two membranes."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["discrete", "separate", "subunit", "unit"], ["network", "whole cell", "throughout", "spread"]], "tips": ["What is an organelle, and what is the cytoskeleton like?"]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 4, "n": 4, "ans": ["specialised conditions", "organised reaction sequence", "separation of harmful reactions", "high concentration of enzymes and substrates"], "tip": "Conditions, organisation, protection, concentration."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["concentrat", "efficien", "faster"], ["separat", "protect", "apart", "harmful", "ph", "condition"]], "tips": ["One about concentration, one about separation or conditions."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q6", "max": 2, "pts": [["modif", "process", "splic", "intron", "edit"], ["before", "ribosome", "translat", "not translated"]], "tips": ["What can happen to mRNA before ribosomes reach it?"]}, {"kind": "choice", "id": "q4_1", "q": "Q7", "max": 1, "n": 1, "ans": ["Prokaryotic cells only"], "tip": "Is there a membrane between the DNA and the ribosomes?"}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 3, "pts": [["engulf", "phagocyt", "vacuole"], ["fuse", "lysosome"], ["enzyme", "hydrolys", "digest"], ["membrane", "cytoplasm", "protect", "safe"]], "tips": ["Engulf, fuse, digest, protect."]}, {"kind": "choice", "id": "q5_1", "q": "Q9", "max": 1, "n": 1, "ans": ["Cell wall"], "tip": "Is it a discrete subunit inside the cell?"}]}, "models": {"1": [["Q1", "To keep incompatible activities apart, give each its own conditions and concentrate the right tools in one place. A cell can keep harmful enzymes in lysosomes and keep enzymes and substrates together in one organelle."]], "2": [["Q2", "No membrane: ribosome. Single: lysosome, Golgi, vacuole (also ER, vesicles). Double: nucleus, mitochondrion, chloroplast."], ["Q3", "An organelle is a discrete subunit of the cell [1]; the cytoskeleton is a network of fibres spread throughout the whole cell, not a discrete unit [1]."]], "3": [["Q4", "pH 5: specialised conditions. Krebs enzymes together: organised sequence. Hydrolases kept in: separation. Concentrated in chloroplasts: high concentration."], ["Q5", "Enzymes and substrates can be concentrated in one compartment, increasing the rate of reactions [1]; harmful or incompatible reactions are separated, and each compartment can have its own conditions such as pH [1]."]], "4": [["Q6", "The mRNA can be modified (post-transcriptional modification, e.g. removing introns) inside the nucleus [1] before it reaches ribosomes, so only processed mRNA is translated [1]."], ["Q7", "In prokaryotes there is no nuclear envelope, so ribosomes can attach to mRNA while it is still being made."]], "5": [["Q8", "The bacterium is engulfed into a phagocytic vacuole [1]; lysosomes fuse with the vacuole and their hydrolytic enzymes digest it [1]; the enzymes stay inside membranes, so the cell''s own cytoplasm is not digested [1]."], ["Q9", "The cell wall is outside the plasma membrane and is not a discrete subunit within the cell."]], "6": [["Exit ticket", "Ribosome; lysosome (or Golgi, ER, vesicle, vacuole); nucleus (or mitochondrion, chloroplast). Enzymes and substrates are concentrated, or harmful reactions are kept apart."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_1": "Q5", "q4_0": "Q6", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '70e42760-8aee-56df-9c80-06a7f6cdfe2e', (select id from public.topics where programme = 'IB DP' and code = 'B2.2' limit 1), 'B2.2 Organelles and compartmentalization · Lesson 2 (HL): Mitochondria, chloroplasts and the nucleus', 'B2.2 Organelles and compartmentalization · Lesson 2 · B2.2.4–B2.2.6 (HL)', '/b22-lesson2/', 'DP1-B22-L2', 23, 62 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-B22-L2', 'B2.2 Organelles and compartmentalization · Lesson 2 (HL): Mitochondria, chloroplasts and the nucleus', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["large area for the electron transport chain and ATP synthase", "enzymes of the Krebs cycle", "small volume for a steep proton gradient", "separates the organelle from the cytoplasm"], "tip": "Area, enzymes, gradient, boundary."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 3, "pts": [["crista", "fold"], ["surface area", "area"], ["atp synthase", "electron transport", "proton"]], "tips": ["Shape, why that shape, what is in it."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 4, "n": 4, "ans": ["Thylakoid membrane", "Stroma", "Thylakoid lumen", "Stroma"], "tip": "Membrane, inside the thylakoid, or the fluid around it?"}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 3, "pts": [["thylakoid", "grana"], ["photosystem", "chlorophyll", "surface area", "light"], ["stroma", "calvin", "enzyme"]], "tips": ["Thylakoids, what is in them, stroma."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q6", "max": 2, "pts": [["mrna", "rna", "out", "leave"], ["protein", "enter", "in", "control", "regulat"]], "tips": ["What goes out, what comes in."]}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 2, "pts": [["spindle", "microtubule", "chromosome"], ["re-form", "reform", "two nuclei", "telophase", "each set", "around"]], "tips": ["What needs to reach the chromosomes?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 4, "pts": [["double membrane", "both"], ["70s", "circular", "dna", "ribosome"], ["crista", "thylakoid"], ["matrix", "stroma", "intermembrane", "lumen"]], "tips": ["Two similarities and two differences."]}, {"kind": "choice", "id": "q5_1", "q": "Q9", "max": 1, "n": 1, "ans": ["Matrix"], "tip": "The fluid inside the inner membrane."}]}, "models": {"1": [["Q1", "Muscles need a lot of ATP for contraction, made by aerobic respiration in mitochondria. Their mitochondria have many tightly packed cristae, giving a large inner membrane area for ATP production."]], "2": [["Q2", "Cristae: large area for oxidative phosphorylation. Matrix: Krebs enzymes. Intermembrane space: proton gradient. Outer membrane: boundary."], ["Q3", "The inner membrane is folded into cristae [1], giving a large surface area [1] for many electron transport chains and ATP synthase molecules, which use the proton gradient to make ATP [1]."]], "3": [["Q4", "Photosystems: thylakoid membrane. Calvin cycle and starch: stroma. Protons: thylakoid lumen."], ["Q5", "Many thylakoid membranes, stacked in grana [1], give a large area for photosystems with chlorophyll to absorb light for the light-dependent reactions [1]; the stroma contains the enzymes of the Calvin cycle [1]."]], "4": [["Q6", "Nuclear pores let mRNA (and ribosome subunits) leave the nucleus [1] and proteins such as enzymes and histones enter, controlling exchange between nucleus and cytoplasm [1]."], ["Q7", "The envelope breaks down so spindle microtubules can attach to and separate the chromosomes [1]; it re-forms around each set of chromosomes at telophase, giving two nuclei [1]."]], "5": [["Q8", "Both have a double membrane [1]; both contain 70S ribosomes and circular DNA [1]; mitochondria have an inner membrane folded into cristae, chloroplasts have thylakoids in grana [1]; mitochondria have a matrix (protons in the intermembrane space), chloroplasts a stroma (protons in the thylakoid lumen) [1]."], ["Q9", "Link reaction and Krebs cycle enzymes are in the mitochondrial matrix."]], "6": [["Exit ticket", "Cristae: large area for ATP synthase and the electron transport chain. Thylakoids: large area for photosystems to absorb light."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_1": "Q5", "q4_0": "Q6", "q4_1": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '18c66216-b041-5046-b7c6-5d8228c8e5a0', (select id from public.topics where programme = 'IB DP' and code = 'B2.2' limit 1), 'B2.2 Organelles and compartmentalization · Lesson 3 (HL): Ribosomes, rough ER, Golgi apparatus and vesicles', 'B2.2 Organelles and compartmentalization · Lesson 3 · B2.2.7–B2.2.9 (HL)', '/b22-lesson3/', 'DP1-B22-L3', 24, 63 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-B22-L3', 'B2.2 Organelles and compartmentalization · Lesson 3 (HL): Ribosomes, rough ER, Golgi apparatus and vesicles', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["Bound ribosome", "Free ribosome", "Bound ribosome", "Bound ribosome", "Free ribosome"], "tip": "Does the protein go through the endomembrane system?"}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["free", "cytosol", "cytoplasm", "within the cell"], ["bound", "secret", "membrane", "lysosome", "export"]], "tips": ["Where does each protein end up?"]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 1, "n": 1, "ans": ["Cis face"], "tip": "Cis = this side, nearest the ER."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 3, "pts": [["receiv", "cis", "from the er"], ["modif", "glycosyl", "carbohydrate", "sugar"], ["packag", "sort", "vesicle", "trans"]], "tips": ["Receive, modify, package."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 6, "n": 6, "ans": ["1st", "2nd", "3rd", "4th", "5th", "6th"], "tip": "Start with the gene."}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 2, "pts": [["coat", "cage", "lattice"], ["bud", "curv", "pinch", "pull", "pit"]], "tips": ["What it forms and what that does to the membrane."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 5, "pts": [["ribosome", "translat", "signal"], ["lumen", "fold", "rough er"], ["vesicle", "transport"], ["golgi", "modif", "package"], ["fuse", "exocytosis", "plasma membrane"]], "tips": ["Five stages, one mark each."]}]}, "models": {"1": [["Q1", "On ribosomes. Proteins for use inside the cell are made on free ribosomes; proteins for secretion, membranes or lysosomes are made on the rough ER and sent through the Golgi in vesicles."]], "2": [["Q2", "Bound: secreted, membrane and lysosome proteins. Free: proteins used in the cytosol or imported into the nucleus."], ["Q3", "Free ribosomes make proteins used inside the cell, in the cytosol (or imported into organelles such as the nucleus) [1]; ribosomes bound to the ER make proteins for secretion, for membranes or for lysosomes [1]."]], "3": [["Q4", "Vesicles from the ER fuse with the cis face; modified proteins leave from the trans face."], ["Q5", "It receives proteins from the rough ER in vesicles at the cis face [1]; modifies them, for example by adding carbohydrate [1]; sorts and packages them into vesicles that leave from the trans face [1]."]], "4": [["Q6", "Nucleus → rough ER → transport vesicle → Golgi → secretory vesicle → exocytosis."], ["Q7", "Clathrin proteins assemble into a cage-like coat on the membrane [1], which bends the membrane into a pit that buds off as a vesicle [1]."]], "5": [["Q8", "Translated by ribosomes bound to the rough ER (signal sequence) [1]; enters the ER lumen and folds [1]; carried in a transport vesicle to the Golgi [1]; modified, sorted and packaged in the Golgi [1]; a secretory vesicle fuses with the plasma membrane and releases it by exocytosis [1]."]], "6": [["Revision plan", "Your own plan, for example: redraw a mitochondrion and chloroplast from memory; rewrite the secretion pathway without notes; make flashcards of organelles by membrane type."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_1": "Q5", "q4_1": "Q7", "q5_0": "Q8", "q6_0": "Revision plan", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '700b70a7-b1a6-5c6a-a464-f380e32bd9bf', (select id from public.topics where programme = 'IB DP' and code = 'B2.1' limit 1), 'B2.1 Membranes and membrane transport · Lesson 1: Lipid bilayers, membrane proteins and how substances cross membranes', 'IB DP Biology · B2.1 Membranes and membrane transport', '/b21-lesson1/', 'DP1-B21-L1', 32, 101 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-B21-L1', 'B2.1 Membranes and membrane transport · Lesson 1: Lipid bilayers, membrane proteins and how substances cross membranes', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["Hydrophilic", "Hydrophobic", "Hydrophobic", "Hydrophilic"], "tip": "Heads face water; tails hide from it."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 3, "pts": [["amphipathic", "hydrophilic+hydrophobic"], ["head+water", "heads face", "heads towards", "heads outward", "heads on the outside"], ["tail+away", "tails inward", "tails face each other", "tails point in", "tails in the middle", "tails inside", "inward", "core", "middle"]], "tips": ["Name the property, then say where the heads go and where the tails go."]}, {"kind": "choice", "id": "q2_2", "q": "Q4", "max": 4, "n": 4, "ans": ["Yes", "Yes", "No", "No"], "tip": "Only small, non-polar particles slip between the lipid tails."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q5", "max": 4, "n": 4, "ans": ["Integral", "Peripheral", "Integral", "Integral"], "tip": "Is it embedded in the hydrophobic core or only on the surface?"}, {"kind": "text", "id": "q3_1", "q": "Q6", "max": 3, "pts": [["water+into", "water moves in", "water enters", "gains water", "water flows in", "into the cell", "move into", "moves into", "enter"], ["higher solute+inside", "more solute inside", "higher concentration inside", "lower solute+outside", "lower water potential inside", "concentrated inside", "higher inside", "concentration+higher+inside", "concentration inside"], ["burst", "lysis", "lyse", "swell"]], "tips": ["Where is solute concentration higher? Which way does water move overall? What happens to the cell?"]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q7", "max": 5, "n": 5, "ans": ["Simple diffusion", "Facilitated diffusion", "Active transport", "Active transport", "Facilitated diffusion"], "tip": "Is there a protein? Is ATP used? Up or down the gradient?"}, {"kind": "text", "id": "q4_1", "q": "Q8", "max": 3, "pts": [["down+gradient", "high to low", "higher to lower"], ["against", "up the gradient", "low to high", "lower to higher"], ["atp", "energy"]], "tips": ["Direction relative to the gradient, and whether ATP is used. Both use specific proteins."]}, {"kind": "text", "id": "q4_2", "q": "Q9", "max": 2, "pts": [["outside", "outer", "extracellular", "exterior"], ["recognition", "adhesion", "receptor", "antigen", "blood group"]], "tips": ["Which side do the carbohydrate chains face?"]}], "5": [{"kind": "text", "id": "q5_1", "q": "Q11", "max": 4, "pts": [["hydrophobic", "non-polar core", "lipid core"], ["ions", "polar", "large molecules", "charged"], ["channel", "pump", "transport protein", "carrier"], ["specific", "particular", "only certain"]], "tips": ["Two parts: what the lipid core keeps out, and how proteins let specific particles through."]}]}, "models": {"1": [["Q1", "Small, non-polar molecules such as O₂ and CO₂ can pass between the lipid tails. Ions and large or polar molecules (glucose, Na⁺, proteins) cannot, because the core of the membrane is hydrophobic."]], "2": [["Q2", "Heads and the two surfaces: hydrophilic. Tails and the core: hydrophobic."], ["Q3", "Phospholipids are amphipathic: a hydrophilic head and hydrophobic tails [1]; the heads are attracted to water so face the water on both sides [1]; the tails are repelled by water so point inwards towards each other, forming the core [1]."], ["Q4", "O₂ and CO₂: yes (small, non-polar). Na⁺ (charged) and glucose (large, polar): no."]], "3": [["Q5", "Spans the bilayer: integral. Surface only: peripheral. Hydrophobic region in the core: integral. Aquaporin (a channel): integral."], ["Q6", "Solute concentration is higher inside the cell than in distilled water, and the membrane is impermeable to the solutes [1]; water molecules move randomly both ways but more move into the cell, a net movement by osmosis (through aquaporins) [1]; the cell swells and bursts (lysis) because it has no cell wall [1]."]], "4": [["Q7", "O₂: simple diffusion. K⁺ through a channel: facilitated diffusion. Na⁺ with ATP: active transport. Ions from dilute soil: active transport (against the gradient). Glucose down its gradient via a protein: facilitated diffusion."], ["Q8", "Facilitated diffusion moves particles down the concentration gradient (high to low) [1]; active transport moves them against the gradient (low to high) [1]; active transport uses energy from ATP, facilitated diffusion does not [1]. (Both use specific membrane proteins: channels or pumps.)"], ["Q9", "On the outer (extracellular) surface, with the carbohydrate facing out [1]; cell recognition (e.g. self markers, blood groups) and cell adhesion [1]."]], "5": [["Q10", "Labels: phospholipid bilayer (hydrophilic heads on both surfaces, hydrophobic tails in the core), integral protein spanning the bilayer, peripheral protein on one surface, glycoprotein with carbohydrate chain on the outer surface, glycolipid, cholesterol between the fatty acid tails, channel protein."], ["Q11", "The bilayer has a hydrophobic core [1] that ions, polar and large molecules cannot easily cross, while small non-polar molecules diffuse through [1]; channel and pump proteins transport particles across [1]; each protein is specific to particular particles, so only selected substances pass [1]."]], "6": [["Exit ticket", "Facilitated diffusion through a channel protein (down the gradient, no ATP) and active transport by a pump protein (against the gradient, uses ATP)."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_1": "Q6", "q4_1": "Q8", "q4_2": "Q9", "q5_0": "Q10", "q5_1": "Q11", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'de0398b6-03a9-5119-9a6a-593bd48d9526', (select id from public.topics where programme = 'IB DP' and code = 'B2.1' limit 1), 'B2.1 Membranes and membrane transport · Lesson 2 (HL): Membrane fluidity, vesicles, gated channels, pumps and cotransporters', 'IB DP Biology · B2.1 Membranes and membrane transport', '/b21-lesson2/', 'DP1-B21-L2', 28, 102 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-B21-L2', 'B2.1 Membranes and membrane transport · Lesson 2 (HL): Membrane fluidity, vesicles, gated channels, pumps and cotransporters', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["More fluid", "Less fluid", "Less fluid", "More fluid"], "tip": "Cholesterol pushes fluidity back towards the middle at both extremes."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 3, "pts": [["kink", "double bond", "bent", "c=c"], ["loose", "cannot pack", "less tightly", "lower melting"], ["fluid", "flexible"]], "tips": ["Structure of the tails → how they pack → melting point → fluidity in the cold."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 4, "n": 4, "ans": ["Endocytosis", "Exocytosis", "Exocytosis", "Endocytosis"], "tip": "Into the cell = endo; out of the cell = exo."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["vesicle+fuse", "fuses", "fusion", "merge"], ["fluid", "phospholipids move", "flexible", "reseal", "join"]], "tips": ["What happens when the vesicle meets the plasma membrane?"]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 5, "n": 5, "ans": ["3", "2", "1", "Out of the cell", "Into the cell"], "tip": "Remember ''3 out, 2 in, 1 ATP''."}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 3, "pts": [["3+2", "three+two", "more positive out", "more na out"], ["atp", "active transport", "against"], ["negative inside", "inside negative", "charge difference", "potential difference", "polarised"]], "tips": ["Count the charges moved in each direction."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 3, "pts": [["sodium+down", "na+ down", "na+into", "sodium into", "sodium gradient"], ["glucose+against", "against its gradient", "up its gradient"], ["sodium-potassium pump", "pump", "atp+indirect", "atp is used by the pump"]], "tips": ["Which particle moves down its gradient, which moves up, and where does the ATP come in?"]}, {"kind": "choice", "id": "q5_1", "q": "Q9", "max": 4, "n": 4, "ans": ["Small intestine", "Nephron", "Synapse", "Between cells in a tissue"], "tip": "Absorption is from food; reabsorption is from filtrate."}]}, "models": {"1": [["Q1", "Too stiff: proteins cannot move, vesicles cannot form or fuse, the membrane may crack. Too fluid: it becomes leaky to ions and may lose its shape and strength."]], "2": [["Q2", "Unsaturated: more fluid. Saturated: less fluid. Cholesterol at high temperature: less fluid (stabilises). Cholesterol at low temperature: more fluid (prevents stiffening)."], ["Q3", "Unsaturated fatty acids have C=C double bonds that kink the tails [1]; so they cannot pack tightly and have a lower melting point [1]; the membrane stays fluid and flexible at low temperature, so proteins and vesicles keep working [1]."]], "3": [["Q4", "Engulfing bacteria and taking in LDL: endocytosis. Secreting amylase and releasing neurotransmitter: exocytosis."], ["Q5", "The vesicle moves to and fuses with the plasma membrane, releasing its contents outside [1]; this is possible because the phospholipids are fluid and can move and rejoin into one continuous membrane [1]."]], "4": [["Q6", "3 Na⁺ out, 2 K⁺ in, 1 ATP per cycle."], ["Q7", "The pump moves 3 Na⁺ out for every 2 K⁺ in [1], using ATP to move both ions against their gradients (active transport) [1]; so more positive charge leaves than enters, making the inside negative relative to the outside: a membrane potential [1]."]], "5": [["Q8", "Na⁺ moves down its concentration gradient into the cell through the cotransporter [1]; glucose is carried with it against its own gradient [1]; ATP is not used by the cotransporter itself but by the sodium–potassium pump that keeps Na⁺ low inside the cell, so ATP is used indirectly [1]."], ["Q9", "Absorption: small intestine. Reabsorption: nephron (proximal convoluted tubule). Acetylcholine receptors: synapse. CAMs: between cells in a tissue."]], "6": [["Exit ticket", "Cholesterol restricts phospholipid movement at high temperature (less fluid, more stable) and stops the tails packing together at low temperature (prevents stiffening)."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_1": "Q5", "q4_1": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'b0a808c9-9c6c-5af7-8384-81be71a007be', (select id from public.topics where programme = 'IB DP' and code = 'B2.3' limit 1), 'B2.3 Cell specialization · Lesson 1: Stem cells, differentiation, cell size and surface area-to-volume ratio', 'IB DP Biology · B2.3 Cell specialization', '/b23-lesson1/', 'DP1-B23-L1', 35, 71 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-B23-L1', 'B2.3 Cell specialization · Lesson 1: Stem cells, differentiation, cell size and surface area-to-volume ratio', '{"marks": {"2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["divide", "self-renew", "self renew", "endless", "unlimited", "mitosis"], ["differentiate", "specialise", "specialize", "different pathways", "different types"]], "tips": ["One is about dividing, one is about becoming different cell types."]}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 3, "pts": [["gradient", "concentration differs", "different concentrations"], ["position", "where", "location"], ["gene expression", "genes switched on", "express different genes", "genes expressed", "switch", "different genes"]], "tips": ["Concentration → position → genes → specialisation."]}, {"kind": "choice", "id": "q2_2", "q": "Q4", "max": 4, "n": 4, "ans": ["Bone marrow", "Hair follicle", "Bone marrow", "Hair follicle"], "tip": "One niche makes blood; the other is in the skin."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q5", "max": 5, "n": 5, "ans": ["Totipotent", "Pluripotent", "Multipotent", "Pluripotent", "Multipotent"], "tip": "Toti = all; pluri = many; multi = a few related."}, {"kind": "text", "id": "q3_1", "q": "Q6", "max": 2, "pts": [["pluripotent+any", "pluripotent+all", "any type of body cell", "all body cell"], ["multipotent+few", "multipotent+limited", "related", "small number", "limited range"]], "tips": ["How many cell types can each become? Where is each found?"]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q7", "max": 4, "n": 4, "ans": ["4", "24", "8", "3"], "tip": "Area of a face = L². Six faces. Volume = L³. SA:V = 6 ÷ L."}, {"kind": "choice", "id": "q4_1", "q": "Q8", "max": 5, "n": 5, "ans": ["Egg cell", "Red blood cell", "Neuron", "Striated muscle fibre", "Sperm cell"], "tip": "Think of what each cell has to do."}, {"kind": "text", "id": "q4_2", "q": "Q9", "max": 3, "pts": [["volume+faster", "volume increases faster", "volume increases more", "sa:v+decrease", "ratio decreases", "ratio falls", "ratio gets smaller"], ["need+volume", "demand+volume", "metabolism+volume", "use depends on volume"], ["surface+exchange", "exchange+surface", "not enough surface", "diffusion too slow", "distance", "too slow"]], "tips": ["Compare how area and volume change, then link each one to exchange."]}], "5": [{"kind": "choice", "id": "q5_0", "q": "Q10", "max": 4, "n": 4, "ans": ["6", "3", "1.5", "0.75"], "tip": "SA:V = 6 ÷ L. Each doubling of L halves the ratio."}, {"kind": "text", "id": "q5_1", "q": "Q11", "max": 3, "pts": [["1 cm", "smaller", "small cube"], ["higher sa:v", "larger sa:v", "bigger ratio", "more surface", "higher ratio", "larger ratio"], ["distance", "shorter", "diffuse", "diffusion"]], "tips": ["Prediction, SA:V, and distance to the centre."]}]}, "models": {"1": [["Q1", "Different genes are switched on (expressed) in each cell type, so they make different proteins, which give them different structures and functions."]], "2": [["Q2", "They can divide endlessly (self-renewal) [1]; they can differentiate along different pathways into specialised cell types [1]."], ["Q3", "Signalling chemicals (morphogens) form concentration gradients across the embryo [1]; each cell receives a different concentration depending on its position [1]; this switches on different genes, so cells differentiate along different pathways [1]."], ["Q4", "Blood cells and platelets: bone marrow. Hair regrowth and skin repair: hair follicle."]], "3": [["Q5", "Zygote: totipotent. Inner cell mass: pluripotent. Bone marrow: multipotent. Any body cell but not placenta: pluripotent. Only a few related types: multipotent."], ["Q6", "Pluripotent stem cells can differentiate into any type of body cell (e.g. early embryo cells) [1]; multipotent stem cells can differentiate into only a few related types (e.g. bone marrow cells make blood cells) [1]."]], "4": [["Q7", "One face 2×2 = 4 µm²; total 6×4 = 24 µm²; volume 2³ = 8 µm³; SA:V = 24 ÷ 8 = 3 : 1."], ["Q8", "120 µm: egg. 8 µm in capillaries: red blood cell. Over 1 m: neuron. Long, many nuclei: striated muscle fibre. Small and mobile: sperm."], ["Q9", "As a cell grows, its volume increases faster than its surface area, so the SA:V ratio falls [1]; the need for exchange (O₂, nutrients, waste) depends on volume [1]; but the rate of exchange depends on surface area, and diffusion distances to the centre increase, so exchange becomes too slow for the cell''s needs [1]."]], "5": [["Q10", "6, 3, 1.5 and 0.75 : 1. Each time the side doubles, SA:V halves."], ["Q11", "The 1 cm cube changes colour all the way through first [1]; it has a higher SA:V ratio (6:1 compared with 2:1), so relatively more surface for acid to enter [1]; and the distance from the surface to the centre is shorter, so diffusion reaches the centre sooner [1]."]], "6": [["Exit ticket", "Differentiation is cells becoming specialised by expressing different genes. A low SA:V means the surface cannot exchange materials fast enough for the cell''s volume."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q2", "q2_1": "Q3", "q3_1": "Q6", "q4_2": "Q9", "q5_1": "Q11", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'e5ab4f68-26a6-5fde-8b97-401196d0e117', (select id from public.topics where programme = 'IB DP' and code = 'B2.3' limit 1), 'B2.3 Cell specialization · Lesson 2 (HL): Adaptations of pneumocytes, muscle cells and gametes', 'IB DP Biology · B2.3 Cell specialization', '/b23-lesson2/', 'DP1-B23-L2', 25, 72 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-B23-L2', 'B2.3 Cell specialization · Lesson 2 (HL): Adaptations of pneumocytes, muscle cells and gametes', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 3, "n": 3, "ans": ["Flattening", "Microvilli", "Invagination"], "tip": "Out-folds are microvilli; in-folds are invaginations."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Type I", "Type II", "Type II", "Type I"], "tip": "Type I: diffusion. Type II: secretion."}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 2, "pts": [["lamellar", "vesicles", "secretory"], ["surfactant+tension", "surface tension", "stops collapse", "prevent collapse", "not collapse", "stick together"]], "tips": ["What do they contain, and what does their secretion do?"]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q5", "max": 5, "n": 5, "ans": ["Cardiac muscle cell", "Striated muscle fibre", "Both", "Cardiac muscle cell", "Striated muscle fibre"], "tip": "Only one feature is shared."}, {"kind": "text", "id": "q4_1", "q": "Q6", "max": 3, "pts": [["one membrane", "single membrane", "surrounded by a membrane", "continuous membrane", "one unit"], ["many nuclei", "multinucleate", "more than one nucleus"], ["fused", "fusion", "several cells", "many cells"]], "tips": ["Give an argument for, an argument against, and how it forms."]}], "5": [{"kind": "choice", "id": "q5_0", "q": "Q7", "max": 5, "n": 5, "ans": ["Acrosome (sperm)", "Midpiece mitochondria (sperm)", "Cortical granules (egg)", "Cytoplasm (egg)", "Zona pellucida (egg)"], "tip": "Match each function to the part."}, {"kind": "text", "id": "q5_1", "q": "Q8", "max": 3, "pts": [["both haploid", "both+haploid", "haploid"], ["sperm+small", "sperm is small", "egg+large", "egg is large", "larger"], ["flagellum+cortical", "flagellum", "acrosome", "cortical granules", "zona"]], "tips": ["One similarity and at least two differences."]}]}, "models": {"1": [["Q1", "Flatten its shape (e.g. biconcave disc), fold its membrane outward into microvilli or inward (invaginations)."]], "2": [["Q2", "Biconcave disc: flattening. Brush border: microvilli. Basal infoldings: invagination."]], "3": [["Q3", "Thin and most of the surface: type I. Lamellar bodies and surfactant: type II."], ["Q4", "Their cytoplasm contains many secretory vesicles (lamellar bodies) [1] that release surfactant, which reduces surface tension so alveoli do not collapse or stick together during exhalation [1]."]], "4": [["Q5", "Branched and intercalated discs: cardiac. Many nuclei and very long: striated fibre. Myofibrils: both."], ["Q6", "For: it is surrounded by a single continuous plasma membrane and functions as one unit [1]. Against: it has many nuclei, whereas a typical cell has one [1]; it forms by the fusion of many embryonic cells, so it is better seen as an exception to cell theory [1]."]], "5": [["Q7", "Digest a way in: acrosome. ATP: midpiece mitochondria. Block other sperm: cortical granules. Nutrients: cytoplasm. Sperm binding: zona pellucida."], ["Q8", "Both are haploid, carrying one set of chromosomes [1]; the sperm is small and streamlined with a flagellum and many mitochondria to swim, whereas the egg is large with cytoplasm and nutrients for the embryo [1]; the sperm has an acrosome with enzymes, while the egg has a zona pellucida and cortical granules to prevent polyspermy [1]."]], "6": [["Exit ticket", "Example: type I pneumocyte: extremely thin to shorten the diffusion distance; large flat surface to give a big area for gas exchange."]]}, "labels": {"q1_0": "Q1", "q3_1": "Q4", "q4_1": "Q6", "q5_1": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '89ee2691-3ee1-5fd1-a9bf-fffa2d1ef2bb', (select id from public.topics where programme = 'IB DP' and code = 'C1.2' limit 1), 'C1.2 Cell respiration · Lesson 1: ATP, aerobic and anaerobic respiration, and measuring respiration rate', 'IB DP Biology · C1.2 Cell respiration', '/c12-lesson1/', 'DP1-C12-L1', 37, 181 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-C12-L1', 'C1.2 Cell respiration · Lesson 1: ATP, aerobic and anaerobic respiration, and measuring respiration rate', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 6, "n": 6, "ans": ["Adenosine triphosphate", "Nucleotide", "Ribose", "Adenine", "Releases energy", "Requires energy"], "tip": "Hydrolysis of ATP releases energy; making ATP needs energy."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 3, "pts": [["soluble", "dissolves", "moves easily", "diffuses"], ["stable", "does not break down"], ["small amount", "right amount", "suitable amount", "convenient amount", "manageable"], ["regenerated", "remade", "recycled", "easily made"]], "tips": ["Think: moving around, not breaking down on its own, how much energy, reuse."]}, {"kind": "choice", "id": "q2_2", "q": "Q4", "max": 5, "n": 5, "ans": ["Active transport", "Anabolism", "Movement", "Movement", "Anabolism"], "tip": "Moving particles across membranes, building molecules, or moving things."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q5", "max": 6, "n": 6, "ans": ["Aerobic", "Anaerobic", "Aerobic", "Both", "Aerobic", "Anaerobic"], "tip": "Only one of these is shared."}, {"kind": "text", "id": "q3_1", "q": "Q6", "max": 2, "pts": [["glucose+oxygen+carbon dioxide+water"], ["glucose+lactate", "lactic acid"]], "tips": ["Use glucose as the substrate both times."]}, {"kind": "text", "id": "q3_2", "q": "Q7", "max": 2, "pts": [["respiration+reaction", "chemical", "inside cells", "atp", "release energy"], ["gas exchange+diffusion", "diffusion", "surface", "across"]], "tips": ["One is chemistry inside cells; the other is movement of gases."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q8", "max": 3, "n": 3, "ans": ["3 mm min⁻¹", "Absorbs CO₂", "Towards the peas"], "tip": "Rate = distance ÷ time. O₂ is used; CO₂ is absorbed, so pressure falls."}, {"kind": "text", "id": "q4_1", "q": "Q9", "max": 3, "pts": [["oxygen+used", "o2 used", "take in oxygen", "uptake", "consume oxygen", "use o2", "uses o2", "use oxygen", "uses oxygen", "oxygen is used"], ["co2+absorbed", "soda lime", "koh", "carbon dioxide+absorbed"], ["pressure", "volume decreases", "less gas", "volume falls"]], "tips": ["What happens to O₂, what happens to CO₂, and so what happens to the gas volume?"]}], "5": [{"kind": "choice", "id": "q5_0", "q": "Q10", "max": 4, "n": 4, "ans": ["Increases", "About doubles", "Temperature", "Oxygen uptake"], "tip": "Compare each value with the one before."}, {"kind": "text", "id": "q5_1", "q": "Q11", "max": 3, "pts": [["oxygen+not enough", "insufficient oxygen", "not enough oxygen", "oxygen cannot", "lack of oxygen", "oxygen supply"], ["anaerobic"], ["atp+quickly", "fast", "quickly", "rapid", "extra atp", "more atp"]], "tips": ["Compare oxygen supply with demand, and say why anaerobic respiration helps."]}]}, "models": {"1": [["Q1", "Burning releases energy all at once as heat, which would damage the cell and be wasted. Small steps release energy in usable amounts that can be captured in ATP."]], "2": [["Q2", "Adenosine triphosphate; a nucleotide; ribose; adenine; hydrolysis releases energy; synthesis requires energy."], ["Q3", "Soluble, so it moves easily to where energy is needed [1]; stable at cell pH, so it does not break down without an enzyme [1]; hydrolysis releases a suitable amount of energy for many cell tasks [1]; it is easily regenerated from ADP and phosphate [1]. (Any three.)"], ["Q4", "Pump: active transport. Polypeptide and DNA synthesis: anabolism. Chromosomes and muscle: movement."]], "3": [["Q5", "O₂, CO₂ and mitochondria: aerobic. Lactate and 2 ATP: anaerobic. Glucose: both."], ["Q6", "Aerobic: glucose + oxygen → carbon dioxide + water [1]. Anaerobic: glucose → lactate [1]."], ["Q7", "Cell respiration is a set of chemical reactions inside cells that release energy and make ATP [1]; gas exchange is the diffusion of O₂ and CO₂ across an exchange surface such as the alveoli [1]."]], "4": [["Q8", "36 ÷ 12 = 3 mm min⁻¹. Soda lime absorbs CO₂, so the change shows O₂ uptake. The liquid moves towards the peas as gas volume falls."], ["Q9", "The organisms use O₂ in aerobic respiration [1]; the CO₂ they release is absorbed by soda lime/KOH [1]; so the volume of gas (and pressure) in the tube falls, drawing the liquid towards the organisms [1]."]], "5": [["Q10", "Rate increases with temperature, roughly doubling each 10 °C (2.0 → 4.1 → 7.9). Independent variable: temperature. Dependent variable: oxygen uptake."], ["Q11", "During sprinting, oxygen cannot be supplied to the muscles fast enough for aerobic respiration alone [1]; so muscles also respire anaerobically, producing lactate [1]; this releases ATP quickly without oxygen, although the yield per glucose is low [1]. During walking, oxygen supply meets demand, so respiration is aerobic."]], "6": [["Exit ticket", "Adenosine triphosphate. Any two: active transport, synthesis of macromolecules (anabolism), movement of cells or chromosomes."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_1": "Q6", "q3_2": "Q7", "q4_1": "Q9", "q5_1": "Q11", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'de8fd788-bd06-504c-9a29-ed8db308912a', (select id from public.topics where programme = 'IB DP' and code = 'C1.2' limit 1), 'C1.2 Cell respiration · Lesson 2 (HL): NAD, glycolysis and anaerobic respiration in humans and yeast', 'IB DP Biology · C1.2 Cell respiration', '/c12-lesson2/', 'DP1-C12-L2', 28, 182 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-C12-L2', 'C1.2 Cell respiration · Lesson 2 (HL): NAD, glycolysis and anaerobic respiration in humans and yeast', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["Oxidised", "Reduced", "Reduced", "Oxidised"], "tip": "OIL RIG: Oxidation Is Loss, Reduction Is Gain (of electrons)."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["electron"], ["loss", "lose", "removed", "removal"]], "tips": ["What does each hydrogen atom bring with it?"]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 4, "n": 4, "ans": ["Phosphorylation", "Lysis", "Oxidation", "ATP formation"], "tip": "The order is in the notes: P, L, O, A."}, {"kind": "choice", "id": "q3_1", "q": "Q5", "max": 5, "n": 5, "ans": ["2", "4", "2", "2", "2"], "tip": "Net = made − used."}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 5, "n": 5, "ans": ["Both", "Humans", "Yeast", "Both", "Yeast"], "tip": "Only the step after pyruvate differs."}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 3, "pts": [["reduced nad+oxidised", "nad+regenerated", "regenerate", "nad is regenerated", "nad is reformed"], ["pyruvate+accept", "accepts hydrogen", "hydrogen to pyruvate"], ["nad+needed", "glycolysis needs nad", "oxidation step", "nad is required"]], "tips": ["What does glycolysis use up, and how is it replaced?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 3, "pts": [["both+glycolysis", "glycolysis", "same pathway"], ["lactate+ethanol", "ethanol"], ["carbon dioxide+yeast", "co2", "yeast+carbon dioxide"]], "tips": ["One similarity, then the different end products."]}, {"kind": "text", "id": "q5_1", "q": "Q9", "max": 2, "pts": [["enzyme", "faster respiration", "rate of respiration", "respire faster"], ["carbon dioxide", "co2", "gas"]], "tips": ["Enzymes and the gas that makes dough rise."]}]}, "models": {"1": [["Q1", "Most ATP comes from later stages in the mitochondrion that need oxygen as the final electron acceptor; without oxygen only glycolysis runs, giving little ATP."]], "2": [["Q2", "Loses H: oxidised. NAD accepting H: reduced. Gains electrons: reduced. Reduced NAD giving away H: oxidised."], ["Q3", "Each hydrogen atom removed takes an electron with it [1]; oxidation is the loss of electrons, so dehydrogenation oxidises the substrate [1]."]], "3": [["Q4", "Add phosphates: phosphorylation. Split: lysis. Remove H to NAD: oxidation. Make 4 ATP: ATP formation."], ["Q5", "2 ATP used, 4 made, net 2; 2 reduced NAD; 2 pyruvate."]], "4": [["Q6", "Glycolysis and NAD regeneration: both. Lactate: humans. Ethanol + CO₂ and bread: yeast."], ["Q7", "Glycolysis needs NAD to accept hydrogen in its oxidation step [1]; in anaerobic conditions pyruvate accepts the hydrogen from reduced NAD, forming lactate [1]; this regenerates (oxidises) NAD so glycolysis can continue producing 2 ATP per glucose [1]."]], "5": [["Q8", "Both use glycolysis to produce pyruvate and a net 2 ATP, regenerating NAD [1]; humans convert pyruvate to lactate, while yeast converts it to ethanol [1]; yeast also releases CO₂, humans do not [1]."], ["Q9", "Higher temperature increases enzyme activity, so yeast respires faster [1]; more CO₂ is produced per minute, so the dough rises faster [1]."]], "6": [["Exit ticket", "2 ATP, 2 reduced NAD, 2 pyruvate. NAD must be regenerated from reduced NAD (by making lactate or ethanol) so glycolysis can keep running."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q4_1": "Q7", "q5_0": "Q8", "q5_1": "Q9", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '11dd6e19-b240-5de0-8c99-57514c54502d', (select id from public.topics where programme = 'IB DP' and code = 'C1.2' limit 1), 'C1.2 Cell respiration · Lesson 3 (HL): Link reaction, Krebs cycle, electron transport chain and chemiosmosis', 'IB DP Biology · C1.2 Cell respiration', '/c12-lesson3/', 'DP1-C12-L3', 30, 183 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-C12-L3', 'C1.2 Cell respiration · Lesson 3 (HL): Link reaction, Krebs cycle, electron transport chain and chemiosmosis', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["3", "2", "4", "6"], "tip": "Acetyl + oxaloacetate = citrate."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 3, "pts": [["decarboxyl", "carbon dioxide", "co2"], ["oxidised", "oxidation", "reduced nad", "nad", "hydrogen removed"], ["acetyl", "coenzyme a", "coa"]], "tips": ["Three things happen to pyruvate: something is removed twice and something is added."]}, {"kind": "choice", "id": "q2_2", "q": "Q4", "max": 3, "n": 3, "ans": ["2", "4", "1"], "tip": "Two carbons enter as acetyl; the same number leave as CO₂."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q5", "max": 5, "n": 5, "ans": ["Matrix", "Inner membrane", "Inner membrane", "Intermembrane space", "Matrix"], "tip": "Cycle and link: inside. Chain and synthase: in the folded membrane."}, {"kind": "text", "id": "q3_1", "q": "Q6", "max": 4, "pts": [["electron", "electrons"], ["pump+proton", "protons pumped", "h+ pumped", "pumped into the intermembrane"], ["gradient", "concentration of protons", "high concentration"], ["atp synthase+diffuse", "atp synthase", "flow back", "back into the matrix"]], "tips": ["Electrons → energy → protons pumped → gradient → flow through ATP synthase."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q7", "max": 3, "pts": [["terminal", "final", "last"], ["electron"], ["water", "protons", "h+", "keeps", "continue", "flow"]], "tips": ["Where is it used, what does it accept, and why does it matter?"]}, {"kind": "choice", "id": "q4_1", "q": "Q8", "max": 5, "n": 5, "ans": ["Lipid", "Carbohydrate", "Carbohydrate", "Both", "Carbohydrate"], "tip": "Lipids skip glycolysis."}], "5": [{"kind": "text", "id": "q5_0", "q": "Q9", "max": 3, "pts": [["electrons+not", "electrons cannot", "chain stops", "flow stops", "no electron flow"], ["proton", "gradient"], ["nad+not regenerated", "reduced nad", "krebs+stop", "krebs cycle stops", "nad"]], "tips": ["Follow the effect backwards along the pathway."]}]}, "models": {"1": [["Q1", "Reduced NAD builds up because it cannot pass its electrons on; NAD runs out, so the Krebs cycle and link reaction stop; ATP production falls to only the small amount from glycolysis."]], "2": [["Q2", "Pyruvate 3C; acetyl 2C; oxaloacetate 4C; citrate 6C (2 + 4 = 6)."], ["Q3", "Pyruvate is decarboxylated, releasing CO₂ [1]; it is oxidised, with hydrogen accepted by NAD to form reduced NAD [1]; the remaining acetyl group is attached to coenzyme A (acetyl-CoA), which carries it into the Krebs cycle [1]."], ["Q4", "2 decarboxylations, 4 oxidations, 1 ATP per turn."]], "3": [["Q5", "Krebs and link: matrix. ETC and ATP synthase: inner membrane (cristae). High H⁺: intermembrane space."], ["Q6", "Electrons from reduced NAD pass along carriers in the inner membrane, releasing energy [1]; the energy is used to pump protons into the intermembrane space [1]; forming a proton concentration gradient [1]; protons diffuse back into the matrix through ATP synthase, which uses the energy to phosphorylate ADP to ATP [1]."]], "4": [["Q7", "Oxygen is the terminal (final) electron acceptor at the end of the electron transport chain [1]; it accepts electrons [1] and protons to form water, which keeps electrons flowing along the chain so ATP production continues [1]."], ["Q8", "Lipid: more energy per gram. Carbohydrate: anaerobic, glycolysis, more oxygen. Both form acetyl-CoA."]], "5": [["Q9", "Electrons cannot pass to oxygen, so electron flow along the chain stops [1]; protons are no longer pumped, so there is no proton gradient for ATP synthase [1]; reduced NAD cannot be oxidised, so NAD is not regenerated and the link reaction and Krebs cycle stop; only glycolysis ATP remains [1]."], ["Q10", "Glycolysis (cytoplasm) → link reaction (matrix) → Krebs cycle (matrix) → electron transport chain and chemiosmosis (inner membrane) → oxygen accepts electrons and protons to form water."]], "6": [["Exit ticket", "Citrate (6C) and oxaloacetate (4C). Oxygen is the terminal electron acceptor."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_1": "Q6", "q4_0": "Q7", "q5_0": "Q9", "q5_1": "Q10", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'a53513bb-9960-566a-8aab-dcda0dd49974', (select id from public.topics where programme = 'IB DP' and code = 'C1.3' limit 1), 'C1.3 Photosynthesis · Lesson 1: Energy from light, the word equation, pigments and spectra', 'IB DP Biology · C1.3 Photosynthesis', '/c13-lesson1/', 'DP1-C13-L1', 26, 171 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-C13-L1', 'C1.3 Photosynthesis · Lesson 1: Energy from light, the word equation, pigments and spectra', '{"marks": {"2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 1, "pts": [["carbon dioxide+water+glucose+oxygen"]], "tips": ["Two reactants, two products."]}, {"kind": "choice", "id": "q2_1", "q": "Q3", "max": 3, "n": 3, "ans": ["Carbon dioxide", "Water", "Water"], "tip": "Oxygen gas comes from splitting water."}, {"kind": "text", "id": "q2_2", "q": "Q4", "max": 2, "pts": [["water+split", "splitting of water", "photolysis", "water is split"], ["not needed", "not used", "waste", "released", "hydrogen is needed", "only hydrogen"]], "tips": ["Why is water split, and what happens to the oxygen?"]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q5", "max": 6, "n": 6, "ans": ["0.95", "0.50", "0.25", "Carotene", "Chlorophyll a", "Chlorophyll b"], "tip": "Rf = pigment distance ÷ solvent distance."}, {"kind": "text", "id": "q3_1", "q": "Q6", "max": 2, "pts": [["pencil+not dissolve", "ink would", "ink dissolves", "ink would run", "pencil does not"], ["above+dissolve", "pigment would dissolve", "wash off", "into the solvent", "not dissolve in the solvent"]], "tips": ["What would ink do? What would happen to the spot if it were under the solvent?"]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q7", "max": 5, "n": 5, "ans": ["Blue", "Green", "Red", "Action spectrum", "Absorption spectrum"], "tip": "Absorption = pigment; action = photosynthesis rate."}, {"kind": "text", "id": "q4_1", "q": "Q8", "max": 3, "pts": [["similar", "same shape", "both peak", "both+peak", "match"], ["blue+red", "red+blue"], ["green+higher", "action+green", "carotenoid", "accessory", "green+more"]], "tips": ["One similarity with colours, one difference and why."]}], "5": [{"kind": "choice", "id": "q5_0", "q": "Q9", "max": 4, "n": 4, "ans": ["450 nm", "Blue", "550 nm", "Red"], "tip": "Find the biggest and smallest numbers."}]}, "models": {"1": [["Q1", "Light energy from the Sun → chemical energy in glucose made by photosynthesis in wheat leaves → stored as starch in the grain → flour → bread → my cells (via respiration to ATP)."]], "2": [["Q2", "carbon dioxide + water → glucose + oxygen (light, chlorophyll)."], ["Q3", "Carbon: CO₂. Hydrogen: water. O₂ gas: water."], ["Q4", "Water is split to supply the hydrogen (and electrons) needed to reduce CO₂ [1]; the oxygen left over is not needed and is released as a by-product (waste) [1]."]], "3": [["Q5", "76/80 = 0.95; 40/80 = 0.50; 20/80 = 0.25. Orange near front: carotene. Blue-green: chlorophyll a. Yellow-green, lowest: chlorophyll b."], ["Q6", "Pencil (graphite) does not dissolve in the solvent, whereas ink would separate and confuse the results [1]; if the spot were below the solvent, the pigments would dissolve into the solvent instead of moving up the paper [1]."]], "4": [["Q7", "Peaks in blue and red; green reflected. Rate vs wavelength: action spectrum. Light absorbed vs wavelength: absorption spectrum."], ["Q8", "Both have a similar shape [1], with peaks in the blue-violet and red parts of the spectrum and a low point in green [1]; the action spectrum is higher in the green-yellow region because accessory pigments such as carotenoids absorb some light there and pass the energy on [1]."]], "5": [["Q9", "Highest at 450 nm (blue); second peak 650 nm (red); lowest in the middle at 550 nm (green)."], ["Q10", "Two peaks, in blue (450 nm) and red (650 nm), with a trough in green (550 nm) and a steep fall beyond 680 nm."]], "6": [["Exit ticket", "From the splitting (photolysis) of water. Blue-violet and red."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q2", "q2_2": "Q4", "q3_1": "Q6", "q4_1": "Q8", "q5_1": "Q10", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '5000621d-8d1e-58d5-a2f7-dbb907775190', (select id from public.topics where programme = 'IB DP' and code = 'C1.3' limit 1), 'C1.3 Photosynthesis · Lesson 2: Limiting factors and carbon dioxide enrichment experiments', 'IB DP Biology · C1.3 Photosynthesis', '/c13-lesson2/', 'DP1-C13-L2', 22, 172 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-C13-L2', 'C1.3 Photosynthesis · Lesson 2: Limiting factors and carbon dioxide enrichment experiments', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["Light intensity", "Carbon dioxide", "Carbon dioxide", "Temperature"], "tip": "Rising line: the x-axis factor limits. Plateau: something else does."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["another factor", "other factor", "carbon dioxide", "co2", "temperature"], ["limiting", "limit"]], "tips": ["Name what is now in short supply."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 5, "n": 5, "ans": ["Independent", "Dependent", "Controlled", "Controlled", "Controlled"], "tip": "Change one, measure one, keep the rest the same."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["increase+rate", "rate will increase", "higher rate", "faster", "rate increases"], ["substrate", "rubisco", "fixed", "calvin", "raw material", "reactant", "needed to make"]], "tips": ["Prediction + biological reason."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 4, "n": 4, "ans": ["FACE", "Greenhouse", "FACE", "Both"], "tip": "Control versus realism."}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 2, "pts": [["species", "same plants", "plot size", "same type", "area", "soil"], ["wind", "difficult to control", "expensive", "cost", "weather", "uncontrolled"]], "tips": ["What can scientists keep the same between plots? What can they not control?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 3, "pts": [["co2+limiting", "carbon dioxide was limiting", "limiting in winter"], ["summer+temperature", "too hot", "high temperature", "temperature+limiting", "denature"], ["water", "stomata", "light", "other factor"]], "tips": ["Which factor limits in each season?"]}]}, "models": {"1": [["Q1", "Temperature: light is plentiful, but low temperature slows the enzymes (e.g. Rubisco) of photosynthesis."]], "2": [["Q2", "Rising part: light. Low-CO₂ plateau: CO₂. Higher plateau with more CO₂: CO₂ was limiting before. Above 40 °C: temperature (enzymes denature)."], ["Q3", "At high light intensity, light is no longer in short supply [1]; another factor such as CO₂ concentration or temperature becomes the limiting factor, so the rate levels off [1]."]], "3": [["Q4", "Lamp distance: independent. Bubbles: dependent. Temperature, NaHCO₃, plant length: controlled."], ["Q5", "As CO₂ concentration increases, the rate of photosynthesis increases until another factor becomes limiting [1], because CO₂ is a substrate fixed by Rubisco in the Calvin cycle, so more CO₂ means more is fixed per minute [1]."]], "4": [["Q6", "Natural conditions and wind problems: FACE. Easy control: greenhouse. Predicting future growth: both."], ["Q7", "Controlled variable: e.g. the same species and plot size in enriched and control plots [1]. Limitation: wind and weather change the CO₂ concentration and other variables cannot be controlled; it is also very expensive [1]."]], "5": [["Q8", "In winter, CO₂ was the limiting factor, so adding CO₂ greatly increased photosynthesis and yield [1]; on hot summer days, high temperature limits the rate (enzymes near or above the optimum) [1]; also stomata may close to save water, so extra CO₂ cannot enter / another factor limits [1]."]], "6": [["Exit ticket", "The factor in shortest supply, which controls the rate; light intensity, CO₂ concentration and temperature."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_1": "Q5", "q4_1": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'b6f502aa-4673-51d0-b44a-658776bddae8', (select id from public.topics where programme = 'IB DP' and code = 'C1.3' limit 1), 'C1.3 Photosynthesis · Lesson 3 (HL): Photosystems and the light-dependent reactions in the thylakoid', 'IB DP Biology · C1.3 Photosynthesis', '/c13-lesson3/', 'DP1-C13-L3', 22, 173 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-C13-L3', 'C1.3 Photosynthesis · Lesson 3 (HL): Photosystems and the light-dependent reactions in the thylakoid', '{"marks": {"2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 3, "pts": [["more light", "more wavelengths", "range of wavelengths", "wider range", "absorb more"], ["funnel", "passed to", "transfer+reaction centre", "reaction centre"], ["acceptor", "not lost", "excited electron", "emit"]], "tips": ["Capturing light, moving energy, using the electron."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 5, "n": 5, "ans": ["Water", "Oxygen", "Lumen", "Stroma", "Photosystem II"], "tip": "Protons build up inside the thylakoid."}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 4, "pts": [["excited electron", "electrons", "electron transport chain"], ["pump", "pumped"], ["gradient", "high concentration", "lumen"], ["atp synthase", "chemiosmosis", "flow back"]], "tips": ["Same idea as in the mitochondrion: electrons → pumping → gradient → ATP synthase."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q5", "max": 4, "n": 4, "ans": ["Thylakoid lumen", "Thylakoid membrane", "Stroma", "Stroma"], "tip": "Membrane holds the machinery; lumen stores protons; stroma receives products."}, {"kind": "text", "id": "q4_1", "q": "Q6", "max": 3, "pts": [["both+atp", "both make atp", "atp+both"], ["cyclic+psi", "only photosystem i", "only psi", "cyclic+photosystem i"], ["nadp+non-cyclic", "non-cyclic+nadp", "no nadp", "no oxygen", "oxygen"]], "tips": ["One similarity, two differences (which photosystems, which products)."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 3, "pts": [["atmosphere", "oxygen-rich", "oxygen in the air"], ["ozone", "uv"], ["iron", "rock", "banded", "aerobic", "extinction", "anaerobes"]], "tips": ["Air, the ozone layer, rocks, and which organisms could evolve or died out."]}]}, "models": {"1": [["Q1", "More light is captured over many wavelengths; energy can be funnelled to one place; the excited electron can be passed to a specific acceptor in the membrane instead of being lost."]], "2": [["Q2", "Many different pigments absorb more light over a wider range of wavelengths [1]; absorbed energy is passed from pigment to pigment and funnelled to the special chlorophyll in the reaction centre [1]; the reaction centre emits an excited electron to a specific acceptor, so the energy is used rather than lost as heat or fluorescence [1]."]], "3": [["Q3", "Water; oxygen; pumped into the lumen; flow back into the stroma; photolysis at PSII."], ["Q4", "Excited electrons from the photosystems pass along the electron transport chain [1]; energy released is used to pump protons into the thylakoid lumen [1]; creating a proton gradient (high concentration in the lumen) [1]; protons diffuse back into the stroma through ATP synthase, which makes ATP (chemiosmosis / photophosphorylation) [1]."]], "4": [["Q5", "Protons: lumen. Photosystems and ETC: membrane. Reduced NADP and ATP released: stroma."], ["Q6", "Both produce ATP by chemiosmosis [1]; cyclic uses only PSI, with electrons returning to PSI, while non-cyclic uses PSII and PSI [1]; non-cyclic also reduces NADP and releases oxygen from photolysis; cyclic does neither [1]."]], "5": [["Q7", "Oxygen accumulated in the atmosphere [1]; an ozone layer formed, shielding the surface from UV so life could colonise land [1]; dissolved iron was oxidised and deposited as banded iron rocks; aerobic respiration and larger organisms evolved while many anaerobes died out [1]."]], "6": [["Exit ticket", "ATP and reduced NADP. By-product: oxygen."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q2", "q3_1": "Q4", "q4_1": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '9945cb9c-9da7-5075-8af4-1c87cd8ea16f', (select id from public.topics where programme = 'IB DP' and code = 'C1.3' limit 1), 'C1.3 Photosynthesis · Lesson 4 (HL): The Calvin cycle and how the two stages depend on each other', 'IB DP Biology · C1.3 Photosynthesis', '/c13-lesson4/', 'DP1-C13-L4', 23, 174 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-C13-L4', 'C1.3 Photosynthesis · Lesson 4 (HL): The Calvin cycle and how the two stages depend on each other', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["Rubisco", "RuBP", "Glycerate 3-phosphate", "5", "3"], "tip": "1C + 5C → 6C → 2 × 3C."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["slow", "slowly"], ["low co2", "low carbon dioxide", "not effective", "low concentrations"]], "tips": ["Two weaknesses of the enzyme."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 4, "n": 4, "ans": ["Both ATP and reduced NADP", "ATP", "5", "6"], "tip": "Reduction needs energy and hydrogen; regeneration needs only energy."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["intermediate", "triose phosphate", "tp", "products of the calvin cycle", "glycerate"], ["nitrate", "nitrogen", "mineral", "ammonium"]], "tips": ["Carbon skeleton + which mineral?"]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 3, "n": 3, "ans": ["Increases", "Decreases", "Decreases"], "tip": "Fixation continues briefly, but reduction stops."}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 3, "pts": [["calvin+stop", "calvin cycle stops", "no fixation", "not fixed"], ["nadp+not regenerated", "nadp runs out", "reduced nadp+not used", "no nadp", "nadp is not"], ["electron", "electrons cannot", "no acceptor", "flow stops"]], "tips": ["CO₂ → Calvin cycle → NADP → electron flow → PSII."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 4, "pts": [["rubisco", "carbon fixation", "fixed"], ["rubp", "ribulose"], ["triose phosphate", "tp", "reduced nadp"], ["regenerat", "five", "5"]], "tips": ["Fixation → reduction → regeneration."]}]}, "models": {"1": [["Q1", "Each molecule works slowly, so many molecules are needed to fix CO₂ fast enough to support growth."]], "2": [["Q2", "Rubisco fixes CO₂ onto RuBP (5C), forming two glycerate 3-phosphate (3C each)."], ["Q3", "Rubisco catalyses carbon fixation relatively slowly [1]; and it is not effective at low CO₂ concentrations, so many enzyme molecules are needed to fix enough carbon [1]."]], "3": [["Q4", "GP → TP: ATP and reduced NADP. Regeneration: ATP. 5 TP → 3 RuBP. 6 turns per glucose."], ["Q5", "Carbon skeletons come from Calvin cycle intermediates such as triose phosphate [1]; nitrogen from mineral nutrients (nitrate/ammonium absorbed by roots) is added to make amino acids [1]."]], "4": [["Q6", "GP increases (still made, not reduced). RuBP decreases (used, not regenerated). TP decreases."], ["Q7", "Without CO₂ the Calvin cycle stops, so reduced NADP and ATP are not used [1]; NADP is not regenerated, so there is no acceptor for electrons at PSI [1]; electron flow along the chain stops, so excited electrons cannot leave PSII and it stops functioning (no photolysis) [1]."]], "5": [["Q8", "CO₂ is fixed by Rubisco [1] onto RuBP, forming glycerate 3-phosphate [1]; GP is reduced to triose phosphate using ATP and reduced NADP [1]; five of every six TP are used to regenerate RuBP using ATP, so the cycle continues [1]."]], "6": [["Exit ticket", "RuBP + CO₂ → glycerate 3-phosphate, catalysed by Rubisco."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_1": "Q5", "q4_1": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '113ab9f2-eb4e-5866-bd31-85d3f0c56516', (select id from public.topics where programme = 'IB DP' and code = 'B3.1' limit 1), 'B3.1 Gas exchange · Lesson 1: Gas-exchange surfaces, the lungs, ventilation and lung volumes', 'IB DP Biology · B3.1 Gas exchange', '/b31-lesson1/', 'DP1-B31-L1', 27, 191 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-B31-L1', 'B3.1 Gas exchange · Lesson 1: Gas-exchange surfaces, the lungs, ventilation and lung volumes', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["Thin", "Large surface area", "Moist", "Ventilation", "Continuous blood flow"], "tip": "Three are properties of the surface; two keep the gradient steep."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 3, "pts": [["ventilation", "breathing", "fresh air", "air is replaced"], ["blood flow", "blood carries", "continuous", "carried away"], ["capillar", "blood vessels"]], "tips": ["Two things replace the gases on each side, and where the vessels are."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 5, "n": 5, "ans": ["Inspiration", "Inspiration", "Expiration", "Expiration", "Inspiration"], "tip": "Volume up → pressure down → air in."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 4, "pts": [["diaphragm+contract", "diaphragm contracts", "diaphragm flattens"], ["external intercostal", "ribs up", "ribs+out"], ["volume+increase", "volume increases", "thorax gets bigger"], ["pressure+fall", "pressure decreases", "lower pressure", "pressure drops", "below atmospheric"]], "tips": ["Muscles → ribs → volume → pressure → air movement."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 4, "n": 4, "ans": ["4.2 dm³", "3.0 dm³", "Tidal volume", "Vital capacity"], "tip": "Vital capacity = TV + IRV + ERV."}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 2, "pts": [["respiration", "more oxygen", "oxygen demand", "need more oxygen", "respire", "more o2", "need more"], ["carbon dioxide", "co2", "remove"]], "tips": ["Muscles need more of one gas and make more of the other."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 4, "pts": [["alveoli+surface", "large surface area", "many alveoli", "high surface area"], ["thin", "one cell", "short diffusion"], ["capillar", "blood supply"], ["surfactant", "moist", "bronchiole"]], "tips": ["Four features, each with its benefit."]}]}, "models": {"1": [["Q1", "The flatworm is thin and flat with a large SA:V and short diffusion distances, so diffusion through its skin is enough. The mouse is larger and more active, with a small SA:V and long distances, so it needs lungs."]], "2": [["Q2", "One cell thick: thin. 480 million alveoli: large surface area. Liquid film: moist. Breathing: ventilation. Blood moving O₂ away: continuous blood flow."], ["Q3", "Ventilation brings in fresh air, keeping O₂ concentration high in the alveoli [1]; continuous blood flow carries oxygenated blood away, keeping O₂ low in the blood [1]; a dense network of capillaries surrounds each alveolus, so the gradient is maintained over a large area [1]."]], "3": [["Q4", "Diaphragm contracting, external intercostals, ribs up and out: inspiration. Abdominal muscles, pressure rising: expiration."], ["Q5", "The diaphragm contracts and flattens [1]; external intercostal muscles contract, moving the ribs up and out [1]; the volume of the thorax increases [1]; so pressure inside falls below atmospheric pressure and air flows in [1]."]], "4": [["Q6", "VC = 0.5 + 2.5 + 1.2 = 4.2 dm³. From the end of a normal breath out you can breathe in TV + IRV = 3.0 dm³. One normal breath: tidal volume. Largest breath out: vital capacity."], ["Q7", "Muscles respire faster during exercise and need more O₂ [1]; more CO₂ is produced and must be removed, so deeper breaths increase gas exchange [1]."]], "5": [["Q8", "Millions of alveoli give a very large surface area [1]; alveolar and capillary walls are thin (one cell), so the diffusion distance is short [1]; dense capillary networks maintain the gradient [1]; surfactant keeps alveoli open and moist / branched bronchioles distribute air to all alveoli [1]."]], "6": [["Exit ticket", "Permeable, thin, moist, large surface area."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_1": "Q5", "q4_1": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '3402b0b7-f762-5296-be8d-516fdd61ef70', (select id from public.topics where programme = 'IB DP' and code = 'B3.1' limit 1), 'B3.1 Gas exchange · Lesson 2: Gas exchange in leaves, transpiration and stomatal density', 'IB DP Biology · B3.1 Gas exchange', '/b31-lesson2/', 'DP1-B31-L2', 18, 192 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-B31-L2', 'B3.1 Gas exchange · Lesson 2: Gas exchange in leaves, transpiration and stomatal density', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["Waxy cuticle", "Guard cells", "Spongy mesophyll", "Xylem", "Phloem"], "tip": "Two of these are in the vein."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 4, "n": 4, "ans": ["Increases", "Decreases", "Increases", "Decreases"], "tip": "Think about the water vapour gradient and the stomata."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["stomata+open", "stomata open", "open stomata"], ["carbon dioxide", "co2", "photosynthesis"]], "tips": ["Why must stomata open, and what escapes when they do?"]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 3, "n": 3, "ans": ["0.13 mm²", "240 mm⁻²", "Reliability"], "tip": "Radius = half the diameter."}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 2, "pts": [["vari", "differ", "not the same", "vary", "not evenly", "uneven"], ["reliab", "mean", "average", "representative"]], "tips": ["Biological material is not uniform."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 2, "pts": [["cuticle", "wax"], ["fewer stomata", "sunken", "hairs", "rolled", "small leaves", "spines"]], "tips": ["Think surface coating and the stomata."]}]}, "models": {"1": [["Q1", "The lower surface is shaded and cooler, so less water evaporates when stomata are open; it also avoids direct sunlight."]], "2": [["Q2", "Cuticle: reduces water loss. Guard cells: open/close stomata. Spongy mesophyll: gas exchange surface. Xylem: water in. Phloem: sugars out."], ["Q3", "Waxy cuticle, upper epidermis, palisade mesophyll, spongy mesophyll with air spaces, lower epidermis, stoma with guard cells, vascular bundle with xylem (upper) and phloem (lower)."]], "3": [["Q4", "Temperature up, wind: increases. Humidity up, darkness: decreases."], ["Q5", "Stomata must open to let CO₂ in for photosynthesis [1]; when they are open, water vapour diffuses out from the moist air spaces, so water loss is unavoidable [1]."]], "4": [["Q6", "Area = 3.14 × 0.2² ≈ 0.126 mm²; density ≈ 30 ÷ 0.126 ≈ 240 stomata mm⁻². Repeats improve reliability."], ["Q7", "Stomata are not evenly spread, so counts vary between fields of view [1]; a mean of several counts is more reliable / representative of the leaf [1]."]], "5": [["Q8", "Thick waxy cuticle reduces evaporation from the surface [1]; fewer or sunken stomata / hairs / rolled leaves trap humid air and reduce the water vapour gradient [1]."]], "6": [["Exit ticket", "Stomata must open for CO₂ to diffuse in, and water vapour diffuses out through the same openings."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_1": "Q5", "q4_1": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'ad8c00ac-3f09-557b-9825-f0eb11cdeff5', (select id from public.topics where programme = 'IB DP' and code = 'B3.1' limit 1), 'B3.1 Gas exchange · Lesson 3 (HL): Haemoglobin, oxygen dissociation curves and the Bohr shift', 'IB DP Biology · B3.1 Gas exchange', '/b31-lesson3/', 'DP1-B31-L3', 19, 193 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-B31-L3', 'B3.1 Gas exchange · Lesson 3 (HL): Haemoglobin, oxygen dissociation curves and the Bohr shift', '{"marks": {"2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 3, "pts": [["first+difficult", "first oxygen", "low affinity at low", "hard to bind"], ["shape change", "cooperative", "conformation", "easier"], ["plateau", "saturated", "all sites", "four"]], "tips": ["Explain the flat start, the steep middle and the plateau."]}, {"kind": "choice", "id": "q2_1", "q": "Q3", "max": 4, "n": 4, "ans": ["About 98%", "About 75%", "Respiring muscle", "Lungs"], "tip": "Only about a quarter of O₂ is unloaded at rest."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 4, "n": 4, "ans": ["Foetal", "Adult", "Foetal", "Adult"], "tip": "Oxygen moves from lower-affinity to higher-affinity haemoglobin."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["more saturated", "higher saturation", "binds more", "takes oxygen", "same partial pressure"], ["mother", "maternal", "placenta"]], "tips": ["Compare saturation at the same pO₂ in the placenta."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q6", "max": 3, "pts": [["carbon dioxide", "co2"], ["affinity+decrease", "lower affinity", "reduces affinity", "less affinity", "affinity falls", "lowers", "lower"], ["releases more", "more oxygen", "dissociat", "unload"]], "tips": ["CO₂ → affinity → oxygen released."]}], "5": [{"kind": "choice", "id": "q5_0", "q": "Q7", "max": 3, "n": 3, "ans": ["15%", "Right", "Lower"], "tip": "60 − 45."}]}, "models": {"1": [["Q1", "High affinity would load well in the lungs but not release O₂ in tissues; low affinity would release well but not load in the lungs. The affinity must change."]], "2": [["Q2", "At low pO₂ the first O₂ binds with difficulty, so the curve starts shallow [1]; binding changes the shape of haemoglobin, so further O₂ binds more easily (cooperative binding), giving the steep middle [1]; at high pO₂ all four haem groups are occupied, so the curve levels off [1]."], ["Q3", "Lungs ~98% (highest pO₂); venous blood at rest ~75%; the steep part matters in respiring tissue."]], "3": [["Q4", "Higher affinity, loads in placenta: foetal. Curve to the right, unloads in placenta: adult."], ["Q5", "At the low pO₂ in the placenta, foetal haemoglobin is more saturated than maternal haemoglobin [1]; so oxygen is transferred from the mother''s blood to the foetus''s blood [1]."]], "4": [["Q6", "Respiring muscle produces more CO₂ [1]; CO₂ lowers the affinity of haemoglobin for O₂ (curve shifts right) [1]; so more O₂ dissociates and is released to the muscle where it is needed [1]."]], "5": [["Q7", "15 percentage points more O₂ released; curve shifts right; affinity is lower."]], "6": [["Exit ticket", "Binding of one O₂ changes haemoglobin''s shape so further O₂ binds more easily. Higher CO₂ lowers haemoglobin''s affinity for O₂, shifting the curve right so more O₂ is released."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q2", "q3_1": "Q5", "q4_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'edb3d9ea-f225-5a19-93ae-406294cdbb5b', (select id from public.topics where programme = 'IB DP' and code = 'B3.2' limit 1), 'B3.2 Transport · Lesson 1: Capillaries, arteries, veins, pulse and coronary heart disease', 'IB DP Biology · B3.2 Transport', '/b32-lesson1/', 'DP1-B32-L1', 23, 201 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-B32-L1', 'B3.2 Transport · Lesson 1: Capillaries, arteries, veins, pulse and coronary heart disease', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["Capillary", "Vein", "Artery", "Vein", "Capillary"], "tip": "Pressure decides the wall."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 3, "pts": [["elastic"], ["stretch+recoil", "recoil", "stretches"], ["muscle", "thick"]], "tips": ["Two tissues and what each does."]}, {"kind": "text", "id": "q2_2", "q": "Q4", "max": 2, "pts": [["valve", "backflow"], ["muscle", "squeez", "compress"]], "tips": ["Two features."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q5", "max": 4, "n": 4, "ans": ["74 bpm", "Thumb has its own pulse", "Radial", "Carotid"], "tip": "Double a 30 s count."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q6", "max": 3, "pts": [["oxygen", "o2", "blood supply"], ["heart muscle", "cardiac muscle", "heart cells"], ["die", "death", "heart attack", "infarction", "angina"]], "tips": ["What does the blocked artery normally supply, and what happens without it?"]}, {"kind": "choice", "id": "q4_1", "q": "Q7", "max": 3, "n": 3, "ans": ["Strong positive", "No", "Other factors may cause both"], "tip": "Correlation is not causation."}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 3, "pts": [["thick+thin", "thicker wall", "thinner wall"], ["lumen", "narrow+wide", "wider lumen"], ["valve"], ["elastic", "muscle"]], "tips": ["Wall thickness, lumen, valves, tissues (any three)."]}]}, "models": {"1": [["Q1", "The artery wall is thick with muscle and elastic tissue to withstand high pressure; the capillary wall is one cell thick for fast exchange."]], "2": [["Q2", "One cell / fenestrations: capillary. Valves / wide lumen: vein. Elastic and muscle: artery."], ["Q3", "Elastic fibres stretch when blood is pumped in at high pressure [1] and recoil between heartbeats, pushing blood on and maintaining pressure [1]; a thick layer of smooth muscle (and collagen) makes the wall strong enough to withstand the pressure [1]."], ["Q4", "Valves prevent backflow so blood can only move towards the heart [1]; contracting skeletal muscles squeeze the thin, flexible walls, pushing blood along [1]."]], "3": [["Q5", "74 beats per minute; the thumb has its own pulse; wrist = radial; neck = carotid."]], "4": [["Q6", "Blood flow to part of the heart is reduced or stopped [1]; so the cardiac muscle beyond the blockage gets too little O₂ and cannot respire aerobically [1]; this causes chest pain (angina) or the death of heart muscle cells (heart attack) [1]."], ["Q7", "Strong positive correlation; it does not prove causation, because other factors (e.g. smoking, exercise, wealth) may cause both."]], "5": [["Q8", "Arteries have thicker walls than veins [1]; arteries have a narrow lumen, veins a wide lumen [1]; veins have valves, arteries do not (except at the heart) [1]; arteries have more elastic fibres and smooth muscle [1]. (Any three.)"]], "6": [["Exit ticket", "Capillaries: wall one cell thick / fenestrations. Arteries: elastic fibres. Veins: valves."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q2_2": "Q4", "q4_0": "Q6", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '32d4865e-5577-5477-9a4b-1f7f3cff2028', (select id from public.topics where programme = 'IB DP' and code = 'B3.2' limit 1), 'B3.2 Transport · Lesson 2: Water transport in xylem and the tissues of stems and roots', 'IB DP Biology · B3.2 Transport', '/b32-lesson2/', 'DP1-B32-L2', 14, 202 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-B32-L2', 'B3.2 Transport · Lesson 2: Water transport in xylem and the tissues of stems and roots', '{"marks": {"2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 4, "pts": [["evaporat", "transpiration"], ["cell wall", "capillary", "adhesion", "drawn out"], ["tension", "negative pressure", "pull"], ["cohesion", "hydrogen bond", "continuous column"]], "tips": ["Evaporation → replacement from xylem → tension → cohesion."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Lignin", "Pits", "No end walls", "No cell contents"], "tip": "Strength, side exits, continuous tube, empty lumen."}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q4", "max": 4, "n": 4, "ans": ["Stem", "Root", "Both", "Root"], "tip": "Ring = stem; centre = root."}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 2, "pts": [["tension", "negative pressure", "pulled"], ["collapse", "inward", "strength", "support"]], "tips": ["What force acts on the vessel walls?"]}]}, "models": {"1": [["Q1", "Lower pressure at the top pulls the water up; a leaf creates tension as water evaporates from its cell walls, pulling water up the xylem."]], "2": [["Q2", "Water evaporates from mesophyll cell walls and is lost by transpiration [1]; water is drawn out of the xylem through cell walls by capillary action/adhesion to replace it [1]; this creates tension (negative pressure) in the xylem that pulls water up [1]; cohesion between water molecules (hydrogen bonds) keeps the column continuous [1]."]], "3": [["Q3", "Lignin: strength. Pits: lateral movement. No end walls: continuous tube. No contents: unobstructed flow."]], "4": [["Q4", "Ring of bundles: stem. Central X of xylem and root hairs: root. Epidermis: both."], ["Q5", "Stem: epidermis (protection), cortex, ring of vascular bundles: phloem outside (sugar transport), xylem inside (water), pith. Root: epidermis with root hairs (absorption), cortex, central xylem (X shape) with phloem between the arms."]], "5": [["Q6", "Water in xylem is under tension (negative pressure) [1]; lignin strengthens the walls so the vessels do not collapse inward [1]."]], "6": [["Exit ticket", "Cohesion (hydrogen bonds between water molecules) and adhesion (to cell walls, giving capillary action)."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q2", "q4_1": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '75f6962d-3a53-5644-881b-c5737c1849c0', (select id from public.topics where programme = 'IB DP' and code = 'B3.2' limit 1), 'B3.2 Transport · Lesson 3 (HL): Tissue fluid, lymph, double circulation and the heart', 'IB DP Biology · B3.2 Transport', '/b32-lesson3/', 'DP1-B32-L3', 25, 203 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-B32-L3', 'B3.2 Transport · Lesson 3 (HL): Tissue fluid, lymph, double circulation and the heart', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["Plasma", "Both", "Tissue fluid", "Tissue fluid"], "tip": "Proteins stay in the blood."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 3, "pts": [["high pressure", "arteriole", "pressure filtration"], ["low pressure", "venule", "back into"], ["lymph"]], "tips": ["Arteriole end, venule end, and where the excess goes."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 4, "n": 4, "ans": ["Mammal", "Fish", "Mammal", "Both"], "tip": "Draw both circuits."}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q5", "max": 5, "n": 5, "ans": ["Vena cava", "Right ventricle", "Pulmonary vein", "Left ventricle", "Aorta"], "tip": "Body → right side → lungs → left side → body."}, {"kind": "text", "id": "q4_1", "q": "Q6", "max": 4, "pts": [["sinoatrial", "sa node", "pacemaker"], ["atri+contract", "atrial systole", "atrium contracts"], ["av valve+close", "atrioventricular valve closes", "atrioventricular+close"], ["semilunar+open", "aorta", "semilunar valve opens"]], "tips": ["Start at the SA node and follow the valves."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 2, "pts": [["body", "whole body", "systemic", "aorta"], ["pressure", "further", "greater distance", "more force"]], "tips": ["Where does each ventricle pump blood?"]}, {"kind": "choice", "id": "q5_1", "q": "Q8", "max": 3, "n": 3, "ans": ["135 mmHg", "85 mmHg", "Ventricular contraction"], "tip": "Systolic is the top number."}]}, "models": {"1": [["Q1", "Fluid would build up and the tissue would swell (oedema)."]], "2": [["Q2", "Proteins: plasma. Glucose and ions: both. Bathes cells and formed by filtration: tissue fluid."], ["Q3", "At the arteriole end, high blood pressure forces plasma out of the capillary (pressure filtration) [1]; at the venule end, pressure is lower so tissue fluid drains back into the capillary [1]; excess fluid drains into lymph ducts and returns to the blood [1]."]], "3": [["Q4", "Twice per circuit and pulmonary circulation: mammal. Gills to body: fish. Heart pumps deoxygenated blood to the exchange organ: both."]], "4": [["Q5", "Vena cava → right atrium → right ventricle → pulmonary artery → lungs → pulmonary vein → left atrium → left ventricle → aorta."], ["Q6", "The SA node starts the beat [1]; the atrium contracts, pushing blood through the open AV valve into the ventricle [1]; the ventricle contracts, pressure rises and the AV valve closes [1]; the semilunar valve opens and blood is pumped into the aorta; then the ventricle relaxes and the semilunar valve closes [1]."]], "5": [["Q7", "The left ventricle pumps blood to the whole body, the right only to the lungs [1]; so it must generate a much higher pressure, needing more cardiac muscle [1]."], ["Q8", "Systolic 135 mmHg, during ventricular contraction; diastolic 85 mmHg, during relaxation."]], "6": [["Exit ticket", "Tissue fluid lacks plasma proteins. Semilunar valves stop blood flowing back from the arteries into the ventricles."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q4_1": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
