insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-B32-L4', 'B3.2 Transport · Lesson 4 (HL): Root pressure and phloem translocation', '{"marks": {"2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 3, "pts": [["active transport", "pump", "atp"], ["ions", "mineral"], ["osmosis", "water follows", "water moves in"]], "tips": ["Ions, ATP, osmosis."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Sieve tube element", "Companion cell", "Sieve tube element", "Companion cell"], "tip": "One carries the sap; the other powers it."}, {"kind": "choice", "id": "q3_1", "q": "Q4", "max": 4, "n": 4, "ans": ["Source", "Sink", "Source", "Sink"], "tip": "Sources release sugar; sinks use or store it."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 3, "pts": [["sieve plate", "pores"], ["no nucleus", "few organelles", "reduced cytoplasm"], ["mitochondria", "atp", "load"], ["plasmodesmata"]], "tips": ["Features that ease flow, and features that power loading."]}]}, "models": {"1": [["Q1", "By pumping mineral ions into the xylem so water follows by osmosis, creating pressure."]], "2": [["Q2", "Mineral ions are actively transported (using ATP) [1] into the xylem in the root [1]; water follows by osmosis, creating a positive pressure that pushes water up [1]."]], "3": [["Q3", "No nucleus, sieve plates: sieve tube element. Mitochondria, loading: companion cell."], ["Q4", "Mature leaf and sprouting tuber: sources. Fruit and root tip: sinks."]], "4": [["Q5", "Sieve plates with pores let sap flow between elements [1]; no nucleus and reduced cytoplasm leave space for flow [1]; companion cells have many mitochondria providing ATP to load sucrose actively, passing it through plasmodesmata [1]."]], "6": [["Exit ticket", "When transpiration is low (high humidity, spring before leaves open); ATP for active transport of mineral ions in the root."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q2", "q4_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '70bf1993-4a9e-5f8f-bc3f-ed9247b046d7', (select id from public.topics where programme = 'IB DP' and code = 'B3.3' limit 1), 'B3.3 Muscle and motility · Lesson 1 (HL): Movement, the sliding filament model, titin and motor units', 'IB DP Biology · B3.3 Muscle and motility', '/b33-lesson1/', 'DP1-B33-L1', 23, 231 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-B33-L1', 'B3.3 Muscle and motility · Lesson 1 (HL): Movement, the sliding filament model, titin and motor units', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Sessile", "Motile", "Sessile", "Motile"], "tip": "Can the adult move from place to place?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["Gets shorter", "Stays the same length", "Stays the same length", "Gets closer together"], "tip": "Filaments slide; they do not shrink."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 4, "pts": [["calcium", "ca"], ["myosin+bind", "cross-bridge", "myosin heads attach", "bind to actin"], ["pull", "power stroke", "swivel", "slide"], ["atp"]], "tips": ["Ca²⁺ → binding → power stroke → ATP."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 2, "pts": [["only contract", "only pull", "cannot push", "only exert force"], ["stretch", "opposite", "relax", "lengthen"]], "tips": ["What can a muscle not do by itself?"]}, {"kind": "choice", "id": "q3_1", "q": "Q5", "max": 4, "n": 4, "ans": ["True", "True", "False", "True"], "tip": "Cross-bridges are formed by myosin."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q6", "max": 3, "pts": [["motor neuron", "motor neurone"], ["muscle fibres", "fibers"], ["neuromuscular junction", "synapse"]], "tips": ["Three parts."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 2, "pts": [["atp", "no atp"], ["detach", "remain attached", "cross-bridges+remain", "stay bound", "cannot release"]], "tips": ["What is ATP needed for in the cycle?"]}]}, "models": {"1": [["Q1", "Sea anemone and barnacle: sessile. Cheetah and jellyfish: motile."]], "2": [["Q2", "Sarcomere shortens; actin and myosin stay the same length; Z lines move closer."], ["Q3", "Calcium ions are released and expose binding sites on actin [1]; myosin heads bind to actin, forming cross-bridges [1]; the heads swivel, pulling actin filaments towards the centre so filaments slide and the sarcomere shortens [1]; ATP is used to detach and re-cock the myosin heads so the cycle repeats [1]."]], "3": [["Q4", "A muscle can only exert force by contracting (pulling) [1]; so a second, antagonistic muscle is needed to pull in the opposite direction and stretch the first back to its original length [1]."], ["Q5", "True, true, false (myosin forms cross-bridges), true."]], "4": [["Q6", "One motor neuron [1]; the group of muscle fibres it controls [1]; connected by neuromuscular junctions (synapses using acetylcholine) [1]."]], "5": [["Q7", "After death no ATP is produced [1]; so myosin heads cannot detach from actin and the cross-bridges remain, locking the muscle [1]."]], "6": [["Exit ticket", "Ca²⁺ exposes binding sites → myosin binds actin → power stroke pulls actin → ATP binds, myosin detaches → ATP hydrolysed, head re-cocked."]]}, "labels": {"q2_1": "Q3", "q3_0": "Q4", "q4_0": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '7a60aa08-2658-5c12-8460-0f591404f1da', (select id from public.topics where programme = 'IB DP' and code = 'B3.3' limit 1), 'B3.3 Muscle and motility · Lesson 2 (HL): Skeletons, joints, intercostal muscles and locomotion', 'IB DP Biology · B3.3 Muscle and motility', '/b33-lesson2/', 'DP1-B33-L2', 23, 232 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-B33-L2', 'B3.3 Muscle and motility · Lesson 2 (HL): Skeletons, joints, intercostal muscles and locomotion', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Exoskeleton", "Endoskeleton", "Exoskeleton", "Exoskeleton"], "tip": "Arthropods = exo."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["Synovial fluid", "Ligament", "Tendon", "Cartilage", "Femur"], "tip": "Ligaments = bone–bone; tendons = muscle–bone."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["goniometer", "angle", "photo", "image analysis"], ["repeat", "several", "same person", "maximum", "dimensions", "planes"]], "tips": ["Instrument, and how to make it fair and reliable."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 2, "pts": [["opposite", "different directions"], ["stretch", "titin"]], "tips": ["Direction of movement and effect on the other layer."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q5", "max": 4, "n": 4, "ans": ["Migration", "Foraging", "Escaping danger", "Searching for a mate"], "tip": "Food, danger, mate, seasonal movement."}, {"kind": "text", "id": "q4_1", "q": "Q6", "max": 3, "pts": [["streamlin"], ["flipper"], ["fluke", "tail"], ["blowhole", "airway", "breath"]], "tips": ["Body shape, limbs, tail, breathing (any three)."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 3, "pts": [["cartilage"], ["synovial fluid", "lubricat"], ["ligament", "capsule", "stable"]], "tips": ["Surfaces, lubrication, stability."]}]}, "models": {"1": [["Q1", "Grasshopper, crab, muscles inside: exoskeleton. Human: endoskeleton."]], "2": [["Q2", "Fluid: lubricates. Ligament: bone to bone. Tendon: muscle to bone. Cartilage: friction and shock. Femur: ball."], ["Q3", "Measure the maximum angle of movement with a goniometer or by analysing photographs [1]; in each plane/dimension, repeating measurements on several people and comparing means [1]."]], "3": [["Q4", "Their fibres are orientated differently, so they move the ribcage in opposite directions [1]; when one layer contracts it stretches the other, storing energy in titin [1]."]], "4": [["Q5", "Wildebeest: migration. Bee: foraging. Gazelle: escaping danger. Moth: searching for a mate."], ["Q6", "Streamlined body reduces drag [1]; forelimbs form flippers for steering [1]; tail forms a fluke moved up and down for propulsion [1]; blowhole/modified airways allow rapid breathing between dives [1]. (Any three.)"]], "5": [["Q7", "Smooth cartilage covers the bone ends, reducing friction [1]; synovial fluid lubricates the joint [1]; ligaments hold the bones together so the joint is stable while moving [1]."]], "6": [["Exit ticket", "Femur and pelvis; tendon."]]}, "labels": {"q2_1": "Q3", "q3_0": "Q4", "q4_1": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'e82ef56b-a6f0-5817-9d5c-7e332ffb4253', (select id from public.topics where programme = 'IB DP' and code = 'D1.1' limit 1), 'D1.1 DNA replication · Lesson 1: Semi-conservative replication, PCR and gel electrophoresis', 'IB DP Biology · D1.1 DNA replication', '/d11-lesson1/', 'DP1-D11-L1', 23, 131 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-D11-L1', 'D1.1 DNA replication · Lesson 1: Semi-conservative replication, PCR and gel electrophoresis', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["Helicase", "DNA polymerase", "Complementary base pairing", "Semi-conservative"], "tip": "Two enzymes, two ideas."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["a+t", "adenine+thymine", "only pairs", "one partner"], ["template", "same sequence", "identical"]], "tips": ["Each base has only one partner."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 6, "n": 6, "ans": ["95 °C", "55 °C", "72 °C", "Strands separate", "Primers bind", "Taq adds nucleotides"], "tip": "Hot, cool, warm."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["heat-stable", "heat stable", "thermostable", "not denatured", "hot spring", "high temperature"], ["95", "each cycle", "repeated", "denaturation"]], "tips": ["What happens to most enzymes at 95 °C?"]}, {"kind": "choice", "id": "q3_2", "q": "Q6", "max": 3, "n": 3, "ans": ["8", "32", "1024"], "tip": "2ⁿ."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q7", "max": 3, "pts": [["negative", "phosphate"], ["positive", "anode", "electric"], ["small", "size", "further", "faster"]], "tips": ["Charge, direction, size."]}, {"kind": "choice", "id": "q4_1", "q": "Q8", "max": 1, "n": 1, "ans": ["Man 1: C, F, G, H"], "tip": "Bands not from the mother must come from the father."}], "5": [{"kind": "text", "id": "q5_0", "q": "Q9", "max": 2, "pts": [["complementary", "bind", "anneal"], ["start", "starting point", "polymerase", "which section", "target", "specific"]], "tips": ["What they bind to and why."]}]}, "models": {"1": [["Q1", "Daughter cells need the same genes to make the same proteins; mistakes (mutations) could make faulty proteins or cause cancer."]], "2": [["Q2", "Helicase separates; polymerase joins; A–T is complementary base pairing; one old + one new strand is semi-conservative."], ["Q3", "Each base pairs with only one complementary base (A with T, C with G) [1]; so the template strand determines the sequence of the new strand, producing an identical copy of the original molecule [1]."]], "3": [["Q4", "Denaturation 95 °C: strands separate. Annealing 55 °C: primers bind. Extension 72 °C: Taq adds nucleotides."], ["Q5", "Taq polymerase is heat-stable (from a hot-spring bacterium) [1]; it is not denatured at 95 °C during the denaturation step, so it can work through every cycle without being replaced [1]."], ["Q6", "2³ = 8; 2⁵ = 32; 2¹⁰ = 1024."]], "4": [["Q7", "DNA is negatively charged because of its phosphate groups [1]; in an electric field it moves towards the positive electrode [1]; smaller fragments move faster through the pores of the gel, so fragments are separated by size [1]."], ["Q8", "Child''s C and F are not from the mother, so they must come from the father: Man 1 (C, F, G, H)."]], "5": [["Q9", "Primers are short sequences complementary to the ends of the target DNA, which bind (anneal) to it [1]; they select the section to be copied and provide a starting point for Taq polymerase [1]."]], "6": [["Exit ticket", "Each new DNA molecule contains one original and one new strand. Taq is heat-stable, so it survives the 95 °C denaturation step."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_1": "Q5", "q4_0": "Q7", "q5_0": "Q9", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '173ebd98-0aa5-5848-95fd-a01aeaca8c5d', (select id from public.topics where programme = 'IB DP' and code = 'D1.1' limit 1), 'D1.1 DNA replication · Lesson 2 (HL): Directionality, leading and lagging strands, replication enzymes and proofreading', 'IB DP Biology · D1.1 DNA replication', '/d11-lesson2/', 'DP1-D11-L2', 16, 132 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-D11-L2', 'D1.1 DNA replication · Lesson 2 (HL): Directionality, leading and lagging strands, replication enzymes and proofreading', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 3, "n": 3, "ans": ["5''", "3''", "5'' → 3''"], "tip": "Polymerase extends from the 3'' OH."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 5, "n": 5, "ans": ["DNA primase", "DNA polymerase III", "DNA polymerase I", "DNA ligase", "Helicase"], "tip": "Five enzymes, five jobs."}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 3, "pts": [["continuous", "continuously"], ["okazaki", "discontinuous", "fragments"], ["primer+once", "one primer", "many primers", "each fragment", "repeatedly"]], "tips": ["How it is made, in what pieces, how many primers."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["polymerase iii", "pol iii", "dna polymerase"], ["mismatch", "removes", "incorrect", "replace"]], "tips": ["Which enzyme, what does it remove, what does it add?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 3, "pts": [["antiparallel", "opposite direction"], ["5''+3''", "only add to the 3''", "5'' to 3''", "3'' end"], ["away from the fork", "short", "as it opens", "fork"]], "tips": ["Antiparallel strands + polymerase direction."]}]}, "models": {"1": [["Q1", "One wall can be built continuously towards the moving point, the other must be built in short sections away from it."]], "2": [["Q2", "Free phosphate: 5'' end. Nucleotides added to the 3'' end. New strand grows 5'' → 3''."]], "3": [["Q3", "Primers: primase. Extending: pol III. Replacing primers: pol I. Joining fragments: ligase. Unwinding: helicase."], ["Q4", "The leading strand is synthesised continuously towards the fork [1]; the lagging strand is synthesised discontinuously in Okazaki fragments away from the fork [1]; the leading strand needs an RNA primer only once, the lagging strand needs a new primer for each fragment [1]."]], "4": [["Q5", "DNA polymerase III checks the newly added base pairs [1]; it removes a nucleotide with a mismatched base from the 3'' end and replaces it with the correct one [1]."]], "5": [["Q6", "The two strands are antiparallel [1]; DNA polymerase can only add nucleotides to the 3'' end, building 5''→3'' [1]; on the lagging strand this is away from the fork, so short fragments are made each time more of the template is exposed [1]."]], "6": [["Exit ticket", "DNA ligase joins fragments; DNA polymerase III proofreads."]]}, "labels": {"q1_0": "Q1", "q3_1": "Q4", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '62556104-6f74-5244-8f7a-347575495e61', (select id from public.topics where programme = 'IB DP' and code = 'D1.2' limit 1), 'D1.2 Protein synthesis · Lesson 1: Transcription and gene expression', 'IB DP Biology · D1.2 Protein synthesis', '/d12-lesson1/', 'DP1-D12-L1', 16, 141 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-D12-L1', 'D1.2 Protein synthesis · Lesson 1: Transcription and gene expression', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["A", "U", "G", "C"], "tip": "RNA uses U instead of T."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 3, "pts": [["unwind", "separate", "hydrogen bonds"], ["template", "complementary"], ["join", "link", "covalent", "bonds rna nucleotides"]], "tips": ["Opens the DNA, reads it, builds RNA."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 2, "pts": [["do not divide", "don''t divide", "not divide", "no replication", "long life", "whole life"], ["conserved", "unchanged", "transcribed many times", "repeatedly", "same sequence"]], "tips": ["Neurons last a lifetime."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q5", "max": 4, "n": 4, "ans": ["False", "True", "False", "True"], "tip": "Gene expression = transcription + translation."}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 3, "pts": [["both+complementary", "both use complementary", "both+template", "both+hydrogen"], ["rna polymerase+dna polymerase", "different enzymes", "rna polymerase"], ["one strand", "both strands", "uracil", "u instead", "gene"]], "tips": ["One similarity, two differences."]}]}, "models": {"1": [["Q1", "The DNA stays safe in the nucleus; many RNA copies can be made quickly for many proteins; RNA copies can be broken down when no longer needed."]], "2": [["Q2", "T→A, A→U, C→G, G→C. mRNA: A U G C C U A G U."], ["Q3", "RNA polymerase unwinds the DNA and separates the strands by breaking hydrogen bonds [1]; it uses one strand as a template so RNA nucleotides pair with complementary bases [1]; it joins the RNA nucleotides together with covalent bonds to make the mRNA strand [1]."]], "3": [["Q4", "Neurons do not divide, so their DNA is not renewed by replication [1]; the same template must be transcribed many times over the life of the cell without its sequence changing [1]."]], "4": [["Q5", "False, true, false, true."]], "5": [["Q6", "Both use a DNA template and complementary base pairing [1]; replication uses DNA polymerase, transcription uses RNA polymerase [1]; replication copies both strands of the whole molecule, transcription copies one strand of one gene and uses uracil instead of thymine [1]."]], "6": [["Exit ticket", "RNA polymerase; uracil."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_0": "Q4", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'deda23ab-8d45-54ff-9418-75af5c1102a3', (select id from public.topics where programme = 'IB DP' and code = 'D1.2' limit 1), 'D1.2 Protein synthesis · Lesson 2: Translation, the genetic code and mutations that change proteins', 'IB DP Biology · D1.2 Protein synthesis', '/d12-lesson2/', 'DP1-D12-L2', 23, 142 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-D12-L2', 'D1.2 Protein synthesis · Lesson 2: Translation, the genetic code and mutations that change proteins', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["tRNA", "Codon", "Anticodon", "Small subunit", "Large subunit"], "tip": "Codon on mRNA; anticodon on tRNA."}, {"kind": "choice", "id": "q2_1", "q": "Q3", "max": 3, "n": 3, "ans": ["Degenerate", "Universal", "Triplet"], "tip": "Many codons, one amino acid = degenerate."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 5, "n": 5, "ans": ["Met", "Phe", "Gly", "Trp", "Stop"], "tip": "Use the codons listed in the notes."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 3, "pts": [["codon+anticodon", "anticodon", "trna binds"], ["peptide bond"], ["moves", "next codon", "along the mrna", "one codon"]], "tips": ["tRNA arrives → bond forms → ribosome moves."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q6", "max": 4, "pts": [["gag+gug", "codon changes", "a to t", "adenine+thymine", "cac"], ["glutamic", "glutamate"], ["valine"], ["sickle", "stick together", "fibres", "insoluble"]], "tips": ["Codon → amino acid → haemoglobin → cell shape."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 3, "pts": [["three bases", "3 bases"], ["64", "20"], ["more than one codon", "several codons", "same amino acid"]], "tips": ["Count the combinations."]}]}, "models": {"1": [["Q1", "4 bases give only 4 codes; pairs give 16 (not enough); triplets give 64, enough for 20 amino acids."]], "2": [["Q2", "tRNA carries amino acids; codon on mRNA; anticodon on tRNA; mRNA binds the small subunit; two tRNAs bind the large subunit."], ["Q3", "Several codons for glycine: degenerate. Human genes work in bacteria: universal. Three bases: triplet."]], "3": [["Q4", "Met – Phe – Gly – Trp – stop."], ["Q5", "A tRNA with the complementary anticodon binds to the next codon, bringing its amino acid [1]; a peptide bond forms between this amino acid and the growing polypeptide [1]; the ribosome moves along the mRNA by one codon and the empty tRNA is released [1]."]], "4": [["Q6", "A base substitution changes the codon GAG to GUG in the mRNA [1]; so glutamic acid [1] is replaced by valine in the β chain of haemoglobin [1]; the altered haemoglobin forms fibres at low O₂, giving sickle-shaped red blood cells that block capillaries [1]."]], "5": [["Q7", "Each codon has three bases [1]; 4³ = 64 codons, more than enough for 20 amino acids [1]; so most amino acids are coded for by more than one codon, which is why it is degenerate [1]."]], "6": [["Exit ticket", "Met – Glu. The mutation changes GAG to GUG, so glutamic acid becomes valine."]]}, "labels": {"q1_0": "Q1", "q3_1": "Q5", "q4_0": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '501e3472-231f-523e-b9a3-464500aa6f36', (select id from public.topics where programme = 'IB DP' and code = 'D1.2' limit 1), 'D1.2 Protein synthesis · Lesson 3 (HL): Directionality, promoters, introns, splicing, initiation and modification', 'IB DP Biology · D1.2 Protein synthesis', '/d12-lesson3/', 'DP1-D12-L3', 21, 143 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-D12-L3', 'D1.2 Protein synthesis · Lesson 3 (HL): Directionality, promoters, introns, splicing, initiation and modification', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["Non-coding", "Coding", "Non-coding", "Non-coding", "Non-coding"], "tip": "Non-coding = does not code for a polypeptide (tRNA genes make RNA, not protein)."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["transcription factor", "binds"], ["rna polymerase", "start", "initiat"]], "tips": ["What binds there, and what that allows."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 3, "pts": [["intron+remov", "introns are removed", "remove introns"], ["exon+splic", "exons joined", "spliced"], ["cap", "poly"]], "tips": ["Removed, joined, added."]}, {"kind": "choice", "id": "q3_1", "q": "Q5", "max": 4, "n": 4, "ans": ["Possible", "Possible", "Possible", "Not possible"], "tip": "Different combinations of exons; introns are removed."}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 3, "n": 3, "ans": ["A site", "P site", "E site"], "tip": "A = arrival, P = polypeptide, E = exit."}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 2, "pts": [["signal sequence", "signal peptide"], ["c-peptide", "c peptide", "c chain"]], "tips": ["What is removed at each stage?"]}, {"kind": "text", "id": "q5_1", "q": "Q8", "max": 2, "pts": [["break down", "degrade", "damaged", "unneeded"], ["amino acids+recycl", "recycle", "reused", "proteome"]], "tips": ["What do they do and what happens to the products?"]}]}, "models": {"1": [["Q1", "By joining different combinations of its coding sections (exons) after transcription."]], "2": [["Q2", "Only the exon codes for a polypeptide; promoter, intron, telomere and tRNA gene are non-coding."], ["Q3", "Transcription factors bind to the promoter sequence [1]; this allows RNA polymerase to bind and initiate transcription of the gene [1]."]], "3": [["Q4", "Introns are removed [1]; exons are spliced together to form mature mRNA [1]; a 5'' cap and a 3'' polyA tail are added to stabilise the mRNA [1]."], ["Q5", "1-2-3-4, 1-3-4 and 1-2-4 are possible variants; introns are removed, so a variant containing an intron is not."]], "4": [["Q6", "Arrival: A site. Growing chain: P site. Exit: E site."]], "5": [["Q7", "The signal sequence is removed, forming proinsulin [1]; then the C-peptide is cut out, leaving the A and B chains of insulin joined by disulfide bonds [1]."], ["Q8", "Proteasomes break down damaged or no-longer-needed proteins [1]; the amino acids are recycled to make new proteins, keeping the proteome functional [1]."]], "6": [["Exit ticket", "Removal of introns/splicing of exons; 5'' cap and polyA tail. A, P and E sites."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_0": "Q4", "q5_0": "Q7", "q5_1": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'e8088031-7c5f-56bb-a432-78613e731c69', (select id from public.topics where programme = 'IB DP' and code = 'D1.3' limit 1), 'D1.3 Mutation and gene editing · Lesson 1: Types, causes and consequences of gene mutation', 'IB DP Biology · D1.3 Mutation and gene editing', '/d13-lesson1/', 'DP1-D13-L1', 22, 151 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-D13-L1', 'D1.3 Mutation and gene editing · Lesson 1: Types, causes and consequences of gene mutation', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["Silent substitution", "Nonsense substitution", "Missense substitution", "Frameshift"], "tip": "Compare each codon with the original."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 3, "pts": [["frameshift", "reading frame", "shift"], ["every codon", "all codons", "all following", "after the mutation", "downstream"], ["substitution+one", "only one codon", "one amino acid", "degenera", "silent"]], "tips": ["Compare how many codons are changed."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 4, "n": 4, "ans": ["Chemical mutagen", "Mutagenic radiation", "Mutagenic radiation", "Chemical mutagen"], "tip": "Two of each."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["anywhere", "any base", "any position", "any gene"], ["not deliberate", "no mechanism", "not directed", "not in response", "no purpose", "cannot choose"]], "tips": ["Where can they occur, and can an organism choose a useful one?"]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 4, "n": 4, "ans": ["Germ cell", "Somatic cell", "Germ cell", "Somatic cell"], "tip": "Only mutations in the gamete line are inherited."}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 2, "pts": [["source", "new alleles", "variation"], ["natural selection", "beneficial", "advantage", "selected"]], "tips": ["Where does variation come from?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 3, "pts": [["mutagen", "mutation", "damages dna"], ["skin cells", "somatic"], ["cell cycle", "uncontrolled", "divide", "tumour", "tumor"]], "tips": ["Mutagen → which cells → which genes → result."]}]}, "models": {"1": [["Q1", "THC ATS AWT HED OG: every word after the deletion is changed. Deleting a base shifts the reading frame, changing every codon after it."]], "2": [["Q2", "GGA still Gly: silent. GAA→UAA stop: nonsense. UUU→UCU (Phe→Ser): missense. One G deleted, frame shifts: frameshift."], ["Q3", "An insertion shifts the reading frame (frameshift) [1]; so every codon after it is changed, altering many amino acids or creating an early stop, so the polypeptide is unlikely to work [1]; a substitution changes only one codon, which may give one different amino acid or none at all because the code is degenerate [1]."]], "3": [["Q4", "Benzo[a]pyrene and aflatoxin: chemical. UV and gamma: radiation."], ["Q5", "Mutations can occur anywhere in the base sequence of a genome (although some bases mutate more often) [1]; there is no mechanism for deliberately changing a particular base to produce a beneficial trait [1]."]], "4": [["Q6", "Inherited and in every cell of the child: germ cell. Skin cancer and lost at death: somatic."], ["Q7", "Mutation is the original source of new alleles and genetic variation [1]; occasionally a mutation is beneficial, and natural selection can increase its frequency, so species evolve [1]."]], "5": [["Q8", "UV radiation is a mutagen that damages DNA, causing mutations [1]; in somatic skin cells [1]; if genes controlling the cell cycle are mutated, cells divide uncontrollably, forming a tumour [1]."]], "6": [["Exit ticket", "Benzo[a]pyrene; UV light. Silent: a substitution that still codes for the same amino acid. Frameshift: an insertion/deletion that changes every codon after it."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_1": "Q5", "q4_1": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '20722444-8a81-5f43-9f9f-59f7f5e9e174', (select id from public.topics where programme = 'IB DP' and code = 'D1.3' limit 1), 'D1.3 Mutation and gene editing · Lesson 2 (HL): Gene knockout, CRISPR–Cas9 and conserved sequences', 'IB DP Biology · D1.3 Mutation and gene editing', '/d13-lesson2/', 'DP1-D13-L2', 14, 152 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-D13-L2', 'D1.3 Mutation and gene editing · Lesson 2 (HL): Gene knockout, CRISPR–Cas9 and conserved sequences', '{"marks": {"2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["inoperative", "switched off", "not work", "inactivate", "disable"], ["compare", "phenotype", "observe", "effect"]], "tips": ["What is done to the gene, then what is looked for?"]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Guide RNA", "Cas9", "Template DNA", "Cell''s repair system"], "tip": "Find, cut, insert, repair."}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 3, "pts": [["guide rna", "complementary"], ["cas9+cut", "cuts", "double-strand break", "break"], ["repair", "template", "insert", "new sequence"]], "tips": ["Targeting, cutting, repairing."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["function", "essential", "selection", "harmful", "important"], ["slower", "lower rate", "less mutation", "rate of mutation"]], "tips": ["One about selection, one about mutation rate."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 3, "pts": [["different", "countries", "laws vary", "regulations vary"], ["embryo", "germ line", "inherited", "designer", "unknown", "off-target", "risk"], ["benefit", "treat", "cure", "disease", "food"]], "tips": ["Why rules differ, the risks, the benefits."]}]}, "models": {"1": [["Q1", "Make the gene inoperative (knock it out) and compare the mouse with normal mice to see what changes."]], "2": [["Q2", "The gene is changed so that it is inoperative [1]; the phenotype of the knockout organism is compared with normal organisms to reveal the gene''s function [1]."]], "3": [["Q3", "Guide RNA finds; Cas9 cuts; template DNA supplies the new sequence; the cell repairs."], ["Q4", "A guide RNA complementary to the target sequence is made [1]; it guides Cas9 to the target, where Cas9 cuts both DNA strands [1]; the cell repairs the break, inserting a supplied template sequence (or introducing errors that knock the gene out) [1]."]], "4": [["Q5", "The gene product has essential functions, so mutations are harmful and removed by natural selection [1]; the sequence may have a slower rate of mutation [1]."]], "5": [["Q6", "Scientists in different countries work under different regulations, so practices banned in one country may be done in another [1]; risks include off-target edits and heritable germ-line changes in embryos [1]; but editing has major benefits (curing genetic diseases, better crops), so shared rules allow benefits while limiting risks [1]."]], "6": [["Exit ticket", "It pairs with the target DNA and leads Cas9 to it. A knockout shows the gene''s function by showing what goes wrong without it."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q2", "q3_1": "Q4", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'a8310200-6094-5b01-a8b2-8df32458f623', (select id from public.topics where programme = 'IB DP' and code = 'D2.2' limit 1), 'D2.2 Gene expression · Lesson 1 (HL): Regulating transcription and translation, and the genome, transcriptome and proteome', 'IB DP Biology · D2.2 Gene expression', '/d22-lesson1/', 'DP1-D22-L1', 14, 161 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-D22-L1', 'D2.2 Gene expression · Lesson 1 (HL): Regulating transcription and translation, and the genome, transcriptome and proteome', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 3, "n": 3, "ans": ["Transcription factor", "Promoter", "Enhancer"], "tip": "Two are DNA sequences; one is a protein."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 3, "pts": [["transcription factor", "activator", "protein"], ["promoter", "enhancer"], ["rna polymerase"]], "tips": ["Which proteins bind where, and what they help."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 2, "pts": [["nuclease", "broken down", "degrad"], ["more protein", "translated more", "longer", "more times", "less protein"]], "tips": ["Lifetime of mRNA → amount of protein."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q5", "max": 4, "n": 4, "ans": ["Genome", "Transcriptome", "Proteome", "Transcriptome"], "tip": "DNA → RNA → protein."}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 2, "pts": [["different genes", "gene expression", "expressed", "switched on"], ["transcri", "mrna", "translat"]], "tips": ["Which genes are used?"]}]}, "models": {"1": [["Q1", "Gene transcribed to mRNA → translated to the enzyme tyrosinase → enzyme catalyses melanin synthesis → melanin pigments the hair."]], "2": [["Q2", "Protein: transcription factor. RNA polymerase binding site: promoter. Distant activating sequence: enhancer."], ["Q3", "Transcription factors/activator proteins [1] bind to specific sequences at the promoter or enhancers [1]; this helps RNA polymerase bind and transcribe the gene more often [1]."]], "3": [["Q4", "mRNA is broken down by nucleases after a controlled time [1]; mRNA that persists longer is translated more times, producing more protein, while rapidly degraded mRNA gives little [1]."]], "4": [["Q5", "Same in all cells: genome. All mRNA: transcriptome. All proteins: proteome. First to change in a response: transcriptome."]], "5": [["Q6", "Different genes are expressed in each cell type [1]; so different mRNAs are transcribed and translated, producing different proteins [1]."]], "6": [["Exit ticket", "Transcriptome: all RNA transcribed in a cell at a time. Proteome: all proteins produced by a cell at a time."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_0": "Q4", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'e3e45205-e281-5e1d-9746-79d17d60abee', (select id from public.topics where programme = 'IB DP' and code = 'D2.2' limit 1), 'D2.2 Gene expression · Lesson 2 (HL): Epigenetic tags, epigenetic inheritance and the environment', 'IB DP Biology · D2.2 Gene expression', '/d22-lesson2/', 'DP1-D22-L2', 17, 162 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-D22-L2', 'D2.2 Gene expression · Lesson 2 (HL): Epigenetic tags, epigenetic inheritance and the environment', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["True", "False", "True", "True"], "tip": "Only one is false."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["cytosine", "methyl"], ["promoter", "represses", "transcription", "rna polymerase"]], "tips": ["Where are methyl groups added, and what process is blocked?"]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 2, "pts": [["same genome", "identical dna", "same genes", "genetically identical", "identical genome"], ["environment", "differences", "epigenetic"]], "tips": ["What is the same and what can differ?"]}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["not all", "imprint", "tags remain", "some tags"], ["father", "mother", "parent", "lion", "tiger"]], "tips": ["Tags left on the gametes, and which parent each comes from."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 4, "n": 4, "ans": ["Switched on", "Switched off", "Switched off", "Switched on"], "tip": "Make what is needed, stop making what is not."}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 3, "pts": [["methyl", "epigenetic tag", "histone"], ["pollution", "diet", "smoking", "environment"], ["sequence", "genotype", "not changed", "unchanged"]], "tips": ["Factor → tags → expression → phenotype, with DNA sequence unchanged."]}]}, "models": {"1": [["Q1", "Different environments (diet, smoking, pollution) change gene expression through epigenetic tags, so the same genes are expressed differently."]], "2": [["Q2", "True, false (sequence unchanged), true, true."], ["Q3", "Methyl groups are added to cytosine bases in the promoter of the gene [1]; this represses transcription (RNA polymerase/transcription factors cannot bind), so the gene is not expressed [1]."]], "3": [["Q4", "Monozygotic twins have identical genomes [1]; so differences in their phenotype or gene expression must be caused by the environment (through epigenetic changes) [1]."], ["Q5", "Not all epigenetic tags are removed from sperm and eggs, so some genes are imprinted according to the parent they came from [1]; in ligers the growth-limiting tags from a lioness mother are missing, so growth genes are over-expressed, while in tigons the lioness''s tags limit growth [1]."]], "4": [["Q6", "Lactose present: on. Absent: off. Tryptophan plentiful: off. Oestrogen target genes: on."]], "5": [["Q7", "Environmental factors such as air pollution or diet [1] alter epigenetic tags such as DNA methylation or histone modification [1]; this changes which genes are expressed and so the phenotype, while the DNA base sequence (genotype) is unchanged [1]."]], "6": [["Exit ticket", "DNA (cytosine) methylation and histone methylation. No: only gene expression and phenotype change."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_0": "Q4", "q3_1": "Q5", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
