insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-D23-L1', 'D2.3 Water potential · Lesson 1: Solvation, osmosis, tonicity and the effects on cells', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 3, "n": 3, "ans": ["Into the cell", "Out of the cell", "No net movement"], "tip": "Water moves towards the higher solute concentration."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["oxygen+na", "negative+sodium", "δ- oxygen", "partial negative+positive ion", "oxygen faces"], ["hydrogen+cl", "positive+chloride", "δ+ hydrogen", "partial positive+negative ion", "hydrogen faces"]], "tips": ["Which end of the water molecule faces which ion?"]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 4, "n": 4, "ans": ["0.0", "Between 0.2 and 0.4", "Hypertonic", "Hypotonic"], "tip": "Isotonic where the change crosses zero."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["different", "starting mass", "initial mass", "vary"], ["compare", "fair"]], "tips": ["Were all the cylinders exactly the same mass?"]}, {"kind": "text", "id": "q3_2", "q": "Q6", "max": 2, "pts": [["reliab", "precision", "spread", "variation", "uncertainty"], ["overlap", "significant"]], "tips": ["What does it mean if two bars overlap?"]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q7", "max": 5, "n": 5, "ans": ["Bursts", "Crenates", "Becomes turgid", "Plasmolysis", "No visible change"], "tip": "Walls prevent bursting."}, {"kind": "text", "id": "q4_1", "q": "Q8", "max": 2, "pts": [["cell wall", "wall"], ["turgor", "pressure", "resists", "prevents"]], "tips": ["What pushes back?"]}, {"kind": "text", "id": "q4_2", "q": "Q9", "max": 2, "pts": [["isotonic", "same concentration", "no net"], ["swell", "shrink", "damage", "burst"]], "tips": ["What would happen to the cells otherwise?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q10", "max": 3, "pts": [["hypotonic", "fresh water", "lower solute"], ["water enters", "osmosis", "into the cell"], ["pump", "expel", "remove", "burst"]], "tips": ["Where is the protist, what happens to water, what does the vacuole do?"]}]}, "models": {"1": [["Q1", "The solution is hypertonic, so water leaves the cells by osmosis and they shrink and crenate."]], "2": [["Q2", "Hypotonic: in. Hypertonic: out. Isotonic: no net movement (dynamic equilibrium)."], ["Q3", "The partially negative oxygen of water is attracted to Na⁺ ions [1]; the partially positive hydrogens are attracted to Cl⁻ ions, so water molecules surround and separate the ions (solvation) [1]."]], "3": [["Q4", "Largest gain at 0.0; isotonic between 0.2 and 0.4 (≈0.33); 0.6 is hypertonic; water is hypotonic."], ["Q5", "The cylinders have slightly different starting masses [1]; % change allows the results to be compared fairly [1]."], ["Q6", "Standard error bars show how reliable each mean is [1]; if bars for two concentrations overlap, the difference between those means may not be significant [1]."]], "4": [["Q7", "RBC in water: bursts. RBC in strong salt: crenates. Onion in water: turgid. Onion in strong sucrose: plasmolysis. RBC in 0.9% saline: no change."], ["Q8", "Plant cells have a strong cellulose cell wall [1]; as water enters, turgor pressure builds against the wall, which resists further expansion and stops bursting; animal cells have no wall, so they swell and lyse [1]."], ["Q9", "An isotonic solution has the same solute concentration as the cells, so there is no net water movement [1]; cells do not swell/burst or shrink, so the organ is not damaged [1]."]], "5": [["Q10", "Fresh water is hypotonic to the cytoplasm [1]; so water continually enters the cell by osmosis [1]; the contractile vacuole collects excess water and expels it (using ATP), preventing the cell from bursting [1]."]], "6": [["Exit ticket", "Lower solute concentration than the cell. Plant cell: water enters, becomes turgid. Animal cell: water enters, swells and bursts."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_1": "Q5", "q3_2": "Q6", "q4_1": "Q8", "q4_2": "Q9", "q5_0": "Q10", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
