insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-D23-L2', 'D2.3 Water potential · Lesson 2 (HL): Water potential, solute potential and pressure potential', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 3, "n": 3, "ans": ["From A to B", "From B to A", "From A to B"], "tip": "From higher (less negative) to lower (more negative)."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["−300", "−700", "0", "−1000"], "tip": "Add them, keeping the signs."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 3, "pts": [["lower water potential", "more negative", "solution+lower"], ["water leaves", "out of the cell", "osmosis"], ["pressure potential+zero", "pressure potential falls", "flaccid", "plasmolys"]], "tips": ["Compare ψw, direction of water, then what happens to ψp."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 2, "pts": [["600", "-600", "−600"], ["y to x", "from y", "into x", "y+x"]], "tips": ["Work out both ψw values first."]}]}, "models": {"1": [["Q1", "Differences in the potential energy of water, caused by solutes and pressure, make water move from higher to lower water potential."]], "2": [["Q2", "−200 → −500: A to B. −300 → −800: B to A. 0 → −400: A to B."]], "3": [["Q3", "−700 + 400 = −300; −700 + 0 = −700; −600 + 600 = 0; −200 + (−800) = −1000."]], "4": [["Q4", "The solution has a lower (more negative) water potential than the cell [1]; water leaves the cell by osmosis [1]; pressure potential falls to zero, the cell becomes flaccid and the membrane pulls away from the wall (plasmolysis) [1]."]], "5": [["Q5", "X: −900 + 300 = −600 kPa; Y: −700 + 400 = −300 kPa [1]; water moves from Y (higher ψw) to X (lower ψw) [1]."]], "6": [["Exit ticket", "ψw = ψs + ψp; pure water at atmospheric pressure and 20 °C has ψw = 0 kPa."]]}, "labels": {"q1_0": "Q1", "q4_0": "Q4", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'b41f1865-24b3-5e1f-9f64-6d799d8ba92b', (select id from public.topics where programme = 'IB DP' and code = 'C2.1' limit 1), 'C2.1 Chemical signalling · Lesson 1 (HL): Receptors, ligands, quorum sensing and types of signalling chemicals', 'IB DP Biology · C2.1 Chemical signalling', '/c21-lesson1/', 'DP1-C21-L1', 17, 211 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-C21-L1', 'C2.1 Chemical signalling · Lesson 1 (HL): Receptors, ligands, quorum sensing and types of signalling chemicals', '{"marks": {"2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 3, "pts": [["autoinducer", "signalling chemical", "release"], ["dense", "population", "concentration+high", "threshold", "many bacteria"], ["genes", "luciferase", "light", "transcription"]], "tips": ["Signal released → concentration depends on numbers → genes switched on."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Hormone", "Neurotransmitter", "Cytokine", "Calcium ion"], "tip": "Distance and source."}, {"kind": "choice", "id": "q3_1", "q": "Q4", "max": 4, "n": 4, "ans": ["Amine", "Protein", "Steroid", "Steroid"], "tip": "Steroids are lipids."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 3, "pts": [["plasma membrane", "membrane+cytoplasm", "cytoplasm", "nucleus"], ["hydrophobic amino acids", "hydrophobic region", "amino acids"], ["outside", "enters", "penetrat", "steroid", "hydrophilic ligand", "cannot cross"]], "tips": ["Location, amino acids, whether the ligand enters."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 3, "pts": [["both+receptor", "both bind", "both+specific"], ["blood", "distant", "far"], ["synapse", "local", "short distance", "fast"]], "tips": ["One similarity, two differences."]}]}, "models": {"1": [["Q1", "Only cells with insulin receptors on their membrane (e.g. liver, muscle, fat cells) can bind insulin and respond."]], "2": [["Q2", "Each bacterium releases an autoinducer signalling chemical [1]; only when the population density is high does its concentration exceed a threshold [1]; it binds to receptors and switches on genes for luciferase, so the bacteria emit light together [1]."]], "3": [["Q3", "Insulin: hormone. Acetylcholine: neurotransmitter. Interleukin: cytokine. Inside the neuron: calcium ion."], ["Q4", "Adrenaline: amine. Insulin: protein. Testosterone and oestradiol: steroids."]], "4": [["Q5", "Transmembrane receptors are in the plasma membrane; intracellular receptors are in the cytoplasm or nucleus [1]; transmembrane receptors have a region of hydrophobic amino acids within the membrane, intracellular receptors are hydrophilic on the surface [1]; ligands of transmembrane receptors stay outside the cell, while ligands of intracellular receptors (e.g. steroids) penetrate the membrane [1]."]], "5": [["Q6", "Both are signalling chemicals that bind to specific receptors on target cells [1]; hormones travel in the blood to distant targets [1]; neurotransmitters diffuse across a synapse, acting locally and much faster [1]."]], "6": [["Exit ticket", "The signalling chemical that binds a receptor. Steroids are hydrophobic, so they diffuse through the membrane to receptors inside."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q2", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'ed12ed97-6cfc-503a-b2b3-4da8613bc0d7', (select id from public.topics where programme = 'IB DP' and code = 'C2.1' limit 1), 'C2.1 Chemical signalling · Lesson 2 (HL): Signal transduction: ion channels, G proteins, tyrosine kinase, steroids and feedback', 'IB DP Biology · C2.1 Chemical signalling', '/c21-lesson2/', 'DP1-C21-L2', 23, 212 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-C21-L2', 'C2.1 Chemical signalling · Lesson 2 (HL): Signal transduction: ion channels, G proteins, tyrosine kinase, steroids and feedback', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["Step 1", "Step 2", "Step 3", "Step 4", "Step 5"], "tip": "Outside → membrane → inside."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["channel+open", "opens", "ion channel"], ["positive", "sodium", "na", "depolari", "voltage"]], "tips": ["What does the receptor contain, and what moves through it?"]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 4, "n": 4, "ans": ["Insulin", "Adrenaline", "Oestradiol", "Progesterone"], "tip": "Two proteins/amines, two steroids."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 3, "pts": [["receptor", "binds", "tyrosine kinase"], ["phosphorylat", "tyrosine"], ["vesicle", "glut4", "transporter", "glucose transporters"]], "tips": ["Bind → phosphorylation → transporters."]}, {"kind": "text", "id": "q3_2", "q": "Q6", "max": 2, "pts": [["intracellular", "inside", "cytoplasm", "diffuse through"], ["dna", "transcription", "gene"]], "tips": ["Where is the receptor, and what does the complex bind to?"]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q7", "max": 4, "n": 4, "ans": ["Negative", "Positive", "Negative", "Positive"], "tip": "Opposes = negative; amplifies = positive."}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 3, "pts": [["adrenaline+outside", "does not enter", "first messenger", "receptor"], ["adenylyl cyclase", "atp", "produced"], ["kinase", "amplif", "inside", "glycogen"]], "tips": ["First messenger outside, second messenger inside."]}]}, "models": {"1": [["Q1", "1 × 10 × 10 × 100 = 10 000 cAMP molecules: the signal is amplified."]], "2": [["Q2", "Bind receptor → activate G protein → adenylyl cyclase makes cAMP → protein kinases → glycogen breakdown."], ["Q3", "Binding opens an ion channel that is part of the receptor [1]; positively charged ions (Na⁺) diffuse into the cell, depolarising the membrane (changing the voltage) [1]."]], "3": [["Q4", "Tyrosine kinase: insulin. G protein/cAMP: adrenaline. Hypothalamus GnRH: oestradiol. Endometrium: progesterone."], ["Q5", "Insulin binds to a transmembrane receptor with tyrosine kinase activity [1]; this causes phosphorylation of tyrosine inside the cell, starting a sequence of reactions [1]; vesicles containing glucose transporters move to and fuse with the plasma membrane, increasing glucose uptake [1]."], ["Q6", "The steroid diffuses through the membrane and binds to an intracellular receptor, activating it [1]; the hormone–receptor complex binds to specific DNA sequences and promotes transcription of target genes [1]."]], "4": [["Q7", "Insulin and opposing: negative. Oxytocin and amplifying: positive."]], "5": [["Q8", "Adrenaline (first messenger) binds to the receptor outside and does not enter the cell [1]; via a G protein, adenylyl cyclase converts ATP to cAMP inside the cell [1]; cAMP carries the signal inside, activating protein kinases and amplifying the response (glycogen breakdown) [1]."]], "6": [["Exit ticket", "Cyclic AMP (cAMP); a transmembrane receptor with tyrosine kinase activity."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_1": "Q5", "q3_2": "Q6", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'add9c4cb-04c6-5930-a3e8-5a36f8dcd586', (select id from public.topics where programme = 'IB DP' and code = 'C2.2' limit 1), 'C2.2 Neural signalling · Lesson 1: Neurons, resting potential, nerve impulses and synapses', 'IB DP Biology · C2.2 Neural signalling', '/c22-lesson1/', 'DP1-C22-L1', 21, 221 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-C22-L1', 'C2.2 Neural signalling · Lesson 1: Neurons, resting potential, nerve impulses and synapses', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 3, "n": 3, "ans": ["Cell body", "Axon", "Dendrite"], "tip": "One long, many short."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 3, "pts": [["3+2", "three+two", "more positive", "more na"], ["k+leak", "potassium+leak", "potassium+diffuse", "k diffuse out", "potassium out", "more permeable"], ["negative+proteins", "proteins", "organic anions", "negatively charged"]], "tips": ["The pump, leaking ions and what stays inside."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Strong positive", "64%", "Strong negative", "Increases speed"], "tip": "R² is a proportion."}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q4", "max": 5, "n": 5, "ans": ["Step 1", "Step 2", "Step 3", "Step 4", "Step 5"], "tip": "Calcium comes before exocytosis."}, {"kind": "text", "id": "q4_1", "q": "Q5", "max": 2, "pts": [["vesicle+presynaptic", "only the presynaptic", "neurotransmitter+presynaptic", "released from the presynaptic"], ["receptor+postsynaptic", "receptors only", "only the postsynaptic"]], "tips": ["Where are the vesicles, where are the receptors?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 4, "pts": [["calcium", "ca"], ["exocytosis", "vesicles fuse", "released"], ["diffuse", "cleft"], ["receptor", "binds"], ["sodium", "na", "depolari"]], "tips": ["From the arrival of the impulse to the postsynaptic membrane (any four steps)."]}]}, "models": {"1": [["Q1", "Nucleus: cell body. Long single fibre: axon. Many short fibres: dendrites."]], "2": [["Q2", "The Na⁺/K⁺ pump moves 3 Na⁺ out for every 2 K⁺ in, so more positive charge leaves [1]; K⁺ leaks out through open channels (the membrane is more permeable to K⁺ than Na⁺) [1]; negatively charged proteins remain inside the cell [1]."]], "3": [["Q3", "r = +0.9: strong positive. R² = 0.64 → 64%. r = −0.85: strong negative. Myelin increases speed."]], "4": [["Q4", "Depolarisation → Ca²⁺ in → exocytosis of ACh → ACh binds receptors → Na⁺ in, EPSP."], ["Q5", "Neurotransmitter is stored in vesicles only in the presynaptic neuron [1]; receptors are only on the postsynaptic membrane, so the signal can only pass from pre to post [1]."]], "5": [["Q6", "Depolarisation causes Ca²⁺ to enter the presynaptic neuron [1]; vesicles release acetylcholine by exocytosis [1]; acetylcholine diffuses across the synaptic cleft [1]; it binds to receptors, opening channels so Na⁺ enters and the postsynaptic membrane depolarises [1]."]], "6": [["Exit ticket", "About −70 mV (inside negative). Calcium ions."]]}, "labels": {"q2_0": "Q2", "q4_1": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '38f6c302-e2bc-5eb4-bf22-4849b474fd40', (select id from public.topics where programme = 'IB DP' and code = 'C2.2' limit 1), 'C2.2 Neural signalling · Lesson 2 (HL): Action potentials in detail, oscilloscope traces and saltatory conduction', 'IB DP Biology · C2.2 Neural signalling', '/c22-lesson2/', 'DP1-C22-L2', 15, 222 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-C22-L2', 'C2.2 Neural signalling · Lesson 2 (HL): Action potentials in detail, oscilloscope traces and saltatory conduction', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 6, "n": 6, "ans": ["−70 mV", "−50 mV", "+30 mV", "Na⁺ channels open", "K⁺ channels open", "Hyperpolarisation"], "tip": "Rise = Na⁺ in; fall = K⁺ out."}, {"kind": "choice", "id": "q2_1", "q": "Q3", "max": 1, "n": 1, "ans": ["30 Hz"], "tip": "12 ÷ 0.4."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 3, "pts": [["sodium+diffuse", "na diffuse", "local current"], ["threshold", "next region", "adjacent"], ["channels open", "voltage-gated", "sodium channels"]], "tips": ["Ions spread → next region reaches threshold → channels open."]}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 3, "pts": [["insulat", "myelin"], ["node", "ranvier"], ["jump", "saltatory", "node to node"]], "tips": ["Where can ions cross?"]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q6", "max": 2, "pts": [["sodium channels+open", "voltage-gated sodium", "na channels open"], ["all or nothing", "no action potential", "below threshold"]], "tips": ["What happens at threshold, and if it is not reached?"]}]}, "models": {"1": [["Q1", "Signals do not fade or vary in size as they travel; information is carried by the frequency of impulses, which is reliable."]], "2": [["Q2", "−70 mV resting; −50 mV threshold; +30 mV peak; rise from Na⁺ channels; fall from K⁺ channels; dip = hyperpolarisation."], ["Q3", "12 ÷ 0.4 = 30 impulses per second."]], "3": [["Q4", "Na⁺ ions entering at a depolarised region diffuse along the axon, creating local currents [1]; this raises the membrane potential of the adjacent region to threshold [1]; voltage-gated Na⁺ channels there open, so the action potential moves along [1]."], ["Q5", "Myelin insulates the axon so ions cannot cross there [1]; channels and pumps are clustered at the nodes of Ranvier [1]; the action potential jumps from node to node (saltatory conduction), covering the distance faster [1]."]], "4": [["Q6", "When the membrane reaches threshold, voltage-gated Na⁺ channels open and an action potential follows [1]; if threshold is not reached, no action potential occurs (all-or-nothing) [1]."]], "6": [["Exit ticket", "Voltage-gated Na⁺ (depolarisation) and voltage-gated K⁺ (repolarisation); at the nodes of Ranvier."]]}, "labels": {"q1_0": "Q1", "q3_0": "Q4", "q3_1": "Q5", "q4_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '76888ad7-8bed-572a-a31f-18202f20b9ba', (select id from public.topics where programme = 'IB DP' and code = 'C2.2' limit 1), 'C2.2 Neural signalling · Lesson 3 (HL): Drugs and pesticides, inhibitory synapses, summation, pain and consciousness', 'IB DP Biology · C2.2 Neural signalling', '/c22-lesson3/', 'DP1-C22-L3', 19, 223 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-C22-L3', 'C2.2 Neural signalling · Lesson 3 (HL): Drugs and pesticides, inhibitory synapses, summation, pain and consciousness', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Cocaine", "Neonicotinoid", "Neonicotinoid", "Cocaine"], "tip": "One blocks receptors; one blocks reuptake."}, {"kind": "text", "id": "q1_1", "q": "Q2", "max": 3, "pts": [["acetylcholine receptor", "nicotinic"], ["not broken down", "acetylcholinesterase", "cannot be removed"], ["block", "paralys"]], "tips": ["Binding, breakdown, effect."]}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Does not fire", "Fires", "Does not fire", "Fires"], "tip": "Need +15 mV in total."}, {"kind": "text", "id": "q2_1", "q": "Q4", "max": 2, "pts": [["hyperpolari", "more negative"], ["further from threshold", "less likely", "harder", "prevents"]], "tips": ["Direction of the membrane potential change and its effect."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q5", "max": 3, "pts": [["capsaicin"], ["channel", "positive ions", "free nerve ending"], ["brain", "threshold", "impulse", "perceived"]], "tips": ["Chemical → channels → impulses → brain."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q7", "max": 3, "pts": [["reuptake", "re-uptake"], ["dopamine"], ["remains", "stays", "accumulat", "overstimulat", "longer"]], "tips": ["Which neurotransmitter, which process, what result?"]}]}, "models": {"1": [["Q1", "Reuptake and longer in synapse: cocaine. Insect ACh receptors and pesticide: neonicotinoid."], ["Q2", "Neonicotinoids bind to nicotinic acetylcholine receptors at insect synapses [1]; they are not broken down by acetylcholinesterase [1]; so synaptic transmission is blocked, causing paralysis and death [1]."]], "2": [["Q3", "2 EPSPs: −60 (no). 4 EPSPs: −50 (fires). 4 EPSPs + 2 IPSPs: −60 (no). 5 EPSPs + 1 IPSP: −50 (fires)."], ["Q4", "It makes the postsynaptic membrane hyperpolarised (more negative) [1]; moving it further from threshold, so an action potential is less likely [1]."]], "3": [["Q5", "Capsaicin binds to and opens channels for positive ions in free nerve endings [1]; positive ions enter, reaching threshold [1]; impulses travel to the brain, which perceives heat/pain [1]."], ["Q6", "It arises from the interactions of many neurons and is not a property of any single neuron; the whole has properties its parts do not."]], "4": [["Q7", "Cocaine blocks reuptake [1] of dopamine into the presynaptic neuron [1]; dopamine stays in the synaptic cleft longer, continuously stimulating the postsynaptic neuron [1]."]], "6": [["Exit ticket", "An IPSP hyperpolarises the postsynaptic membrane (further from threshold); an EPSP depolarises it (closer to threshold)."]]}, "labels": {"q1_1": "Q2", "q2_1": "Q4", "q3_0": "Q5", "q3_1": "Q6", "q4_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '35df0e25-d31e-5c72-bf33-5bd8f6e3f748', (select id from public.topics where programme = 'IB DP' and code = 'C3.1' limit 1), 'C3.1 Integration of body systems · Lesson 1: System integration, nerves and hormones, the brain and the spinal cord', 'IB DP Biology · C3.1 Integration of body systems', '/c31-lesson1/', 'DP1-C31-L1', 20, 241 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-C31-L1', 'C3.1 Integration of body systems · Lesson 1: System integration, nerves and hormones, the brain and the spinal cord', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["Nervous", "Endocrine", "Nervous", "Endocrine", "Endocrine"], "tip": "Speed vs duration."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 3, "pts": [["impulse", "electrical", "neuron"], ["hormone", "blood"], ["fast+slow", "faster", "slower", "longer"]], "tips": ["How, by what route, how fast/long."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 4, "n": 4, "ans": ["Sensory neuron", "Motor neuron", "Brain", "Spinal cord"], "tip": "Input, output, two integrating centres."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["aware", "voluntary", "decide", "control"], ["reflex", "heart", "breathing", "without awareness", "automatic", "involuntary"]], "tips": ["Awareness and control."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q6", "max": 3, "pts": [["sheath", "connective tissue", "protective"], ["bundle", "fibres", "axons"], ["myelin"]], "tips": ["Outside, inside, two kinds of fibre."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 3, "pts": [["transport", "carries"], ["glucose", "oxygen", "urea", "hormone", "heat"], ["liver", "lungs", "kidney", "muscle"]], "tips": ["What is carried, from which organ, to which organ?"]}]}, "models": {"1": [["Q1", "E.g. running a marathon: it needs the muscles, skeleton, heart, lungs, nerves and hormones working together; no single organ can do it alone."]], "2": [["Q2", "Impulses, faster: nervous. Blood, longer-lasting, hormones: endocrine."], ["Q3", "The nervous system sends electrical impulses along neurons [1]; the endocrine system sends hormones in the blood [1]; nervous messages are faster and short-lived, hormonal messages slower and longer-lasting [1]."]], "3": [["Q4", "Receptor → CNS: sensory neuron. To muscle: motor neuron. Learning: brain. Reflexes: spinal cord."], ["Q5", "Conscious processes are ones we are aware of and control, e.g. choosing to pick up a pen [1]; unconscious processes happen without awareness, e.g. a reflex or control of heart rate [1]."]], "4": [["Q6", "A protective sheath of connective tissue surrounds the nerve [1]; inside are bundles of nerve fibres of sensory and motor neurons [1]; some fibres are myelinated and some unmyelinated [1]."]], "5": [["Q7", "The blood transports materials and energy between organs [1]; e.g. glucose from the liver, O₂ from the lungs, urea and hormones [1]; e.g. urea from the liver to the kidneys, O₂ from lungs to muscles, so organs can depend on each other [1]."]], "6": [["Exit ticket", "The spinal cord; motor neurons."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_1": "Q5", "q4_0": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '96ebe95f-e48e-58d7-afc8-ab50f723b6f8', (select id from public.topics where programme = 'IB DP' and code = 'C3.1' limit 1), 'C3.1 Integration of body systems · Lesson 2: Reflexes, cerebellum, melatonin, adrenaline, hypothalamus and feedback control', 'IB DP Biology · C3.1 Integration of body systems', '/c31-lesson2/', 'DP1-C31-L2', 27, 242 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-C31-L2', 'C3.1 Integration of body systems · Lesson 2: Reflexes, cerebellum, melatonin, adrenaline, hypothalamus and feedback control', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["1", "2", "3", "4", "5"], "tip": "Receptor to effector."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["Cerebellum", "Melatonin", "Adrenaline", "Melatonin"], "tip": "One brain region, two hormones."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 3, "pts": [["heart rate", "heart"], ["glucose", "glycogen"], ["airway", "ventilation", "breathing", "blood to muscles", "dilate", "oxygen"]], "tips": ["Heart, fuel, oxygen supply (any three effects)."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 4, "n": 4, "ans": ["Baroreceptor", "Chemoreceptor", "Medulla", "Hypothalamus"], "tip": "Pressure, chemistry, two brain regions."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 4, "pts": [["carbon dioxide", "co2"], ["ph+fall", "ph decreases", "acid", "lower ph"], ["chemoreceptor"], ["diaphragm", "intercostal", "medulla", "brainstem"]], "tips": ["CO₂ → pH → detection → muscles."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 4, "n": 4, "ans": ["CNS", "ENS", "CNS", "ENS"], "tip": "Start and end are voluntary."}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 3, "pts": [["baroreceptor"], ["aorta", "carotid"], ["medulla", "brainstem"], ["increase", "faster", "stroke volume"]], "tips": ["Receptor, location, centre, response."]}]}, "models": {"1": [["Q1", "Receptor → sensory neuron → interneuron → motor neuron → muscle."]], "2": [["Q2", "Balance: cerebellum. Night, sleep–wake: melatonin. Fight or flight: adrenaline."], ["Q3", "Adrenaline increases heart rate and stroke volume [1]; it causes glycogen in the liver to be broken down, raising blood glucose [1]; it widens the airways and increases ventilation / diverts blood to muscles, supplying more O₂ for contraction [1]."]], "3": [["Q4", "Pressure: baroreceptor. pH/CO₂: chemoreceptor. Heart and breathing control: medulla. Pituitary control: hypothalamus."], ["Q5", "Muscles respire faster, producing more CO₂ [1]; CO₂ dissolves forming carbonic acid, lowering blood pH [1]; chemoreceptors in the brainstem detect the fall in pH [1]; the medulla sends impulses to the diaphragm and intercostal muscles to increase breathing rate and depth [1]."]], "4": [["Q6", "Swallowing and egestion: CNS. Peristalsis along the gut: ENS."]], "5": [["Q7", "Baroreceptors [1] in the aorta and carotid arteries detect the fall in pressure [1]; they send impulses to the medulla, which sends impulses to the heart to increase heart rate and stroke volume, raising pressure (negative feedback) [1]."]], "6": [["Exit ticket", "In the aorta and carotid arteries; the pineal gland."]]}, "labels": {"q2_1": "Q3", "q3_1": "Q5", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'd109d888-5d3b-5e2d-a54e-b44422d742a1', (select id from public.topics where programme = 'IB DP' and code = 'C3.1' limit 1), 'C3.1 Integration of body systems · Lesson 3 (HL): Tropisms and plant hormones', 'IB DP Biology · C3.1 Integration of body systems', '/c31-lesson3/', 'DP1-C31-L3', 20, 243 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP1-C31-L3', 'C3.1 Integration of body systems · Lesson 3 (HL): Tropisms and plant hormones', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Qualitative", "Quantitative", "Qualitative", "Quantitative"], "tip": "Numbers = quantitative."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 4, "pts": [["shaded", "dark side", "away from the light"], ["efflux", "carrier", "transport"], ["h+", "hydrogen ion", "acid", "apoplast"], ["elongat", "faster", "grow more"]], "tips": ["Where auxin goes, how, what it does, and the result."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Auxin", "Cytokinin", "Ethylene", "Auxin"], "tip": "Roots make cytokinin."}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 3, "pts": [["ethylene", "ethene"], ["more ethylene", "stimulates production", "positive feedback", "increases"], ["rapid", "synchron", "same time", "together"]], "tips": ["The loop, and why fast and together is useful."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 3, "pts": [["one side", "unilateral", "lamp", "box with a hole"], ["angle", "curvature", "protractor", "measure"], ["control", "same", "repeat", "several"]], "tips": ["Set-up, measurement, fair test/reliability."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 2, "pts": [["one side", "same side"], ["active", "pump", "cell to cell", "concentrated"]], "tips": ["Where are the carriers, and what results?"]}]}, "models": {"1": [["Q1", "Drawing and description: qualitative. Angle and length: quantitative."]], "2": [["Q2", "Auxin is moved to the shaded side of the shoot [1] by auxin efflux carriers positioned on that side of the cells [1]; auxin promotes H⁺ secretion into the cell walls, loosening cross-links between cellulose [1]; cells on the shaded side elongate more, so the shoot bends towards the light [1]."]], "3": [["Q3", "Shoot tips and shaded side: auxin. Root tips: cytokinin. Ripening gas: ethylene."], ["Q4", "Ethylene stimulates ripening [1]; ripening fruit produce more ethylene, which speeds ripening further (positive feedback) [1]; so fruits ripen rapidly and at the same time, attracting animals to disperse seeds [1]."]], "4": [["Q5", "Grow seedlings in a box with light entering from one side only, with a control group in uniform light [1]; measure the angle of curvature after a set time with a protractor/image analysis [1]; keep species, age, temperature and water the same and use many seedlings to calculate a mean [1]."]], "5": [["Q6", "Efflux carriers are positioned on the same side of each cell [1]; auxin is actively pumped out on that side and diffuses into the next cell, so it is transported from cell to cell and concentrated in one region [1]."]], "6": [["Exit ticket", "Auxin; ethylene (ethene)."]]}, "labels": {"q2_0": "Q2", "q3_1": "Q4", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '3369f62c-d3a6-5a3f-a28b-a0a0e2315262', (select id from public.topics where programme = 'IB DP' and code = 'C3.2' limit 1), 'C3.2 Defence against disease · Lesson 1: Pathogens, barriers, clotting and the immune system', 'IB DP Biology · C3.2 Defence against disease', '/c32-lesson1/', 'DP-C32-L1', 28, 251 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP-C32-L1', 'C3.2 Defence against disease · Lesson 1: Pathogens, barriers, clotting and the immune system', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Virus", "Bacterium", "Protist", "Fungus"], "tip": "Plasmodium is a single-celled eukaryote."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["1", "2", "3", "4"], "tip": "Fibrin is the last protein made."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Innate", "Adaptive", "Innate", "Adaptive"], "tip": "Specific + memory = adaptive."}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 3, "pts": [["amoeboid", "move", "leave the blood", "squeeze"], ["engulf", "endocytosis"], ["lysosome", "digest", "enzymes"]], "tips": ["Move, engulf, digest."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q5", "max": 5, "n": 5, "ans": ["1", "2", "3", "4", "5"], "tip": "Activation before cloning."}, {"kind": "text", "id": "q4_1", "q": "Q6", "max": 3, "pts": [["mitosis", "divide", "multiply"], ["clone", "plasma"], ["same antibody", "specific", "large amounts", "secrete"]], "tips": ["Few B-cells match each antigen."]}, {"kind": "text", "id": "q4_2", "q": "Q7", "max": 2, "pts": [["memory cells"], ["rapid", "faster", "quickly", "before symptoms"]], "tips": ["What is left after the first infection?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 3, "pts": [["broad", "non-specific", "general"], ["specific"], ["memory", "does not change", "more effective"]], "tips": ["Range of targets and change over life."]}]}, "models": {"1": [["Q1", "HIV: virus. TB: bacterium. Malaria: protist. Athlete''s foot: fungus."]], "2": [["Q2", "Clotting factors → thrombin → fibrinogen to fibrin → clot."]], "3": [["Q3", "Broad and phagocytes: innate. Memory and specific antibodies: adaptive."], ["Q4", "Phagocytes move by amoeboid movement out of capillaries to the site of infection [1]; they recognise and engulf pathogens by endocytosis [1]; lysosomes fuse with the vesicle and their enzymes digest the pathogen [1]."]], "4": [["Q5", "Antigen recognition → helper T activates B → clone by mitosis → plasma cells secrete antibodies → memory cells remain."], ["Q6", "Only a few B-cells match each antigen, so activated B-cells divide by mitosis [1]; forming a clone of plasma cells [1]; which all secrete the same specific antibody in large amounts [1]."], ["Q7", "Memory cells specific to measles antigens remain after the first infection [1]; on re-infection they rapidly produce large amounts of antibody, eliminating the virus before symptoms develop [1]."]], "5": [["Q8", "The innate system responds to broad categories of pathogen [1]; the adaptive system responds specifically to particular pathogens [1]; the innate system does not change during life, while the adaptive system builds up memory, so responses become more effective [1]."]], "6": [["Exit ticket", "Plasma cells (activated B-cells); memory cells."]]}, "labels": {"q3_1": "Q4", "q4_1": "Q6", "q4_2": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'ded5f710-16d1-54f8-b74d-f72b0540d736', (select id from public.topics where programme = 'IB DP' and code = 'C3.2' limit 1), 'C3.2 Defence against disease · Lesson 2: HIV, antibiotics, zoonoses, vaccines, herd immunity and COVID-19 data', 'IB DP Biology · C3.2 Defence against disease', '/c32-lesson2/', 'DP-C32-L2', 19, 252 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('DP-C32-L2', 'C3.2 Defence against disease · Lesson 2: HIV, antibiotics, zoonoses, vaccines, herd immunity and COVID-19 data', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 3, "pts": [["lymphocyte", "helper t"], ["antibod", "immune response"], ["opportunistic", "other infections"]], "tips": ["Which cells, what is lost, what follows."]}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["no metabolism", "host cell", "inside cells", "own metabolism", "no cell wall", "no ribosomes"], ["nothing to block", "processes", "not affected", "cannot target"]], "tips": ["What do antibiotics target? Do viruses have it?"]}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 3, "pts": [["mutation", "random"], ["susceptible+killed", "survive", "selection"], ["reproduce", "pass on", "frequency", "plasmid"]], "tips": ["Variation → selection → reproduction."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 4, "n": 4, "ans": ["Animal bite", "Mosquito", "Milk or close contact with cattle", "Airborne between humans after the initial spillover"], "tip": "Vectors, bites, food."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 3, "pts": [["mrna", "codes for", "antigen"], ["cells make", "translated", "protein"], ["memory"]], "tips": ["Code → antigen → immune response → memory."]}, {"kind": "text", "id": "q4_1", "q": "Q6", "max": 2, "pts": [["most people immune", "high percentage", "large proportion", "enough people"], ["transmission", "cannot spread", "fewer hosts", "less likely"]], "tips": ["Who can the pathogen infect?"]}], "5": [{"kind": "choice", "id": "q5_0", "q": "Q7", "max": 2, "n": 2, "ans": ["−75%", "40%"], "tip": "Change ÷ original; difference ÷ mean."}]}, "models": {"1": [["Q1", "HIV infects and destroys helper T-lymphocytes [1]; so fewer B-cells are activated and antibody production falls [1]; the person cannot fight opportunistic infections, which is AIDS [1]."]], "2": [["Q2", "Viruses have no metabolism or cell structures of their own (no cell wall, no ribosomes), using the host cell''s processes [1]; so there are no bacterial processes for antibiotics to block [1]."], ["Q3", "Random mutations give some bacteria resistance [1]; when antibiotics are used, susceptible bacteria die and resistant ones survive (natural selection) [1]; survivors reproduce and pass on resistance genes (also via plasmids), so resistance becomes more frequent [1]."]], "3": [["Q4", "Rabies: bite. Japanese encephalitis: mosquito. Bovine TB: milk/cattle. COVID-19: spread between humans after spillover."]], "4": [["Q5", "The vaccine contains mRNA coding for a pathogen antigen [1]; body cells translate it and make the antigen protein, which triggers an immune response [1]; memory cells are produced, giving immunity without the disease [1]."], ["Q6", "When a high percentage of the population is immune [1], the pathogen cannot easily spread from person to person, so unvaccinated people are less likely to meet it [1]."]], "5": [["Q7", "(2000 − 8000) ÷ 8000 × 100 = −75%. |120 − 80| ÷ 100 × 100 = 40%."]], "6": [["Exit ticket", "COVID-19 is caused by a virus, which has no bacterial processes to block. Vaccines contain antigens or nucleic acids coding for antigens."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q2", "q2_1": "Q3", "q4_0": "Q5", "q4_1": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
